	-- The protection check, written once. The Extensions pane shows the full report and the Execute
	-- button asks this same function before the script runs, so the two can never disagree about the
	-- same source. Markers are matched as plain text, never as patterns: a packer writes these
	-- strings into its output, and a script that merely mentions one is reported, never blocked.
	local PROTECTION_MARKERS = {
		{ "LPH_", "Luraph marker in the text", "high" },
		{ "luraph", "Luraph marker in the text", "high" },
		{ "Luarmor", "Luarmor lock", "high" },
		{ "gethwid", "locked to a hardware id", "high" },
		{ "HWID", "locked to a hardware id", "high" },
		{ "Warlock", "Warlock protector", "high" },
		{ "MoonSec", "MoonSec obfuscator", "high" },
