		{ "Prometheus", "Prometheus obfuscator", "medium" },
		{ "hookmetamethod", "hooks engine metamethods", "medium" },
		{ "hookfunction", "hooks engine functions", "medium" },
		{ "setreadonly", "rewrites engine tables", "medium" },
		{ "getrawmetatable", "reads engine internals", "low" },
		{ "loadstring", "builds code while it runs", "medium" },
		{ "game:HttpGet", "downloads code from a URL", "medium" },
		{ "https://", "names a web address", "low" },
