	function api.protectionScan(src)
		if type(src) ~= "string" or #src == 0 then
			return nil, "nothing to scan"
		end
		local lines, longest, urls = 0, 0, 0
		-- One pass for the per-line facts, then ONE whole-buffer search per marker. The old shape asked
		-- every marker of every line: 6000 lines x 18 markers measured 338 ms on a 105 KB script before
		-- the player's code had even compiled (work/test_scan_cost.js). The same findings and the
		-- same first-line reporting, from 18 byte scans instead of 108 thousand small function calls.
		for line in (src .. "\n"):gmatch("([^\n]*)\n") do
			lines = lines + 1
			if #line > longest then
				longest = #line
			end
			if line:find("http", 1, true) then
				urls = urls + 1
			end
		end
		local findings = {}
		for _, m in ipairs(PROTECTION_MARKERS) do
			local at = src:find(m[1], 1, true)
			if at then
				local _, nl = src:sub(1, at):gsub("\n", "")
				findings[#findings + 1] = { label = m[2], sev = m[3], line = nl + 1 }
			end
		end
		-- reported in the order the player reads them: first line first, as the per-line walk produced
		table.sort(findings, function(a, b) return a.line < b.line end)
		local worst = "none"
		for _, f in ipairs(findings) do
			if PROTECTION_RANK[f.sev] > PROTECTION_RANK[worst] then
				worst = f.sev
			end
		end
		if longest > 800 then
			findings[#findings + 1] = {
				label = "one line of " .. longest .. " characters (packed output)",
				sev = "high",
				line = 0,
			}
			worst = "high"
		end
		-- A size that rounds to zero says nothing, so under a kilobyte the byte count is the report
		-- and above it one decimal is enough. The tenths are computed by hand because the engine's
		-- number formatting is not the one the offline gate runs.
		local size
		if #src < 1024 then
			size = #src .. " B"
		else
			local tenths = math.floor((#src / 1024) * 10 + 0.5)
			size = tostring(math.floor(tenths / 10)) .. "." .. tostring(tenths % 10) .. " KB"
		end
