		if worst == "high" then
			verdict = "packed or locked to this device, so it may refuse to run"
		elseif worst == "medium" then
			verdict = "not packed, but it touches the engine or loads remote code"
		elseif worst == "low" then
			verdict = "no protection markers, only low-risk mentions"
		else
			verdict = "no protection markers, which is not a guarantee that it behaves"
		end
