			lines = lines,
			bytes = #src,
			size = size,
			urls = urls,
			findings = findings,
			worst = worst,
			verdict = verdict,
		}
	end
	function api.execute(src, tabName)
		if type(src) ~= "string" or #src == 0 then
			return false, "nothing to run"
		end
		-- The protection check runs before the script does, on the same source the script will see.
		-- It reports; it never blocks: the owner runs scripts that fetch code, and a check that
		-- refused to run them would be worse than no check at all. The autoexec channel stays
		-- quiet, because those are our own files and a line per boot would push the player's own
		-- output down the pane.
		local scan = api.protectionScan(src)
		if scan and tabName ~= "auto" and type(api.log) == "function" then
			pcall(api.log, "Protection: " .. scan.verdict .. " (" .. scan.lines .. " lines, "
				.. scan.size .. ")")
		end
		-- Luau renamed this. Whichever one this engine exposes is the one that compiles the buffer.
		local compile = loadstring or load
		if type(compile) ~= "function" then
			return false, "this engine has no loadstring/load"
		end
		-- One compile per script, not two. The wrapper below is the shape we actually run, so the
		-- raw source is compiled only when that shape is refused; the fallback still reports the
		-- engine's own message. Compiling both doubled every Execute and every autoexec file.
		-- A main executor's console shows what the script said. Without this the Output pane can only
		-- repeat the panel's own messages, which is a log of the UI rather than of the player's script.
		-- The shadow environment must inherit from the chunk's OWN environment, not from getgenv(): this
		-- engine injects writefile/gethui/etc into the chunk env, so basing the table on getgenv made
		-- every injected global disappear from the player's script (Execute ran and then failed on a nil
		-- writefile, which looked like the button not working).
		local captured = 0
		local function capture(...)
			captured = captured + 1
			local parts = {}
			for i = 1, select("#", ...) do
				parts[#parts + 1] = tostring(select(i, ...))
			end
			if type(api.log) == "function" then -- api, never CROZIX: that local does not exist inside its own initialiser
				pcall(api.log, table.concat(parts, "  "))
			end
		end
		-- setfenv cannot redirect these globals: Luau keeps them in the chunk's own environment, so the
		-- call reports success and changes nothing (the tablet recorded applied=true captured=0 while the
		-- script's print still reached the real console). Passing print in as a parameter does not depend
		-- on the environment at all, and the prefix sits on the first line so error line numbers match.
		local runner, mode = nil, "plain"
		-- The chunk gets a name. Without one, a runtime error quotes our wrapper source straight
		-- back at the player - the message begins [string "return function(print, ...)] instead of
		-- naming the script they ran. The loader names its chunk; now Execute does the same.
		local tag = "[Crozix " .. tostring(tabName or "script") .. "]"
		local wrapped = compile("return function(print, ...) " .. src .. "\nend", tag)
		if wrapped then
			local factory = wrapped()
			if type(factory) == "function" then
				runner, mode = factory, "printarg"
			end
		end
		if not runner then
			-- The wrapper was refused - a syntax error in the script, or an engine that will not take
			-- the shape. Only here is the raw source compiled, so a script that runs costs exactly
			-- one compile, and a broken one still reports the engine message without our prefix.
			local chunk, compileErr = compile(src, tag)
			if not chunk then
				return false, "error: " .. tostring(compileErr)
			end
			runner = chunk
		end
		-- The stacking rules change the moment a script is about to draw: take the baseline now, and keep
		-- the panel one above whatever the script builds.
		pcall(api.armRise)
		local ok, err = pcall(runner, (mode == "printarg") and capture or nil)
		pcall(writefile, "Crozix/print_capture.txt",
			string.format("mode=%s captured=%d\n", mode, captured))
		if not ok then
			return false, "stopped: " .. tostring(err)
		end
		return true, "executed"
	end

	-- Two themes, one file apart. Delta's own surfaces measure 99.6% neutral (its darkest panel is
	-- rgb(38,50,59), a cool graphite), and its colour appears only where something is selected. Our first
	-- build tinted every surface red and outlined every card in rgb(235,60,72), which is why it read as a
	-- gaming skin instead of a tool. Graphite is therefore the default: red stays the brand (the square,
	-- the edge glow, the active state), it just stops being the wallpaper.
	-- One ladder for everything that is not a colour. Before this there was no radius table at all
	-- and the file used 13 different corner values across 42 sites, which is the difference between
	-- a designed surface and a pile of rounded rectangles.
	api.D = {
		R = { XS = 8, SM = 12, MD = 16, LG = 22, PILL = 999 },
		SP = { XS = 8, SM = 12, MD = 16, LG = 24 },
		TYPE = { Title = 18, Section = 15, Body = 12, Caption = 11, Code = 12,
		-- the key-screen wordmark is not a UI text level. Named here so the ladder check has nothing
		-- to forgive; the boot card's own 18px glyph is reported by the gate, not hidden from it.
		Wordmark = 40 },
		MOTION = { Open = 0.22, Section = 0.18, TabRule = 0.3, Press = 0.09, State = 0.14, Glow = 1.6 },
		HIT = 44,
	}

	api.THEMES = {
		graphite = {
			-- Surface ladder: window, card, in-card element. Each step is a level of depth, not a
			-- shade someone liked, and no surface that carries text is translucent.
			-- Measured 2026-11-01: the old card sat 1.08:1 above the window and the editor 1.11:1
			-- below it, which is under the ~1.15 a layered surface needs to read as depth, so the
			-- panel looked like one flat sheet with lines drawn on it. The card moved up two steps;
			-- the editor did not move, so the same edit opened both rungs at once.
			PanelTop = { 26, 26, 26 }, PanelBottom = { 9, 9, 9 }, Card = { 45, 45, 45 },
			Editor = { 14, 14, 14 }, Stroke = { 96, 96, 96 }, StrokeSoft = { 68, 68, 68 },
			-- 214,36,55 rather than 229,40,60: a white label on the old red measured 4.47:1, under
			-- the 4.5 the brief's legibility floor asks for, and every state of the primary button
			-- now clears it. Glow stays the brighter brand red -- it is light, not text.
			Accent = { 214, 36, 55 }, AccentDeep = { 183, 27, 42 }, AccentHover = { 226, 44, 62 },
			Glow = { 229, 40, 60 },
			Text = { 240, 238, 236 }, TextSecondary = { 203, 200, 197 }, Muted = { 176, 172, 168 },
			TextMuted = { 160, 160, 160 },
			Red = { 248, 110, 110 }, Green = { 70, 168, 120 }, Yellow = { 226, 174, 32 },
			Dark = { 23, 23, 23 },
			FabFill = { 45, 45, 45 },
			CardLift = { 60, 60, 60 },
		},
		crimson = {
			PanelTop = { 44, 18, 24 }, PanelBottom = { 11, 6, 8 }, Card = { 54, 32, 38 },
			Editor = { 16, 9, 11 }, Stroke = { 104, 52, 60 }, StrokeSoft = { 78, 42, 48 },
			Accent = { 214, 36, 55 }, AccentDeep = { 183, 27, 42 }, AccentHover = { 226, 44, 62 },
			Glow = { 229, 40, 60 },
			Text = { 240, 236, 238 }, TextSecondary = { 208, 190, 194 }, Muted = { 188, 168, 172 },
			TextMuted = { 156, 138, 142 },
			Red = { 248, 110, 110 }, Green = { 70, 168, 120 }, Yellow = { 226, 174, 32 },
			Dark = { 40, 24, 28 },
			FabFill = { 54, 32, 38 },
			CardLift = { 65, 44, 50 },
