	-- One file decides the palette, and one read answers for every surface. The loader paints before
	-- the reference's own theme call, so without this it kept the crimson it was written with while
	-- the window it was loading was graphite -- the same product, two colours, at every join.
	function api.activeTheme()
		if api.themeName ~= nil then
			return api.themeName
		end
		local name = "graphite"
		pcall(function()
			if type(isfile) == "function" and type(readfile) == "function" and isfile("Crozix/theme.txt") then
				local want = tostring(readfile("Crozix/theme.txt")):gsub("%s", ""):lower()
				if api.THEMES[want] then
					name = want
				end
			end
		end)
		api.themeName = name
		return name
	end

	function api.palette()
		local out = {}
		for k, v in pairs(api.THEMES[api.activeTheme()]) do
			if type(v) == "table" then
				out[k] = Color3.fromRGB(v[1], v[2], v[3])
			end
		end
		return out
	end

	function api.theme(T)
		local t = api.THEMES[api.activeTheme()]
		local applied = 0
		for k, v in pairs(t) do
			if type(v) == "table" then
				T[k] = Color3.fromRGB(v[1], v[2], v[3])
				applied = applied + 1
			end
		end
		api.themeApplied = applied
		return api.activeTheme()
	end

	-- Lite is the default. The brief names the weak device as the target, so the top-lit strokes, the
	-- card sheen, the button glow and the breathing edge all wait for the player to ask for them; the
	-- press scale and the tweens stay, because those are what make a touch feel answered.
	api.EFFECTS = { glass = true }
	function api.effectsOn()
		return api.EFFECTS.glass == true
	end

	-- Every costly layer registers itself here. Toggling Glass is then one property write per layer
	-- instead of rebuilding the tree, so a player flips it and sees it on the same screen.

	api.effectLayers = {}
	function api.trackEffect(layer)
		table.insert(api.effectLayers, layer)
		layer.Enabled = api.EFFECTS.glass == true
		return layer
	end
	-- The breathing edge is the one motion that repeats forever, so it gets its own list rather than
	-- riding on every costly layer. A glow is still registered with the registry Lite switches off.
	api.glowLayers = {}
	function api.trackGlow(layer)
		table.insert(api.glowLayers, layer)
		return api.trackEffect(layer)
	end

	function api.applyEffects()
		for _, layer in ipairs(api.effectLayers) do
			if layer.Parent then layer.Enabled = api.EFFECTS.glass == true end
		end
	end

	api.SAVEFILE = "Crozix/saved.json"
	-- This engine's JSONEncode writes any keyed table as [] -- Save reported success and persisted
	-- nothing. Saved scripts use a length-prefixed text format instead, so the encoder has no say in
	-- what survives. The JSON branch below only reads files written before that change.
	local NL = string.char(10)
	local function decodeSaved(raw)
		if string.sub(raw, 1, 8) ~= "CROZIXS1" or string.sub(raw, 9, 9) ~= NL then
			local out = {}
			local ok, dec = pcall(function()
				return realGame:GetService("HttpService"):JSONDecode(raw)
			end)
			if ok and type(dec) == "table" then
				for k, v in pairs(dec) do
					if type(k) == "string" and type(v) == "string" then
						out[k] = v
					end
				end
			end
			return out
		end
		local out = {}
		local i = 10
		local function take()
			local digits = string.match(raw, "^%d+", i)
			if not digits then
				return nil
			end
			local n = tonumber(digits)
			i = i + #digits + 1
			local chunk = string.sub(raw, i, i + n - 1)
			i = i + n + 1
			return chunk
		end
		while i <= #raw do
			local name = take()
			local content = take()
			if not name or not content then
				break
			end
			out[name] = content
		end
		return out
	end

	local function encodeSaved(all)
		local parts = { "CROZIXS1" .. NL }
		for name, content in pairs(all) do
			if type(name) == "string" and type(content) == "string" then
				parts[#parts + 1] = #name .. NL .. name .. NL
				parts[#parts + 1] = #content .. NL .. content .. NL
			end
		end
		return table.concat(parts)
	end

	local function readSaved()
		local raw = nil
		pcall(function()
			if isfile and isfile(api.SAVEFILE) then
				raw = readfile(api.SAVEFILE)
			end
		end)
		if type(raw) ~= "string" then
			return nil
		end
		return decodeSaved((string.gsub(raw, string.char(13) .. NL, NL)))
	end

	local function writeSaved(all)
		return pcall(writefile, api.SAVEFILE, encodeSaved(all))
	end

	function api.load(into)
		local all = readSaved()
		if not all then
			return 0
		end
		local n = 0
		for name, content in pairs(all) do
			into[name] = content
			n = n + 1
		end
		return n
	end

	function api.save(name, content)
		if type(name) ~= "string" or type(content) ~= "string" then
			return false
		end
		local all = readSaved() or {}
		all[name] = content
		if not writeSaved(all) then
			return false
		end
		-- Read the payload back: reporting success for a file that does not hold the script is exactly
		-- how Save looked functional while persisting nothing.
		local back = readSaved()
		return back ~= nil and back[name] == content
	end

	-- Deleting a row in his list must delete it on disk too, otherwise the script comes back on the
	-- next join and the button looks broken.
	function api.forget(name)
		if type(name) ~= "string" then
			return false
		end
		local all = readSaved()
		if not all or all[name] == nil then
			return false
		end
		all[name] = nil
		if not writeSaved(all) then
			return false
		end
		local back = readSaved()
		return back ~= nil and back[name] == nil
	end

api.KEYFILE = "Crozix/key.txt"

	function api.readKey()
		local raw = nil
		pcall(function()
			if isfile and isfile(api.KEYFILE) then
				raw = readfile(api.KEYFILE)
			end
		end)
		if type(raw) ~= "string" then
			return nil
		end
		raw = raw:gsub("^%s+", ""):gsub("%s+$", "")
		if #raw == 0 or #raw > 256 then
			return nil
		end
		return raw
	end

	function api.writeKey(key)
		if type(key) ~= "string" or #key == 0 then
			return false
		end
		local ok = pcall(writefile, api.KEYFILE, key)
		return ok and true or false
	end

	-- The engine's own file API, so a PNG the owner drops into the workspace becomes a real asset
	-- without an upload. Returns "" when the file is not there, which makes every caller fall back to
	-- what the reference already draws.
	local function localAsset(rel)
		local have = false
		pcall(function()
			have = isfile ~= nil and isfile(rel) == true
		end)
		if not have then
			return ""
		end
		local url = nil
		pcall(function()
			url = getcustomasset ~= nil and getcustomasset(rel) or nil
		end)
		if type(url) ~= "string" or #url == 0 then
			return ""
		end
		return url
	end

	-- The panel paints two things from files rather than from vectors: the CROZIX mark in the rail and
	-- the soft shadow under the window. Both go through the head's existing guard, which returns an
	-- empty string when the file is not on the device, so a missing asset hides one label instead of
	-- throwing on every widget that asks for it.
	-- A caller names a file inside the asset folder; it is not a path. The icons, the rail monogram
	-- and the window shadow all live in Crozix/icons/, and a bare name asked of isfile() resolves at
	-- the workspace root, where the asset can never be and the panel quietly paints nothing.
	api.ASSET_DIR = "Crozix/icons/"
	function api.asset(name)
		return localAsset(api.ASSET_DIR .. name)
	end

	-- A caller that already holds the whole workspace-relative path - the Script Hub's cached
	-- thumbnails do - needs the same guard without the icons folder glued onto the front.
	function api.assetAt(rel)
		return localAsset(rel)
	end

	api.LOGO_FILE = "Crozix/logo.png"

	function api.logoAsset()
		return localAsset(api.LOGO_FILE)
	end

	-- Every icon name the panel asks for lives in one registry, spliced in here so the slot list, the
	-- request document and the panel cannot drift apart. The owner drops Crozix/icons/<name>.png; the
	-- loading glow waits for each file that exists, and the drawn icon stays the fallback for the rest.
	-- ONE ICON REGISTRY. Before this table there were three separate answers to "which marks does this
	-- panel paint": a slot list for the rail and editor, a second drawn-glyph renderer inside the
	-- Extensions store, and the store's own category map. An image could therefore replace a rail icon
	-- and never reach the same mark two sections away, and the owner's request document could not list
	-- half the icons the UI actually drew.
	--
	-- This is the single source of truth. Every row is one file the owner may drop into
	-- Crozix/icons/; the panel reads this table to know which files to look for, which ones keep their
	-- own colours, and which drawn fallback paints until the file exists. The `section` and `element`
	-- columns are the audit trail: work/icon_registry_check.js fails the build when a name is drawn in
	-- code but missing here, when a row here is never painted, or when ui/ICON_REQUESTS_V7.md and this
	-- table disagree.
	--
	-- `drawn` names the fallback renderer, not a file: "icon" is Icon.new's vector defs, "mk" is the
	-- Extensions store's glyph kit. Both honour Config.Icons[name] first, so one PNG changes both.
	api.ICON_SPEC = {
		-- ---- navigation rail + top bar ------------------------------------------------------------
		{ name = "code", file = "code.png", section = "Rail / Scripts", element = "Editor rail icon, Scripts tab, script-type rows" },
		{ name = "search", file = "search.png", section = "Rail / Script Hub", element = "Script Hub rail icon, hub search field, Search button" },
		{ name = "save", file = "save.png", section = "Rail / Scripts", element = "Scripts rail icon, Scripts header, Save button" },
		{ name = "ai", file = "ai.png", section = "Rail / AI", element = "AI rail icon and AI empty state (60px)", keep = true },
		{ name = "extensions", file = "extensions.png", section = "Rail / Extensions", element = "Extensions rail icon and extension rows" },
		{ name = "settings", file = "settings.png", section = "Rail / Settings", element = "Settings rail icon and section rows" },
		{ name = "output", file = "output.png", section = "Rail / Consoles", element = "Consoles rail icon and Crozix Console empty state" },
		{ name = "import", file = "import.png", section = "Rail", element = "Rail collapse button (panel to floating button)" },
		{ name = "chevron", file = "chevron.png", section = "Top bar / Extensions", element = "Top bar hide-window chevron and the extensions sort rows" },
		{ name = "link", file = "link.png", section = "Key screen / Community", element = "Get-key link button and the Community card corner" },
		{ name = "key", file = "key.png", section = "Key screen", element = "Key input field" },
		{ name = "arrow", file = "arrow.png", section = "Key screen", element = "Login button" },

		-- ---- editor + console actions --------------------------------------------------------------
		{ name = "play", file = "play.png", section = "Editor / Extensions", element = "Execute button and the EXECUTE SCRIPT action pill" },
		{ name = "trash", file = "trash.png", section = "Editor / Consoles", element = "Clear button and both console Clear buttons" },
		{ name = "copy", file = "copy.png", section = "Consoles", element = "Copy button on the Crozix and Roblox consoles" },
		{ name = "bolt", file = "bolt.png", section = "Editor", element = "AutoExec button", keep = true },
		{ name = "pencil", file = "pencil.png", section = "Editor", element = "Edit mark on a saved script" },
		{ name = "close", file = "close.png", section = "Tabs / dialogs / Scripts", element = "Tab close, dialog close, delete-saved close" },
		{ name = "plus", file = "plus.png", section = "Editor / Extensions", element = "New tab button and the Add Custom Extension button" },
		{ name = "refresh", file = "refresh.png", section = "Settings / Scripts", element = "Reset to defaults and the Scripts refresh control" },

		-- ---- status widget ------------------------------------------------------------------------
		{ name = "fps", file = "fps.png", section = "Status widget", element = "FPS column" },
		{ name = "ping", file = "ping.png", section = "Status widget", element = "Ping column" },
		{ name = "players", file = "players.png", section = "Status widget", element = "Players column" },
		{ name = "info", file = "info.png", section = "Status widget / Extensions", element = "Status card corner and the extensions empty state" },

		-- ---- Extensions store: filters, chips, categories -----------------------------------------
		{ name = "grid", file = "grid.png", section = "Extensions", element = "ALL filter pill and the add-item placeholder tile" },
		{ name = "puzzleMini", file = "puzzleMini.png", section = "Extensions", element = "EXTENSIONS filter pill" },
		{ name = "user", file = "user.png", section = "Extensions", element = "MY ITEMS filter pill and the USER chip" },
		{ name = "crown", file = "crown.png", section = "Extensions / Scripts", element = "BUILT-IN chip" },
		{ name = "puzzle", file = "puzzle.png", section = "Extensions", element = "Add Custom Extension path card" },
		{ name = "dashedPlus", file = "dashedPlus.png", section = "Extensions", element = "Empty add-item tile" },
		{ name = "sortDown", file = "sortDown.png", section = "Extensions", element = "Sort pill and its open menu" },
		{ name = "arrowLeft", file = "arrowLeft.png", section = "Extensions", element = "Back button in the add-extension form" },
		{ name = "check", file = "check.png", section = "Extensions", element = "Selected row in the sort menu" },
		{ name = "bulb", file = "bulb.png", section = "Extensions", element = "Extensions and Addons banner" },

		-- ---- Extensions store: item marks ----------------------------------------------------------
		{ name = "speedo", file = "speedo.png", section = "Extensions", element = "FPS Boost item tile, Performance category" },
		{ name = "keyboard", file = "keyboard.png", section = "Extensions", element = "Virtual Keyboard item tile, Input category" },
		{ name = "rocket", file = "rocket.png", section = "Extensions", element = "Auto Rejoin item tile, Automation category" },
		{ name = "shieldCheck", file = "shieldCheck.png", section = "Extensions", element = "Script Checker item tile, Analysis category" },
		{ name = "shieldScan", file = "shieldScan.png", section = "Extensions", element = "Scan Protection item tile, Security category, ANALYZE pill" },
		{ name = "shield", file = "shield.png", section = "Extensions", element = "SCAN SCRIPT action pill" },
		{ name = "terminal", file = "terminal.png", section = "Extensions", element = "Compile Check item tile, Code Analysis category, CHECK CODE pill" },
		{ name = "cube", file = "cube.png", section = "Extensions", element = "RUN EXTENSION pill, Interface category" },
	}

	-- A row's `drawn` is derived rather than typed twice: the main renderer owns the marks the rail,
	-- editor and status widget ask for, and the Extensions kit owns the store's own glyphs. The check
	-- script compares this split against the code, so a name that moves between renderers is caught.
	local MK_ONLY = {
		arrowLeft = true, bulb = true, check = true, crown = true, cube = true, dashedPlus = true,
		grid = true, keyboard = true, puzzle = true, puzzleMini = true, rocket = true, shield = true,
		shieldCheck = true, shieldScan = true, sortDown = true, speedo = true, terminal = true, user = true,
	}
	for _, row in ipairs(api.ICON_SPEC) do
		row.drawn = MK_ONLY[row.name] and "mk" or "icon"
	end

	-- name -> row, so a caller can ask what a slot is for without walking the list.
	local ICON_BY_NAME = {}
	for _, row in ipairs(api.ICON_SPEC) do
		ICON_BY_NAME[row.name] = row
	end

	function api.iconSpec(name)
		return ICON_BY_NAME[name]
	end

	-- Files whose PNG keeps the colours it was drawn with instead of being flattened to one tint.
	-- Derived from the same rows, so a new two-colour mark is one flag in one table.
	api.COLOR_ICONS = {}
	for _, row in ipairs(api.ICON_SPEC) do
		if row.keep == true then
			api.COLOR_ICONS[row.name] = true
		end
	end

	-- The files the loading glow waits for. A name with no file on the device is simply absent from
	-- this map, and the drawn fallback stays in place, so a partial batch is never a hole in the UI.
	-- The resolved URLs are kept on the adapter as well as handed to Config.Icons, because the head's
	-- own helpers cannot see the body's Config local and must not guess at it.
	api.ICONS = {}
	function api.iconAssets()
		local out, found = {}, 0
		for _, row in ipairs(api.ICON_SPEC) do
			local url = localAsset("Crozix/icons/" .. row.file)
			if url ~= "" then
				out[row.name] = url
				found = found + 1
			end
		end
		api.ICONS = out
		api.iconCount = found
		return out
	end

	-- The one image path both renderers share. Returns nil when the owner has not supplied the file,
	-- which is the signal to draw the fallback; a caller never has to know which renderer it uses.
	function api.iconImage(name, parent, size, color, props)
		local url = type(api.ICONS) == "table" and api.ICONS[name] or nil
		if type(url) ~= "string" or url == "" then
			return nil
		end
		local img = Instance.new("ImageLabel")
		img.Name = "Icon_" .. tostring(name)
		img.Image = url
		img.BackgroundTransparency = 1
		img.ScaleType = Enum.ScaleType.Fit
		img.Size = UDim2.fromOffset(size, size)
		for p, v in pairs(props or {}) do
			img[p] = v
		end
		local keep = api.COLOR_ICONS[name] == true
		if not keep and color ~= nil then
			img.ImageColor3 = color
		end
		img.Parent = parent
		local obj = { Root = img }
		function obj.SetColor(c)
			if not keep then
				img.ImageColor3 = c
			end
		end
		return obj
	end

	-- True only when this engine can actually run a buffer. The reference holds its key screen and its
	-- loading glow until this answers yes, so the glow is a real wait and not a countdown.
	function api.engineReady()
		local runnable = false
		pcall(function()
			runnable = type(loadstring) == "function" or type(load) == "function"
		end)
		return runnable
	end

	-- A loading screen with measured stages. step() is called from between the reference's own section
	-- banners, so the bar advances on work that really happened and the milliseconds are elapsed time,
	-- not a scripted countdown.
	local STAGES = { "client", "ui", "present" }
	local done, trace, started, parts, gui = {}, {}, nil, nil, nil

	local function paint(current)
		if not parts then
			return
		end
		local n, nextName = 0, nil
		for _, s in ipairs(STAGES) do
			if done[s] then
				n = n + 1
			elseif not nextName then
				nextName = s
			end
		end
		pcall(function()
			parts.fill.Size = UDim2.new(n / #STAGES, 0, 1, 0)
			parts.count.Text = n .. " / " .. #STAGES
			parts.status.Text = current and ("loading " .. current) or (nextName and ("loaded - next: " .. nextName) or "ready")
			parts.time.Text = string.format("%.0f ms", (clock() - (started or clock())) * 1000)
		end)
	end

	function api.buildLoader()
		started = clock()
		local P = api.palette()
		local function mk(cls, props, parent)
			local i = Instance.new(cls)
			for k, v in pairs(props) do
				i[k] = v
			end
			i.Parent = parent
			return i
		end
		gui = Instance.new("ScreenGui")
		gui.Name = "CrozixLoad"
		gui.ResetOnSpawn = false
		gui.IgnoreGuiInset = true
		gui.DisplayOrder = 1000
		local box = mk("Frame", {
			Size = UDim2.new(0, 320, 0, 92), AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, 0), BackgroundColor3 = P.PanelBottom,
			BorderSizePixel = 0,
		}, gui)
		mk("UICorner", { CornerRadius = UDim.new(0, api.D.R.MD) }, box)
		mk("TextLabel", {
			Text = "CROZIX", Font = Enum.Font.GothamBlack, TextSize = api.D.TYPE.Title,
			TextColor3 = P.Text, BackgroundTransparency = 1,
			Position = UDim2.new(0, 16, 0, 10), Size = UDim2.new(1, -32, 0, 24),
			TextXAlignment = Enum.TextXAlignment.Left,
		}, box)
		local status = mk("TextLabel", {
			Text = "starting", Font = Enum.Font.GothamMedium, TextSize = 11,
			TextColor3 = P.Muted, BackgroundTransparency = 1,
			Position = UDim2.new(0, 16, 0, 36), Size = UDim2.new(1, -32, 0, 14),
			TextXAlignment = Enum.TextXAlignment.Left,
		}, box)
		local track = mk("Frame", {
			BackgroundColor3 = P.Dark, BackgroundTransparency = 0.35,
			BorderSizePixel = 0, Position = UDim2.new(0, 16, 0, 56), Size = UDim2.new(1, -32, 0, 6),
		}, box)
		local fill = mk("Frame", {
			BackgroundColor3 = P.Accent, BorderSizePixel = 0,
			Size = UDim2.new(0, 0, 1, 0),
		}, track)
		local count = mk("TextLabel", {
			Text = "0 / 3", Font = Enum.Font.GothamMedium, TextSize = 11,
			TextColor3 = P.Muted, BackgroundTransparency = 1,
			Position = UDim2.new(0, 16, 0, 66), Size = UDim2.new(0.5, 0, 0, 14),
			TextXAlignment = Enum.TextXAlignment.Left,
		}, box)
		local time = mk("TextLabel", {
			Text = "0 ms", Font = Enum.Font.GothamMedium, TextSize = 11,
			TextColor3 = P.Muted, BackgroundTransparency = 1,
			Position = UDim2.new(0.5, 0, 0, 66), Size = UDim2.new(0.5, -16, 0, 14),
			TextXAlignment = Enum.TextXAlignment.Right,
		}, box)
		parts = { fill = fill, status = status, count = count, time = time }
		pcall(function()
			gui.Parent = api.hub()
		end)
		paint(nil)
	end

	function api.step(name)
		if name then
			done[name] = true
			trace[#trace + 1] = string.format("%s=ok t=%.1fms", name, (clock() - (started or clock())) * 1000)
		end
		paint(name)
		pcall(function()
			task.wait(0)
		end)
		paint(nil)
	end

	function api.finish(ok, err)
		api.step("present")
		-- The widgets the panel built, reachable from any other script. An executor's own UI is a
		-- surface the player can drive, and a harness that fires the real buttons proves the handlers
		-- without depending on this engine's touch-to-absolute coordinate mapping.
		pcall(function()
			getgenv().CrozixUI = api.hot
			getgenv().CrozixPanel = api
		end)
		pcall(function()
			if gui then
				gui:Destroy()
			end
		end)
		pcall(writefile, "Crozix/load_trace.txt", "6.0.0 " .. api.SOURCE_MD5 .. "\n"
			.. table.concat(trace, "\n") .. "\n")
		local report = "aliases=" .. tostring(api.aliasHits or 0) .. "\n" .. api.enumReport() .. "\n"
		if ok then
			pcall(writefile, "Crozix/panel_ok.txt", "6.0.0 built\n" .. report)
		else
			pcall(writefile, "Crozix/panel_error.txt", "6.0.0 build failed: " .. tostring(err)
				.. "\n" .. report)
		end
	end

	api.BUFFERFILE = "Crozix/buffer.txt"

	function api.loadBuffer()
		local raw = nil
		pcall(function()
			if isfile and isfile(api.BUFFERFILE) then
				raw = readfile(api.BUFFERFILE)
			end
		end)
		if type(raw) ~= "string" or #raw == 0 or #raw > 200000 then
			return nil
		end
		return raw
	end

	function api.saveBuffer(text)
		if type(text) ~= "string" then
			return false
		end
		return pcall(writefile, api.BUFFERFILE, text) and true or false
	end

	-- Delta runs the player's scripts when they join; a panel that makes them press Execute every time
	-- is a script, not an executor. One file, one obvious place: Crozix/auto.lua.
	-- AutoExec runs a folder, not the editor. The player keeps .lua files in Crozix/Autoexec --
-- a plain folder in the phone's own internal storage, reachable from any file manager -- and
-- pressing the pill runs everything in it, right then. The old shape snapshotted whatever was in
-- the editor when the pill was pressed and replayed that at the next join, which is neither a
-- folder a player can fill nor a button that does what its label says.
	api.AUTO_DIR = "Crozix/Autoexec"
	api.AUTOLOG = "Crozix/auto_run.txt"

-- Names whose PNG keeps the colours it was drawn with instead of being flattened to one tint.
	-- Derived from the icon registry at the top of this head (COLOR_ICONS there), so this line only
	-- records why the two-colour marks are special rather than restating their names.

-- listfiles is not uniform across executors: some hand back strings, some a table with a Name.
-- Either shape resolves to a path, and a folder the engine cannot list is simply an empty one.
	local function folderScripts()
		local paths = {}
		pcall(function()
			if type(listfiles) ~= "function" then
				return
			end
			local found = listfiles(api.AUTO_DIR)
			if type(found) ~= "table" then
				return
			end
			for _, item in ipairs(found) do
				local path = type(item) == "table" and (item.Name or item.Path) or item
				path = tostring(path or "")
				if path:match("%.lua$") then
					paths[#paths + 1] = path
				end
			end
		end)
		table.sort(paths)
		return paths
	end

-- Pressing the pill runs what is in the folder, now. The player sees the count in the toast, so the
-- button reports what the disk said rather than what it intended, and an empty folder is an honest
-- answer instead of a silent success.
	function api.autoRun()
		pcall(function()
			if type(makefolder) == "function" then
				makefolder(api.AUTO_DIR)
			end
		end)
		local files = folderScripts()
		local ran, failed = 0, {}
		for _, path in ipairs(files) do
			local raw = nil
			pcall(function()
				raw = readfile(path)
			end)
			if type(raw) == "string" and #raw > 0 then
				local ok, msg = api.execute(raw, "auto")
				if ok then
					ran = ran + 1
				else
					failed[#failed + 1] = tostring(msg)
				end
			end
		end
		local report = string.format("ran %d of %d\n", ran, #files)
		if #failed > 0 then
			report = report .. table.concat(failed, "; ") .. "\n"
		end
		pcall(writefile, api.AUTOLOG, report)
		if #files == 0 then
			return 0, 0, "No scripts in " .. api.AUTO_DIR
		end
		if ran == 0 then
			return 0, #files, "None of the " .. #files .. " scripts ran: " .. failed[1]
		end
		return ran, #files, nil
	end

	-- The device harness taps these numbers instead of guessing a button's place off a screenshot, and
	-- the file doubles as proof the widget exists with a real on-screen size and visibility. The widgets
	-- are read from a registry the panel fills in, not by walking the tree: this engine's
	-- GetDescendants came back with only two of seven widgets, and a report that quietly drops the
	-- ones that matter is worse than no report.
	api.hot = {}

	function api.register(name, inst)
		if type(name) == "string" and inst then
			api.hot[name] = inst
		end
	end

	-- The card at the top of the code pane used to read "Welcome to CROZIX!" under a CROZIX wordmark,
	-- with a marketing sentence that truncated itself. It is now the owner-named information widget,
	-- and its three readings are written by the live stats loop, so there is no title/subtitle writer
	-- left here to fight that loop.

	function api.hotspots(root, names)
		if not api.harness then
			return
		end
		local lines = {}
		-- AbsolutePosition is in Roblox's GUI space, which on this tablet is NOT the framebuffer the
		-- screenshot comes out of (1333x800 GUI vs 2000x1200 pixels). Without the ratio the harness
		-- taps in the wrong place, so the panel states its own viewport and the harness converts.
		local vx, vy = 0, 0
		pcall(function()
			local c = realGame:GetService("Workspace").CurrentCamera
			vx, vy = c.ViewportSize.X, c.ViewportSize.Y
		end)
		lines[#lines + 1] = string.format("viewport %.0fx%.0f", vx, vy)
		lines[#lines + 1] = "parent " .. tostring(api.parentUsed or "unknown")
		for _, n in ipairs(names or {}) do
			local inst = api.hot[n]
			if inst then
				local ok, a, s, vis = pcall(function()
					return inst.AbsolutePosition, inst.AbsoluteSize, inst.Visible
				end)
				if ok and a and s then
					lines[#lines + 1] = string.format(
						"%s cx=%.0f cy=%.0f w=%.0f h=%.0f visible=%s",
						n, a.X + s.X / 2, a.Y + s.Y / 2, s.X, s.Y, tostring(vis))
				else
					lines[#lines + 1] = n .. " UNREADABLE"
				end
			else
				lines[#lines + 1] = n .. " NOT REGISTERED"
			end
		end
		local text = table.concat(lines, "\n")
		pcall(writefile, "Crozix/hotspots.txt", text .. "\n")
		return text
	end

	-- Settings and the window's place are the app's, not the session's: Delta remembers where you left
	-- it, so a panel that resets every join reads as a script that re-ran.
	api.SETFILE = "Crozix/settings.json"

	function api.loadSettings(into)
		local raw = nil
		pcall(function()
			if isfile and isfile(api.SETFILE) then
				raw = readfile(api.SETFILE)
			end
		end)
		if type(raw) ~= "string" or #raw == 0 then
			return 0
		end
		local d = nil
		pcall(function()
			d = realGame:GetService("HttpService"):JSONDecode(raw)
		end)
		if type(d) ~= "table" then
			return 0
		end
		local n = 0
		if type(d.Smart) == "boolean" then
			into.Smart = d.Smart
			n = n + 1
		end
		if type(d.Scale) == "number" then
			into.Scale = math.max(0.4, math.min(1.5, d.Scale))
			n = n + 1
		end
		if type(d.Transparency) == "number" then
			into.Transparency = math.max(0, math.min(1, d.Transparency))
			n = n + 1
		end
		for _, k in ipairs({ "AntiAfk", "AntiScam", "NoRobux", "SafeTeleports" }) do
			if type(d[k]) == "boolean" then
				into[k] = d[k]
				n = n + 1
			end
		end
		local p = d.pos
		if type(p) == "table" and type(p[1]) == "number" and type(p[3]) == "number" then
			api.savedPos = p
			n = n + 1
		end
		return n
	end

	function api.saveSettings(settings, root)
		local pos = nil
		if root then
			local ok, p = pcall(function()
				return root.Position
			end)
			if ok and p then
				pos = { p.X.Scale, p.X.Offset, p.Y.Scale, p.Y.Offset }
			end
		end
		local encoded = nil
		pcall(function()
			local payload = {
				Smart = settings.Smart,
				Scale = settings.Scale,
				Transparency = settings.Transparency,
				pos = pos,
			}
			for _, k in ipairs({ "AntiAfk", "AntiScam", "NoRobux", "SafeTeleports" }) do
				if type(settings[k]) == "boolean" then
					payload[k] = settings[k]
				end
			end
			encoded = realGame:GetService("HttpService"):JSONEncode(payload)
		end)
		if type(encoded) ~= "string" then
			return false
		end
		pcall(writefile, api.SETFILE, encoded)
		return true
	end

	function api.applyWindowPos(root)
		local p = api.savedPos
		if type(p) ~= "table" then
			return false
		end
		pcall(function()
			root.Position = UDim2.new(p[1], p[2], p[3], p[4])
		end)
		return true
	end

	-- Where a finger has to land to press each widget. AbsolutePosition is design space and the
	-- UIScale is applied after it, so it is not a tap point on this engine. The engine's own hit-test
	-- is: sweep the viewport and ask GetGuiObjectsAtPosition what is under each point. What it answers
	-- is exactly where the player's tap has to go, in the same space as input.Position.
	function api.tapmap(names)
		if not api.harness then
			return
		end
		local vx, vy = 0, 0
		pcall(function()
			local c = realGame:GetService("Workspace").CurrentCamera
			vx, vy = c.ViewportSize.X, c.ViewportSize.Y
		end)
		if vx < 50 or vy < 50 then
			pcall(writefile, "Crozix/tapmap.txt", "no viewport\n")
			return
		end
		local base = nil
		pcall(function()
			base = api.gui and api.gui.Parent
		end)
		if base == nil then
			base = api.hub()
		end
		local lines, box = {}, {}
		-- The map is a background measurement, so it must not hold the frame: one hit-test measured about a
		-- millisecond on the tablet, and thousands of them in a row froze the game for seconds after a
		-- section switch. Two requests never overlap either; a second sweep would only repeat the first.
		if api.mapBusy then
			return
		end
		api.mapBusy = true
		api.mapCalls = 0
		local tMap = os.clock()
		local maxSlice, sliceStart = 0, tMap
		-- A map that does not say what it describes cannot be told apart from a stale one, and a stale map
		-- has already cost this harness several wrong conclusions.
		api.mapSeq = (api.mapSeq or 0) + 1
		-- The start is written down too: a sweep that is still running has to be visible as running,
		-- otherwise a pull in the middle of one looks like a map of the wrong section.
		pcall(writefile, "Crozix/tapmap.txt", string.format(
			"running seq %d section %s start_ms=%d names=%d\n",
			api.mapSeq, tostring(api.activeSection or "unknown"), math.floor(os.time() * 1000), #names))
		lines[#lines + 1] = string.format("seq %d section %s", api.mapSeq, tostring(api.activeSection or "unknown"))
		local step = 14
		local stepY = 12
		for y = stepY, vy - stepY, stepY do
			for x = step, vx - step, step do
				-- Yield every slice: a sweep that runs to the end without stopping is a freeze, and the
				-- engine runs this chunk on the thread that also renders. Twenty milliseconds of extra map
				-- time per frame is invisible next to a multi-second stop.
				api.mapCalls = api.mapCalls + 1
				if api.mapCalls % 16 == 0 then
					local sl = (os.clock() - sliceStart) * 1000
					if sl > maxSlice then
						maxSlice = sl
					end
					task.wait()
					sliceStart = os.clock()
				end
				local ok, objs = pcall(function()
					return base:GetGuiObjectsAtPosition(x, y)
				end)
				if ok and type(objs) == "table" then
					for _, o in ipairs(objs) do
						local node = o
						for _ = 1, 12 do
							if node == nil then
								break
							end
							for _, n in ipairs(names) do
								if node.Name == n then
									local b = box[n]
									if b == nil then
										box[n] = { x0 = x, x1 = x, y0 = y, y1 = y }
									else
										b.x0 = math.min(b.x0, x)
										b.x1 = math.max(b.x1, x)
										b.y0 = math.min(b.y0, y)
										b.y1 = math.max(b.y1, y)
									end
								end
							end
							node = node.Parent
						end
					end
				end
			end
		end
		lines[#lines + 1] = string.format("end_ms=%d elapsed_ms=%d calls=%d max_slice_ms=%d",
			math.floor(os.time() * 1000), math.floor((os.clock() - tMap) * 1000),
			api.mapCalls, math.floor(maxSlice))
		api.mapBusy = false
		-- The middle of the hit region, not the first sample that touched it: the corner is inside the
		-- button but it is also the place where a neighbour or a rounded edge can miss.
		for _, n in ipairs(names) do
			local b = box[n]
			if b then
				lines[#lines + 1] = string.format("tap %s %.0f %.0f %.0f %.0f", n, (b.x0 + b.x1) / 2, (b.y0 + b.y1) / 2, b.x0, b.x1)
			else
				lines[#lines + 1] = string.format("miss %s", n)
			end
		end
		local text = #lines == 0 and "nothing hit" or table.concat(lines, "\n")
		pcall(writefile, "Crozix/tapmap.txt", text .. "\n")
	end

	-- One HTTP path for the whole panel: the host's request() when it provides one, the
	-- engine's HttpGet when it does not. The answer is a body or nothing -- a body that is not
	-- a non-empty string is a failure, so no caller can paint an empty answer as a result.
	-- The caller keeps its own threading, because when a request runs is the caller's decision:
	-- the script library defers, the keyboard defers, the experience search spawns.
	api.httpGet = function(url)
		local ok, body = pcall(function()
			if type(request) == "function" then
				local r = request({ Url = url, Method = "GET" })
				if type(r) == "table" then
					return r.Body
				end
				return r
			end
			return realGame:HttpGet(url)
		end)
		if not ok or type(body) ~= "string" or #body == 0 then
			return false, nil
		end
		return true, body
	end
	return api
end)()

-- Declared before the reference body so his own reads of Enum, and of nothing else, resolve through
-- the adapter. game, Instance and every service stay the engine's.
local Enum = CROZIX.enum

-- v6 design tokens, additive only: the v5 ladder (D.R / D.SP / D.TYPE / D.MOTION / D.HIT) is
-- untouched. These name the sizes the redesign's components share so no magic numbers return.
CROZIX.D.H = { PILL = 32, TOUCH = 44, BAR = 52, ROW = 40, CHIP = 24 }
CROZIX.D.ICON = { SM = 14, MD = 16, LG = 18, RAIL = 20 }
CROZIX.PANEL_VERSION = "v6"
local function CROZIX_BUILD()
--[[
	ExecutorUI  |  Luau LocalScript
	-------------------------------------------------------------
	Put in: StarterGui (or StarterPlayerScripts) as a LocalScript.

	Flow (when there is no valid saved key):
	  1. Red animated light travelling around the DEVICE screen edges while assets load
	  2. Logo animation in the centre, then it moves aside
	  3. Key screen (24 Hours / 2 Days / 1 Week, get-link button, key box, login)
	  4. Sections slide in from the side of the screen, content opens on click
	     and every section change is animated.

	No universal key: validation delegates to Config.KeyBackend; with none wired the panel opens in local mode.
	Toggle: RightShift (or the floating button when hidden).
	No emojis anywhere: every icon is drawn with Frames (no assets needed).
]]

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")
local ContentProvider = game:GetService("ContentProvider")
local Stats = game:GetService("Stats")

local PlayerGui = Players.LocalPlayer:WaitForChild("PlayerGui")

------------------------------------------------------------------
-- CONFIG
------------------------------------------------------------------
local Config = {
	Title = "CROZIX",
	Subtitle = "EXECUTOR",
	WelcomeText = "Fast, clean, built for your games.",
	ToggleKey = Enum.KeyCode.RightShift,

	Links = {
		-- "Get it only at example.com" is the template's filler text. The product's own address is the
		-- first thing a main UI should say, and tapping it copies it.
		{ glyph = "W", color = Color3.fromRGB(226, 46, 60), text = "crozomods.xyz" },
	},

	-- Optional image ids for sidebar icons (Icons.search = "rbxassetid://123").
	-- Empty = the built-in drawn icon is used.
	-- Filled from Crozix/icons/<name>.png on the device: the owner drops the batch of PNGs into that
	-- folder and each one replaces its drawn icon with no code change. A name with no file keeps the
	-- drawn fallback, so a partial batch is never a hole in the UI.
	Icons = CROZIX.iconAssets(),
	ColorIcons = CROZIX.COLOR_ICONS,
	LogoImage = CROZIX.logoAsset(), -- Crozix/logo.png when it exists, "" when it does not
	Preload = {}, -- extra asset ids to preload during the loading glow

	-- KEY SYSTEM
	-- No placeholder destinations: real key links are supplied by the backend when one is wired.
	-- Empty is crash-safe (the Get-key handler falls back to "").
	KeyLinks = {},
	LoadSavedKey = function()
		return CROZIX.readKey()
	end,
	SaveKey = function(key)
		return CROZIX.writeKey(key)
	end,
	-- No universal key. Validation succeeds only against a real backend; with none wired the panel
	-- runs in local mode (see START) and this returns an honest failure instead of accepting "123".
	KeyBackend = nil, -- function(key) -> ok, message; wire a real server here to enable the key gate
	ValidateKey = function(key)
		if Config.KeyBackend then
			return Config.KeyBackend(key)
		end
		return false, "No key server connected"
	end,
	OnGetKey = nil, -- function(optionId, link)
	IsEngineReady = function()
		-- The glow ends when the engine can actually execute, so "loading" means waiting for
		-- something real rather than waiting for a timer.
		return CROZIX.engineReady()
	end,

	OpenFirstSection = true, -- open the Editor automatically after the sections slide in
	StartSection = "code",

	-- Hooks
	OnExecute = function(code, tabName)
		return CROZIX.execute(code, tabName)
	end,
	OnSave = function(name, content)
		return CROZIX.save(name, content)
	end,
	-- Left nil on purpose: his Open picker lists the saved table, and that table is seeded from disk
	-- below, so wiring OnOpen here would replace a working list with a single-file loader.
	OnOpen = nil, -- function() -> name, content
	OnSidebar = {}, -- e.g. OnSidebar.import = function() ... end
	HubSearch = nil, -- function(query) -> { {name=, desc=, code=}, ... }
	OnSettingsChanged = nil, -- function(settings)
}

local DESIGN_W, DESIGN_H = 700, 380
-- 0.15, not 0.4: at 40% the cards let a bright sky through and the labels lose contrast against it, which
-- is what made the glass read as a mock-up rather than a tool. The slider still goes down to full glass.
local Settings = { Smart = true, Scale = 1, Transparency = 0.15 }
-- Restored from Crozix/settings.json. A main app remembers how the player left it; having to re-drag
-- and re-size the window on every join is exactly what reads as "just a script that re-ran".
CROZIX.loadSettings(Settings)
CROZIX.settings = Settings

