	CROZIX.step("ui:theme")
-- THEME
------------------------------------------------------------------
local T = {
	PanelTop = Color3.fromRGB(26, 26, 26),
	PanelBottom = Color3.fromRGB(9, 9, 9),
	Card = Color3.fromRGB(45, 45, 45),
	Editor = Color3.fromRGB(14, 14, 14),
	Stroke = Color3.fromRGB(96, 96, 96),
	StrokeSoft = Color3.fromRGB(68, 68, 68),
	Accent = Color3.fromRGB(214, 36, 55),
	AccentHover = Color3.fromRGB(226, 44, 62),
	AccentDeep = Color3.fromRGB(183, 27, 42),
	Glow = Color3.fromRGB(229, 40, 60),
	Text = Color3.fromRGB(240, 238, 236),
	Code = Color3.fromRGB(255, 255, 255),
	TextSecondary = Color3.fromRGB(203, 200, 197),
	Muted = Color3.fromRGB(176, 172, 168),
	TextMuted = Color3.fromRGB(160, 160, 160),
	Red = Color3.fromRGB(248, 110, 110),
	Green = Color3.fromRGB(70, 168, 120),
	Yellow = Color3.fromRGB(226, 174, 32),
	Dark = Color3.fromRGB(23, 23, 23),
	FabFill = Color3.fromRGB(45, 45, 45),
	CardLift = Color3.fromRGB(60, 60, 60),
}

-- Applied before anything reads T, so every widget built below picks the theme up without knowing
-- about it. This is the whole difference between a red UI and a UI with a red brand.
CROZIX.theme(T)
T.Editor = T.Editor:Lerp(T.PanelBottom, 0.45)
T.Muted = T.Muted:Lerp(T.Text, 0.18)
T.TextMuted = T.TextMuted:Lerp(T.Text, 0.2)

-- The editor is one text layer, so there is one code colour and it is the theme's own text colour.
-- This used to be seven literals, six of which nothing read any more.
local SYN = {
	Default = T.Code,
}

------------------------------------------------------------------
	CROZIX.step("ui:helpers")
-- HELPERS
------------------------------------------------------------------
local function new(class, props, children)
	local inst = Instance.new(class)
	if inst:IsA("GuiObject") then
		inst.BorderSizePixel = 0
		inst.BackgroundTransparency = 1
	end
	if inst:IsA("GuiButton") then
		inst.AutoButtonColor = false
		inst.Text = ""
	end
	if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then
		inst.Font = Enum.Font.GothamMedium
		inst.TextSize = 12
		inst.TextColor3 = T.Text
	end
	local parent
	for k, v in pairs(props or {}) do
		if k == "Parent" then
			parent = v
		else
			inst[k] = v
		end
	end
	for _, c in ipairs(children or {}) do
		c.Parent = inst
	end
	inst.Parent = parent
	return inst
end

local function corner(parent, r)
	return new("UICorner", { CornerRadius = UDim.new(0, r), Parent = parent })
end

local function stroke(parent, color, thickness, transparency)
	return new("UIStroke", {
		Color = color,
		Thickness = thickness or 1,
		Transparency = transparency or 0,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = parent,
	})
end

function CROZIX.motionDuration(seconds)
	local ok, reduced = pcall(function() return game:GetService("GuiService").ReducedMotionEnabled end)
	if ok and reduced == true then return 0 end
	return seconds
end

local function tween(obj, t, props, style, dir)
	t = CROZIX.motionDuration(t)
	local tr = TweenService:Create(
		obj,
		TweenInfo.new(t, style or Enum.EasingStyle.Quad, dir or Enum.EasingDirection.Out),
		props
	)
	tr:Play()
	return tr
end
local tw = tween

local function hover(btn, normal, over, prop)
	prop = prop or "BackgroundColor3"
	local inside, selected = false, false
	local function paint()
		local active = inside or selected
		tw(btn, active and 0.14 or 0.1, { [prop] = active and over or normal })
	end
	btn.MouseEnter:Connect(function() inside = true; paint() end)
	btn.MouseLeave:Connect(function() inside = false; paint() end)
	if btn.SelectionGained and btn.SelectionLost then
		btn.SelectionGained:Connect(function() selected = true; paint() end)
		btn.SelectionLost:Connect(function() selected = false; paint() end)
	end
end

local function lighten(c, a)
	return c:Lerp(Color3.new(1, 1, 1), a)
end

-- glass (transparency setting) registry
local glassItems = {}
local function glassBase()
-- Bounded, and it only moves the shell behind the cards now. The old range let a surface
	-- reach 0.62 see-through, which is what read as soft text: the game showed through the
	-- letters. Surfaces that carry text are opaque; this leaves the frame behind them.
	return Settings.Transparency * 0.12
end
local function glass(inst, off, max)
	glassItems[#glassItems + 1] = { inst = inst, off = off or 0, max = max or 0.88 }
	inst.BackgroundTransparency = math.clamp(glassBase() + (off or 0), 0, max or 0.88)
end
-- The toast chip paints itself: it fades in and out on its own clock, so it cannot live in
-- glassItems, where every entry is re-applied verbatim and a fading card would be pulled back to
-- solid. It adds a settle hook instead, which is only asked to re-read the slider, and only while it
-- is on screen.
local glassSettle = {}
local function applyGlass()
	local b = glassBase()
	for _, g in ipairs(glassItems) do
		if g.inst.Parent then
			g.inst.BackgroundTransparency = math.clamp(b + g.off, 0, g.max)
		end
	end
	for _, f in ipairs(glassSettle) do
		f()
	end
end

-- A stroke that is uniform all round reads as a wireframe. The same stroke fading toward the
-- bottom reads as an edge catching light from above, and it costs one UIGradient on one UIStroke.
local function litStroke(parent, color, alpha)
	local s = stroke(parent, color, 1, alpha == nil and 0.3 or alpha)
	local g = new("UIGradient", {
		Rotation = 90,
		Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0),
			NumberSequenceKeypoint.new(1, 0.72),
		}),
		Parent = s,
	})
	CROZIX.trackEffect(g)
	return s
end

-- The surface itself, one step lighter at the top. strength is where the gradient starts.
local function sheen(f, strength, topLight)
	local g = new("UIGradient", {
		Rotation = 90,
		Transparency = NumberSequence.new(1 - (strength or 0.12), 1),
		Parent = f,
	})
	-- topLight is the surface catching light on its upper edge: one rung above the surface's own
	-- colour, fading back into it at the bottom. It is a token rather than arithmetic on the frame's
	-- colour because this engine's Color3 does not promise its channels can be read back.
	if topLight then
		g.Color = ColorSequence.new(topLight, f.BackgroundColor3)
	end
	CROZIX.trackEffect(g)
	return g
end

local function panel(parent, props, radius)
	local f = new("Frame", props)
	f.BackgroundColor3 = Color3.new(1, 1, 1)
	f.Parent = parent
	corner(f, radius or CROZIX.D.R.LG)
	new("UIGradient", {
		Rotation = 90,
		Color = ColorSequence.new(T.PanelTop, T.PanelBottom),
		Parent = f,
	})
	litStroke(f, T.Stroke, 0.45)
	-- v7.7: the plates follow the Transparency slider, as the reference always did. v7 cut this call to
	-- keep the game out of the labels and painted the shell to compensate; the cost was the two things
	-- the owner named: the rail moved and the window did not, and the header, the body and the rail
	-- stopped reading as three surfaces because one black plate sat behind all of them. The frame the
	-- three hang on is not painted at all -- new() leaves a GuiObject fully transparent -- so the gaps
	-- between the plates keep showing the game at 100 percent, and the slider moves the three plates
	-- together by the same 12 percent. Cards and the code well stay painted solid.
	glass(f, 0, 0.85)
	return f
end

local function card(parent, props)
	local f = new("Frame", props)
	f.BackgroundColor3 = T.Card
	f.Parent = parent
	corner(f, CROZIX.D.R.MD)
	litStroke(f, T.StrokeSoft, 0.34)
	-- The CardLift rung is the top light. A separate 1px line was tried first and the layout gate
	-- caught it painting over a button in the editor card; this costs no instance, cannot collide,
	-- and moves with the theme.
	sheen(f, 0.1, T.CardLift)
	-- v7: opaque. At 0.10 the game behind the window showed through every card as a grey copy of its
	-- own text, and that is what made the labels read soft. The lift sheen and the stroke carry the
	-- depth now, so closing the surface costs nothing.
	f.BackgroundTransparency = 0
	return f
end

------------------------------------------------------------------
-- ICONS (drawn with Frames, no emojis, no assets)
------------------------------------------------------------------
local Icon = {}

function Icon.new(name, parent, size, color, props)
	local k = size / 24
	local root = new("Frame", { Name = "Icon_" .. name, Size = UDim2.fromOffset(size, size) })
	for p, v in pairs(props or {}) do
		root[p] = v
	end
	-- The drawn icons below are the fallback. The moment the owner puts a real image in
	-- Config.Icons[name], this returns that instead, and SetColor tints the image so hover still
	-- works. Every call site keeps working unchanged because the returned shape is the same.
	local asset = Config.Icons[name]
	if type(asset) == "string" and asset ~= "" then
		local img = new("ImageLabel", {
			Image = asset,
			BackgroundTransparency = 1,
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromScale(1, 1),
			Parent = root,
		})
		-- Config.ColorIcons names are drawn exactly as their PNG is: the owner's AutoExec
		-- glyph is a pale folder with a red bolt, and one tint would flatten the two.
		local keep = type(Config.ColorIcons) == "table" and Config.ColorIcons[name] == true
		if not keep then
			img.ImageColor3 = color
		end
		root.Parent = parent
		local imageObj = { Root = root }
		function imageObj.SetColor(c)
			if not keep then
				img.ImageColor3 = c
			end
		end
		return imageObj
	end
	local parts = {}

	local function line(x1, y1, x2, y2, th)
		th = th or 2.2
		local dx, dy = x2 - x1, y2 - y1
		local len = math.sqrt(dx * dx + dy * dy) + th * 0.5
		local f = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset((x1 + x2) / 2 * k, (y1 + y2) / 2 * k),
			Size = UDim2.fromOffset(len * k, th * k),
			Rotation = math.deg(math.atan2(dy, dx)),
			BackgroundTransparency = 0,
			BackgroundColor3 = color,
			Parent = root,
		})
		new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = f })
		parts[#parts + 1] = { f = f }
	end

	local function fill(x, y, w, h, r)
		local f = new("Frame", {
			Position = UDim2.fromOffset(x * k, y * k),
			Size = UDim2.fromOffset(w * k, h * k),
			BackgroundTransparency = 0,
			BackgroundColor3 = color,
			Parent = root,
		})
		if r and r > 0 then
			corner(f, r * k)
		end
		parts[#parts + 1] = { f = f }
	end

	local function outlineC(cx, cy, w, h, th, r, rot)
		local f = new("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromOffset(cx * k, cy * k),
			Size = UDim2.fromOffset(math.max((w - 2 * th) * k, 1), math.max((h - 2 * th) * k, 1)),
			Rotation = rot or 0,
			Parent = root,
		})
		if r and r > 0 then
			corner(f, r * k)
		end
		parts[#parts + 1] = { s = stroke(f, color, th * k, 0) }
	end

	local function outline(x, y, w, h, th, r)
		outlineC(x + w / 2, y + h / 2, w, h, th, r, 0)
	end

	local function ring(cx, cy, d, th)
		outlineC(cx, cy, d, d, th, d / 2, 0)
	end

	local function arc(cx, cy, r, a0, a1, th)
		local steps = math.max(6, math.floor(math.abs(a1 - a0) / 20))
		local lx, ly
		for i = 0, steps do
			local a = math.rad(a0 + (a1 - a0) * i / steps)
			local x, y = cx + r * math.cos(a), cy + r * math.sin(a)
			if lx then
				line(lx, ly, x, y, th)
			end
			lx, ly = x, y
		end
	end

	local function head(tx, ty, dx, dy, len, th)
		local m = math.sqrt(dx * dx + dy * dy)
		dx, dy = -dx / m, -dy / m
		for _, s in ipairs({ 0.6, -0.6 }) do
			local c, sn = math.cos(s), math.sin(s)
			line(tx, ty, tx + (dx * c - dy * sn) * len, ty + (dx * sn + dy * c) * len, th)
		end
	end

	local defs = {}
	defs.plus = function()
		line(12, 5, 12, 19, 2.6)
		line(5, 12, 19, 12, 2.6)
	end
	-- A rotated square is the sparkle's silhouette, and it is the only mark in the set that is not
	-- a stroke, so it cannot be mistaken for close or plus when the real image is absent.
	defs.ai = function()
		outlineC(12, 12, 15, 15, 2.6, 4, 45)
	end
	defs.fps = function()
		line(13.5, 4, 8.5, 13, 2.6)
		line(8.5, 13, 15.5, 13, 2.6)
		line(15.5, 13, 10.5, 20, 2.6)
	end
	defs.ping = function()
		-- arc() takes degrees, so the wave is two upper-half arcs stacked on their own
		-- dot. The first attempt passed a thickness where the start angle goes and drew a caret.
		ring(12, 18, 3, 2.4)
		arc(12, 18, 6, 200, 340, 2.4)
		arc(12, 18, 11, 205, 335, 2.4)
	end
	defs.players = function()
		ring(9, 8, 5, 2.4)
		arc(9, 19, 6, 180, 360, 2.6)
		ring(16.5, 9, 4, 2.2)
		arc(16.5, 18, 4.5, 180, 360, 2.2)
	end
	defs.info = function()
		line(5, 19, 5, 14, 2.6)
		line(11, 19, 11, 10, 2.6)
		line(17, 19, 17, 6, 2.6)
	end
	defs.close = function()
		line(6, 6, 18, 18, 2.6)
		line(18, 6, 6, 18, 2.6)
	end
	defs.chevron = function()
		line(6, 9, 12, 15, 2.6)
		line(12, 15, 18, 9, 2.6)
	end
	-- Stroke census: this glyph is only ever drawn at 14px. At 2.2 units the chevron arms came
	-- out 1.28 units thick and the 2-unit slash 1.17, the thinnest mark in the panel and close to
	-- the width the engine has been measured to drop. 3.0 and 2.8 put every mark above 1.6 units
	-- without touching the geometry, because code is two chevrons and a slash with no hole to close.
	defs.code = function()
		line(9, 7, 3.5, 12, 3)
		line(3.5, 12, 9, 17, 3)
		line(15, 7, 20.5, 12, 3)
		line(20.5, 12, 15, 17, 3)
		line(13.5, 5, 10.5, 19, 2.8)
	end
	defs.search = function()
		ring(10, 10, 13, 2.4)
		line(15.2, 15.2, 20.5, 20.5, 2.8)
	end
	defs.save = function()
		outline(4, 4, 16, 16, 2.2, 3)
		fill(8, 5.5, 7, 4, 1)
		fill(7, 14, 10, 6, 1)
	end
	defs.import = function()
		line(12, 4, 12, 14, 2.4)
		head(12, 15, 0, 1, 5.5, 2.4)
		line(5, 16, 5, 20, 2.2)
		line(5, 20, 19, 20, 2.2)
		line(19, 16, 19, 20, 2.2)
	end
	defs.settings = function()
		ring(12, 12, 12, 2.6)
		for i = 0, 7 do
			local a = math.rad(i * 45)
			local c, s = math.cos(a), math.sin(a)
			line(12 + 6.6 * c, 12 + 6.6 * s, 12 + 10.4 * c, 12 + 10.4 * s, 3)
		end
	end
	defs.refresh = function()
		arc(12, 12, 7.5, 25, 305, 2.4)
		local a = math.rad(305)
		head(12 + 7.5 * math.cos(a), 12 + 7.5 * math.sin(a), -math.sin(a), math.cos(a), 4.8, 2.4)
	end
	defs.power = function()
		arc(12, 13, 7, -55, 235, 2.6)
		line(12, 3.5, 12, 12, 2.6)
	end
	defs.folder = function()
		outline(3, 8, 18, 12, 2.2, 2)
		fill(3, 4.5, 8, 4.5, 1)
	end
	defs.play = function()
	-- Measured on the tablet: the twelve 1.2-unit rows of the reference are 0.7 physical pixels at
	-- the 14px this pill draws, and the engine drops a frame that thin, so Execute had no glyph at
	-- all. Seven rows of 1.9 units keep the same right-pointing triangle and every row survives.
	for i = 0, 6 do
		local y = 4.5 + i * 2.1
		local w = 12 * (1 - math.abs(y + 1.05 - 12) / 7.5)
		fill(8, y, math.max(w, 1.6), 1.9, 0)
	end
end
	-- The third pill on the owner's sheet is AutoExec, drawn as a lightning bolt. This is the fallback
	-- silhouette until bolt.png arrives; every segment is a real line, so it stays visible at 14px.
	defs.bolt = function()
		line(14, 3.5, 9.5, 12.5, 2.4)
		line(9.5, 12.5, 13, 12.5, 2.4)
		line(13, 12.5, 10, 20.5, 2.4)
		line(10, 20.5, 14.5, 11.5, 2.4)
		line(14.5, 11.5, 11, 11.5, 2.4)
		line(11, 11.5, 14, 3.5, 2.4)
	end
	-- Measured in the render, not guessed: at the 13px this row drew, each stroke came out 1.41px
	-- wide with about 2px between them, so the three marks collapsed into one faint slash and the
	-- edit affordance read as "a line". Two shapes now, drawn at 16px: a 5.2-unit body, and a nib
	-- whose arms are computed symmetrically about the body's axis. head() splays +-34 deg around
	-- the axis it is given, which put one arm inside the bar and the other outside it, so the tip
	-- looked like a hook; these two lines are +-26 deg, and the wedge straddles the axis.
	defs.pencil = function()
		line(8.2, 15.8, 17.2, 6.8, 5.2)
		line(4.4, 19.6, 9.69, 17.78, 3.2)
		line(4.4, 19.6, 6.22, 14.31, 3.2)
	end
	-- At 14px the lid, the handle and the can are all under two physical pixels apart, and the three
	-- marks read as one blob with a hat on it. The fallback keeps the two that still read at that size:
	-- a wide lid line and a can under it.
	defs.trash = function()
		line(4, 6, 20, 6, 2.2)
		outline(5.5, 9, 13, 11, 2.5, 2.2)
	end
	defs.key = function()
		ring(7.5, 12, 9, 2.4)
		line(12, 12, 21, 12, 2.4)
		line(17.5, 12, 17.5, 16, 2.2)
		line(20.5, 12, 20.5, 15.5, 2.2)
	end
	defs.clock = function()
		ring(12, 12, 18, 2.2)
		line(12, 12, 12, 7, 2.2)
		line(12, 12, 15.5, 14, 2.2)
	end
	defs.link = function()
		outlineC(8.5, 15.5, 12, 7.5, 2.2, 3.7, -45)
		outlineC(15.5, 8.5, 12, 7.5, 2.2, 3.7, -45)
	end
	defs.arrow = function()
		line(4, 12, 19, 12, 2.6)
		head(20, 12, 1, 0, 6.5, 2.6)
	end
	defs.output = function()
		outline(3.5, 5, 17, 14, 2.2, 3)
		line(7.5, 9.5, 10.5, 12, 2.2)
		line(10.5, 12, 7.5, 14.5, 2.2)
		line(12.5, 15, 16.5, 15, 2.2)
	end
	-- A piece with a tab on top and a plus beside it: the mark the owner sent for this section.
	-- outline() takes the OUTER box and the stroke eats twice its width, so a 4-unit square
	-- with a 2.2 stroke draws as a one-pixel dot: the first version of this mark did. Every
	-- box below is sized for the stroke it carries.
	defs.extensions = function()
		outline(2.5, 6.5, 14.5, 14, 2.4, 3)
		line(9.5, 6.5, 9.5, 3, 2.4)
		line(18.5, 13.5, 23, 13.5, 2.4)
		line(20.75, 11.25, 20.75, 15.75, 2.4)
	end
	defs.check = function()
		line(5, 12.5, 10, 17.5, 2.8)
		line(10, 17.5, 19, 7, 2.8)
	end
	-- Two sheets, the back one shown as an open corner above and to the right of the front sheet. The
	-- first cut stacked two closed outlines and at 13 units they merged into one smudge; this is the
	-- standard copy mark and it keeps a clear gap at the size the console actually draws it.
	defs.copy = function()
		outline(3.5, 8.5, 12, 12, 2.2, 2.5)
		line(9, 3.2, 20.5, 3.2, 2.2)
		line(20.5, 3.2, 20.5, 15.2, 2.2)
	end

	local def = defs[name]
	if def then
		def()
	end
	root.Parent = parent

	local obj = { Root = root }
	function obj.SetColor(c)
		for _, p in ipairs(parts) do
			if p.s then
				p.s.Color = c
			else
				p.f.BackgroundColor3 = c
			end
		end
	end
	return obj
end

local function centerIcon(parent, name, size, color)
	return Icon.new(name, parent, size, color, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
	})
end

local function iconHover(btn, ic, normal, over)
	btn.MouseEnter:Connect(function()
		ic.SetColor(over)
	end)
	btn.MouseLeave:Connect(function()
		ic.SetColor(normal)
	end)
end

-- Three kinds, one table. Every button resolves normal / hover / pressed through here, so a
-- variant is a name at the call site instead of four more literals. Red is the brand, but only
-- the primary wears it: that is the line between a brand and a wallpaper.
local function buttonStyles()
	return {
		primary = { fill = T.Accent, over = T.AccentHover, down = T.AccentDeep,
			ring = T.AccentHover, ringT = 0.25, text = T.Text, glow = false },
		secondary = { fill = T.Editor, over = T.Dark, down = T.StrokeSoft,
			ring = T.Stroke, ringT = 0.4, text = T.Text },
		ghost = { fill = T.Editor, over = T.Dark, down = T.StrokeSoft,
			ring = T.StrokeSoft, ringT = 0.55, text = T.TextSecondary },
		danger = { fill = T.Red, over = lighten(T.Red, 0.16), down = T.AccentDeep,
			ring = T.Red, ringT = 0.25, text = T.Text },
	}
end

-- The press is a 0.96 scale as well as a colour change, because a thumb covers exactly the
-- pixels that would show the colour. Lite drops the glow, never the press.
local function styleButton(b, variant, opts)
	local v = buttonStyles()[variant] or buttonStyles().secondary
	opts = opts or {}
	local face = opts.face or b
	face.BackgroundColor3 = v.fill
	b.BackgroundTransparency = (opts.face and 1) or (opts.transparentFill and 1 or 0)
	if opts.face then
		-- new() hands every GuiObject a transparent background, so a plate that is
		-- meant to be filled has to say so: without this the primary pill drew its ring and its
		-- label on nothing, and Execute read as an outline instead of the one filled button on screen.
		face.BackgroundTransparency = 0
	end
	litStroke(face, v.ring, v.ringT)
	if v.glow then
		CROZIX.trackGlow(new("UIStroke", { Color = T.Glow, Thickness = 2, Transparency = 0.75,
			ApplyStrokeMode = Enum.ApplyStrokeMode.Border, Enabled = false, Parent = b }))
	end
	local sc = new("UIScale", { Scale = 1, Parent = b })
	b.MouseEnter:Connect(function()
		tw(face, CROZIX.D.MOTION.State, { BackgroundColor3 = v.over })
	end)
	b.MouseLeave:Connect(function()
		tw(face, CROZIX.D.MOTION.State, { BackgroundColor3 = v.fill })
		tw(sc, CROZIX.D.MOTION.Press, { Scale = 1 })
	end)
	b.MouseButton1Down:Connect(function()
		tw(face, CROZIX.D.MOTION.Press, { BackgroundColor3 = v.down })
		tw(sc, CROZIX.D.MOTION.Press, { Scale = 0.96 })
	end)
	b.MouseButton1Up:Connect(function()
		tw(face, CROZIX.D.MOTION.State, { BackgroundColor3 = v.over })
		tw(sc, CROZIX.D.MOTION.Press, { Scale = 1 })
	end)
	return v
end

-- Disabled is its own look rather than the normal one slightly faded, so a player can tell
-- "not yet" from "already done".
function CROZIX.setButtonEnabled(b, on)
	-- A plate is not one Frame: under it sit the glow, the drawn icon's own Frames and the word, and
	-- fading only the plate left a bright red glyph on a dead button, which reads as "already done"
	-- rather than "not yet". Each class gets the transparency property it actually paints with.
	local bg, tx, im = on and 0 or 0.72, on and 0 or 0.6, on and 0 or 0.72
	b.Active = on
	b.BackgroundTransparency = bg
	local function paint(c)
		if c:IsA("UIStroke") then
			-- The hairline is the last thing still shouting accent on a dead plate: the picture of the
			-- disabled Import button showed a dark pill with a bright red outline, which reads as
			-- "selected", not "not yet". A stroke is not a GuiObject, so it needs its own property.
			c.Transparency = bg
		elseif c:IsA("TextLabel") then
			c.TextTransparency = tx
		elseif c:IsA("ImageLabel") then
			c.ImageTransparency = im
		elseif c:IsA("Frame") then
			c.BackgroundTransparency = bg
		end
		for _, k in ipairs(c:GetChildren()) do
			paint(k)
		end
	end
	for _, c in ipairs(b:GetChildren()) do
		paint(c)
	end
end

-- button with an icon + text row
local function iconButton(parent, text, iconName, color, size, pos, textColor, iconSize, textSize)
	-- Every caller of this passes a plate on the touch floor, and work/touch_census_lib.js reads
	-- each call and refuses the build if one is short or cannot be measured. The floor is not
	-- clamped here because indexing size.Height.Offset aborts the boot on this engine.
	local b = new("TextButton", {
		BackgroundTransparency = 0,
		BackgroundColor3 = color,
		Size = size,
		Position = pos or UDim2.new(),
		Parent = parent,
	})
	corner(b, CROZIX.D.R.PILL)
	styleButton(b, (color == T.Accent or color == T.Green) and "primary" or "secondary")
	local tcol = textColor or T.Text
	local row = new("Frame", { Size = UDim2.fromScale(1, 1), Parent = b })
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Center,
		VerticalAlignment = Enum.VerticalAlignment.Center,
		Padding = UDim.new(0, 6),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = row,
	})
	local ic = Icon.new(iconName, row, iconSize or 14, tcol, { LayoutOrder = 1 })
	local lbl = new("TextLabel", {
		Text = text,
		Font = Enum.Font.GothamBold,
		TextSize = textSize or 11,
		TextColor3 = tcol,
		AutomaticSize = Enum.AutomaticSize.X,
		Size = UDim2.new(0, 0, 1, 0),
		LayoutOrder = 2,
		Parent = row,
	})
	return b, ic, lbl
end

-- Rule 5 is a floor, not a suggestion, and a 34px field is a coin flip with a thumb. The height
-- comes from the call but is never allowed under 44, so every field in the panel clears it at once.
-- The corners go to the pill step because the brief asks the search bar to read as one thing, and
-- the fill stops being half-transparent: a field is Surface 3, the same plate the editor well uses.
local function inputBox(parent, pos, size, iconName, placeholder)
	local fieldH = math.max(size.Y.Offset, CROZIX.D.HIT)
	local f = new("Frame", {
		Position = pos,
		Size = UDim2.new(size.X.Scale, size.X.Offset, size.Y.Scale, fieldH),
		BackgroundTransparency = 0,
		BackgroundColor3 = T.Editor,
		Parent = parent,
	})
	corner(f, CROZIX.D.R.PILL)
	local st = stroke(f, T.StrokeSoft, 1, 0.2)
	local ic = Icon.new(iconName, f, 16, T.Muted, {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 10, 0.5, 0),
	})
	local tb = new("TextBox", {
		Text = "",
		PlaceholderText = placeholder,
		PlaceholderColor3 = T.Muted,
		ClearTextOnFocus = false,
		ClipsDescendants = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		Position = UDim2.fromOffset(34, 0),
		Size = UDim2.new(1, -44, 1, 0),
		Parent = f,
	})
	tb.Focused:Connect(function()
		tw(st, 0.12, { Color = T.Stroke, Transparency = 0 })
		ic.SetColor(T.Text)
	end)
	tb.FocusLost:Connect(function()
		tw(st, 0.12, { Color = T.StrokeSoft, Transparency = 0.2 })
		ic.SetColor(T.Muted)
	end)
	return f, tb
end

