-- on this engine's CoreGui children (a probe took the count from 2 to 1), so sweep shortly after
-- the build -- and only while our own window is still mounted, because a window that was already
-- removed must not go on to remove the survivor.
local function sweepOlderWindows()
	pcall(function()
		if Gui.Parent == nil then
			return
		end
		for _, hub in ipairs({ game:GetService("CoreGui"), PlayerGui }) do
			for _, c in ipairs(hub:GetChildren()) do
