		task.delay(2, sweepOlderWindows)
		task.delay(8, sweepOlderWindows)
	end
end)
-- The two shots above only cover the first eight seconds of the session. The sweep keeps going while
-- this window is mounted, because a loader that builds its panel later must not leave a second panel
-- standing. It exits on its own once the window is gone, so a removed instance never goes on to
-- remove the survivor.
task.spawn(function()
	while true do
