local connections = {}
local function connect(signal, fn)
	-- one session list, owned by the head: a panel's own widgets die with its window, but a handler put
	-- on a SERVICE does not, so every join has to hand its connections to the place the next join will
	-- clear (CROZIX.keep); measured growth was +4 RenderStepped and +6 input handlers per join
	-- (work/probe_join_handlers.js), and work/test_double_boot.js is what keeps it from coming back
	local c
	if type(CROZIX) == 'table' and type(CROZIX.keep) == 'function' then
		c = CROZIX.keep(signal, fn)
	else
		c = signal:Connect(fn)
	end
	connections[#connections + 1] = c
	return c
end

local fit, shown, revealed, locked = 1, true, false, true
local sizeSlider -- set later (settings pane)

-- Smart auto size: ~60% of the width / 70% of the height, never fullscreen.
local function targetScale()
	local vp = Gui.AbsoluteSize
	local maxFit = math.min(vp.X * 0.92 / DESIGN_W, vp.Y * 0.92 / DESIGN_H)
	local s
	if Settings.Smart then
-- 0.60 / 0.62 of the viewport. Measured on the tablet on 2026-11-01: at 0.72 / 0.82 the window took
-- 71% of the screen width and ran past the bottom edge, so its own content was clipped. The old
-- window players know sits at 46% x 52%. Smart stays on, so a small phone still fits, and turning
-- Smart off hands the size to the slider in Settings exactly as before.
		s = math.clamp(math.min(vp.X * 0.60 / DESIGN_W, vp.Y * 0.62 / DESIGN_H), 0.45, 1.55)
	else
		s = math.clamp(Settings.Scale, 0.85, 1.6)
	end
	return math.min(s, maxFit)
end

-- The harness taps by the map, and every resize invalidates the whole map. The debounce lives here
-- rather than at each caller because the slider fires on every frame of a drag.
local reportPending = false
local function remapSoon()
	if not CROZIX.harness or reportPending or type(CROZIX.report) ~= "function" then
		return
	end
	reportPending = true
	task.spawn(function()
		task.wait(1.4)
		reportPending = false
		CROZIX.report()
	end)
end

local function refreshScale(instant)
	fit = targetScale()
	if revealed and shown then
		if instant then
			Scale.Scale = fit
		else
			tw(Scale, 0.18, { Scale = fit })
		end
	else
		-- Before the first reveal the scale is written silently, so the window never pops from 1 to the
		-- fitted size on the frame it becomes visible.
		Scale.Scale = fit
	end
	if Settings.Smart and sizeSlider then
		sizeSlider.set(math.clamp(math.floor(fit * 20 + 0.5) / 20, 0.85, 1.6), true)
	end
	-- Phase F (master prompt Phase 7): a real narrow-window reflow, not just UIScale. The hook is
	-- installed after the editor widgets exist; refreshScale runs at boot before they do (skips it)
	-- and again on every viewport change, so the reflow always tracks the rendered size.
	if CROZIX.applyCompact then
		CROZIX.applyCompact(fit)
	end
	remapSoon()
end
connect(Gui:GetPropertyChangedSignal("AbsoluteSize"), function()
	refreshScale(true)
end)
