-- v6: one shared rail tooltip. The dwell gate is the point: touch fires MouseEnter on tap-down
-- and MouseLeave on release, so a quick tap cancels before the 0.35s deadline and never flashes;
-- a mouse rest names the icon-only row. One closure local, not five body locals.
local RailTip = (function()
	local tip = new("TextLabel", {
		Name = "CrozixRailTip",
		Text = "",
		Font = Enum.Font.GothamMedium,
		TextSize = CROZIX.D.TYPE.Caption,
		TextColor3 = T.Text,
		BackgroundColor3 = T.PanelBottom,
		BackgroundTransparency = 1,
		TextTransparency = 1,
		AnchorPoint = Vector2.new(1, 0.5),
		Position = UDim2.fromOffset(636, 0),
		Size = UDim2.fromOffset(0, CROZIX.D.H.CHIP),
		AutomaticSize = Enum.AutomaticSize.X,
		Visible = false,
		ZIndex = 60,
		Parent = Root,
	})
	corner(tip, CROZIX.D.R.XS)
	new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10), Parent = tip })
	local tipStroke = stroke(tip, T.StrokeSoft, 1, 1)
	local gen = 0
	local function hide()
		gen += 1
		local my = gen
		tw(tip, 0.12, { BackgroundTransparency = 1, TextTransparency = 1 })
		tw(tipStroke, 0.12, { Transparency = 1 })
		task.delay(0.14, function()
			if my == gen then tip.Visible = false end
		end)
	end
	local function show(text, rowY)
		gen += 1
		local my = gen
		tip.Text = text
		tip.Position = UDim2.fromOffset(636, rowY)
		tip.Visible = true
		tw(tip, 0.12, { BackgroundTransparency = 0.05, TextTransparency = 0 })
		tw(tipStroke, 0.12, { Transparency = 0.3 })
		task.delay(1.6, function()
			if my == gen then hide() end
		end)
	end
	local function dwell(text, rowY, isActive)
		gen += 1
		local my = gen
		task.delay(0.35, function()
			if my == gen and not isActive() then show(text, rowY) end
		end)
	end
	local function cancel()
		gen += 1
		if tip.Visible then hide() end
	end
	return { dwell = dwell, cancel = cancel }
end)()

local sideButtons, sideIcons, sideBars = {}, {}, {}
local function makeSideButton(def, parent, order)
	local b = new("TextButton", {
		Size = UDim2.fromOffset(CROZIX.D.HIT, CROZIX.D.HIT),
		BackgroundColor3 = T.Accent,
		BackgroundTransparency = 1,
		-- #sideButtons is 0 forever: the table is keyed by section name, so the length operator sees
		-- no entries and all six icons got LayoutOrder 2. The list then fell back to insertion order,
		-- which the engine does not promise -- the rail could arrive in any order on any device. The
		-- position of the section in SIDE is the order, and it is handed in by the loop below.
		LayoutOrder = order,
		Parent = parent,
	})
	corner(b, CROZIX.D.R.SM)
	-- One asset path: this used to build its own ImageLabel from Config.Icons, which is how a
	-- keep-colour mark got flattened on the rail even though the registry says it must not be tinted.
	-- CROZIX.iconImage is the call the Extensions kit makes, so the two cannot drift apart again.
	local ic = CROZIX.iconImage(def.key, b, 18, T.Muted, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
	})
	if not ic then
		ic = centerIcon(b, def.icon, 18, T.Muted)
	end
	local bar = new("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, -7, 0.5, 0), -- inside the rail, unlike the cue, which is on the rail
		Size = UDim2.fromOffset(3, 18),
		BackgroundTransparency = 0,
		BackgroundColor3 = T.Accent,
		Visible = false,
		Parent = b,
	})
	corner(bar, CROZIX.D.R.PILL)
	b.MouseEnter:Connect(function()
		if not b:GetAttribute("Active") then
			tw(b, 0.12, { BackgroundTransparency = 0.85 })
			ic.SetColor(T.Text)
		end
		RailTip.dwell(def.label, CROZIX.SIDE_TOP + (order - 1) * CROZIX.D.HIT + CROZIX.D.HIT / 2, function()
			return b:GetAttribute("Active")
		end)
	end)
	b.MouseLeave:Connect(function()
		if not b:GetAttribute("Active") then
			tw(b, 0.12, { BackgroundTransparency = 1 })
			ic.SetColor(T.Muted)
		end
		RailTip.cancel()
	end)
	sideButtons[def.key] = b
	b.Name = "CrozixSide_" .. def.key
	CROZIX.register("CrozixSide_" .. def.key, b)
	sideIcons[def.key] = ic
	sideBars[def.key] = bar
	return b
end
