-- CUE_X is named once because the resting position and the tween target both read it. Nine pixels
-- outside the rail put the bar in the middle of the 27px gap between the window and the rail, where
-- the one accent mark on the screen read as a rendering accident instead of "this row is active".
CROZIX.CUE_X = -1
local SideCue = new("Frame", {
	AnchorPoint = Vector2.new(0, 0.5),
	Position = UDim2.new(0, CROZIX.CUE_X, 0, CROZIX.SIDE_TOP + CROZIX.D.HIT / 2),
	Size = UDim2.fromOffset(3, 22),
