-- v6: group the rail 3|2|2 (create | assist | system). The lines are children of the rail, not
-- the list, so the 44px pitch, the cue tween and the registered tap geometry all stay put.
for _, after in ipairs({ 3, 5 }) do
	local sep = new("Frame", {
