-- One accent plate and one cue. The cue is a single Frame that tweens to the active row, so
-- changing section reads as movement rather than six things flicking at once.
local function setActiveSide(key)
	local step = CROZIX.D.HIT
	local row = 0
	for i, def in ipairs(SIDE) do
		if def.key ~= "refresh" then
			local on = def.key == key
			local b = sideButtons[def.key]
			b:SetAttribute("Active", on)
			tw(b, CROZIX.D.MOTION.Section, { BackgroundTransparency = on and 0.82 or 1 })
			sideIcons[def.key].SetColor(on and T.AccentHover or T.Muted)
			sideBars[def.key].Visible = false
			if on then
				row = i - 1
			end
		end
	end
	if SideCue then
		tw(SideCue, CROZIX.D.MOTION.Section, {
			Position = UDim2.new(0, CROZIX.CUE_X, 0, CROZIX.SIDE_TOP + row * step + CROZIX.D.HIT / 2),
		}, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
	end
end

