local function makeToast(parent, pos)
	-- The card lives UNDER the window, not on it: the panel is 380 design units tall, so the host starts
	-- 12 units below its bottom edge. No message can ever cover a control the player is reaching for.
	local Host = new("Frame", {
		Name = "CrozixToastHost",
		AnchorPoint = Vector2.new(0.5, 0),
		Position = pos,
		Size = UDim2.fromOffset(700, 40),
		BackgroundTransparency = 1,
		Visible = false,
		ZIndex = 40,
		Parent = parent,
	})
	-- v8: the chip wears the window's own surface -- the same PanelTop-to-PanelBottom gradient the
	-- plates use -- so a message reads as part of the window, not a grey box under it. It stays 30
	-- units tall and answers the Transparency slider. The glow is still two faint plates of light;
	-- this engine has no per-object blur.
	local glowOuter = new("Frame", {
		Name = "CrozixToastHalo",
		BackgroundColor3 = T.Glow,
		BackgroundTransparency = 0.96,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0, 15),
		Size = UDim2.fromOffset(326, 46),
		ZIndex = 38,
		Parent = Host,
	})
	corner(glowOuter, 14)
	local glowInner = new("Frame", {
		Name = "CrozixToastHalo2",
		BackgroundColor3 = T.Glow,
		BackgroundTransparency = 0.92,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0, 15),
		Size = UDim2.fromOffset(314, 40),
		ZIndex = 39,
		Parent = Host,
	})
	corner(glowInner, 12)
	-- The chip hangs under the window, so it answers the same slider: at 0 it is the same slightly
	-- lifted card it always was, and it opens by the same amount as the plates above it. The +0.12
	-- head start is kept, so a message is never more solid than the surface it belongs to.
	local function chipRest()
		return math.clamp(glassBase() + 0.12, 0, 0.85)
	end
	local Card = new("Frame", {
		Name = "CrozixToastCard",
		BackgroundColor3 = Color3.new(1, 1, 1),
		BackgroundTransparency = chipRest(),
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.new(0.5, 0, 0, 0),
		Size = UDim2.fromOffset(300, 30),
		ClipsDescendants = true,
		ZIndex = 41,
		Parent = Host,
	})
	corner(Card, 8)
	new("UIGradient", {
		Rotation = 90,
		Color = ColorSequence.new(T.PanelTop, T.PanelBottom),
		Parent = Card,
	})
	local cardStroke = stroke(Card, T.Stroke, 1, 0.55)
	local dot = new("Frame", {
		Name = "CrozixToastDot",
		BackgroundColor3 = T.Green,
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.fromOffset(12, 15),
		Size = UDim2.fromOffset(5, 5),
		ZIndex = 42,
		Parent = Card,
	})
	corner(dot, 3)
	local Msg = new("TextLabel", {
		Name = "CrozixToastMsg",
		Text = "",
		Font = Enum.Font.GothamMedium,
		TextSize = 12,
		TextColor3 = T.Text,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Center,
		TextTruncate = Enum.TextTruncate.AtEnd,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(26, 0),
		Size = UDim2.new(1, -38, 1, 0),
		ZIndex = 42,
		Parent = Card,
	})
	-- The life strip: a hairline pinned to the card's bottom-right corner. It wipes from right to left
	-- over exactly the time the message stays up, then the card fades. The timer, drawn not written.
	-- Drawn behind the label (ZIndex 41 vs 42) so it never scores through the words.
	local Line = new("Frame", {
		Name = "CrozixToastLife",
		BackgroundColor3 = T.Accent,
		BackgroundTransparency = 0.2,
		AnchorPoint = Vector2.new(1, 1),
		Position = UDim2.new(1, -8, 1, -4),
		Size = UDim2.new(0, 0, 0, 2),
		ZIndex = 41,
		Parent = Card,
	})
	local parts = {
		{ obj = glowOuter, prop = "BackgroundTransparency", base = 0.96 },
		{ obj = glowInner, prop = "BackgroundTransparency", base = 0.92 },
		-- A function, not a number: the resting value is whatever the slider says when the fade lands,
		-- not the one that was true when the toast was built.
		{ obj = Card, prop = "BackgroundTransparency", base = chipRest },
		{ obj = cardStroke, prop = "Transparency", base = 0.55 },
		{ obj = dot, prop = "BackgroundTransparency", base = 0 },
		{ obj = Msg, prop = "TextTransparency", base = 0 },
		{ obj = Line, prop = "BackgroundTransparency", base = 0.2 },
	}
	-- One alpha for the whole card: each child remembers the transparency it settles at, so fading in and
	-- out can never leave a label dimmer than its neighbour.
	local fadeA = 0
	local function alpha(a, t)
		fadeA = a
		for _, p in ipairs(parts) do
			local base = type(p.base) == "function" and p.base() or p.base
			local v = base + (1 - base) * a
			if t then
				tween(p.obj, t, { [p.prop] = v }, Enum.EasingStyle.Quad)
			else
				p.obj[p.prop] = v
			end
		end
	end
	-- A slider move should land on a message that is already up, not wait for the next one. Keeping
	-- fadeA means this can only change where the card is heading: one that is fading out stays fading.
	glassSettle[#glassSettle + 1] = function()
		if Host.Visible then
			local base = chipRest()
			Card.BackgroundTransparency = base + (1 - base) * fadeA
		end
	end
	local gen = 0
	return function(msg, color, dur)
		gen += 1
		local my = gen
		local hold = tonumber(dur) or 2.6
		-- The card is as wide as the sentence, measured by the engine, so a two-word toast looks like a
		-- toast and a long error does not run off the screen.
		local w = 260
		pcall(function()
			local ts = game:GetService("TextService")
			local one = ts:GetTextSize(tostring(msg), 12, Enum.Font.GothamMedium, Vector2.new(560, 40))
			if one.X > 0 then
				w = math.clamp(one.X + 46, 200, 520)
			end
		end)
		Msg.Text = tostring(msg)
		dot.BackgroundColor3 = color or T.Green
		Line.BackgroundColor3 = color or T.Accent
		Card.Size = UDim2.fromOffset(w, 30)
		glowInner.Size = UDim2.fromOffset(w + 10, 40)
		glowOuter.Size = UDim2.fromOffset(w + 22, 46)
		-- v7.4: the notification itself never moves. It fades in on the spot under the window, the strip
		-- wipes right to left as the countdown, and the card fades out when the strip is spent. The owner
		-- rejected a box that slid sideways: the strip is the only thing that travels.
		Line.Size = UDim2.new(0, 0, 0, 2)
		Host.Visible = true
		alpha(1, nil)
		alpha(0, 0.16)
		-- Linear on purpose: the strip is a clock, so its speed must not ease in or out.
		tween(Line, hold, { Size = UDim2.new(0, w - 16, 0, 2) }, Enum.EasingStyle.Linear)
		task.delay(hold, function()
			if my ~= gen then
				return
			end
			alpha(1, 0.22)
			task.delay(0.26, function()
				if my == gen then
					Host.Visible = false
				end
			end)
		end)
	end
end
local toast = makeToast(Root, UDim2.new(0.5, 0, 1, 12))

-- v8: every toast is also a line in the Crozix console, so a message the player caught by eye is
-- still there after the card fades. CROZIX.log is installed by the console pane further down the body.
local function notify(text, color)
	toast(text, color)
	if type(CROZIX.log) == "function" then
		pcall(CROZIX.log, text, color or T.Green)
	end
end

-- Registered on the adapter so the boot sequence (auto-run, settings) can speak to the player with the
-- same toast the rest of the panel uses, instead of silently doing something behind their back.
CROZIX.notify = function(text, color)
	notify(text, color or T.Green)
end

