local function statCell(index, caption, glyph)
	local cell = new("Frame", {
		Position = UDim2.new((index - 1) / 3, 0, 0, 0),
		Size = UDim2.new(1 / 3, 0, 1, 0),
		Parent = Pill,
	})
	-- Three rows, the owner's mock: the mark on top, the reading in the middle, the name
	-- under it. The mark is drawn at 20 against a Title-18 reading, which is the level he asked
	-- for -- an icon a step smaller than its number reads as a bullet, not as the same rank.
	if glyph then
		Icon.new(glyph, cell, 20, T.Muted, {
			AnchorPoint = Vector2.new(0.5, 0),
			Position = UDim2.new(0.5, 0, 0, 8),
		})
	end
	local value = new("TextLabel", {
		Text = "--",
		Font = Enum.Font.GothamBold,
		TextSize = CROZIX.D.TYPE.Title,
		TextColor3 = T.Text,
		Position = UDim2.fromOffset(0, 32),
		Size = UDim2.new(1, 0, 0, 26),
		Parent = cell,
	})
	new("TextLabel", {
		Text = caption,
		TextSize = 11,
		TextColor3 = T.Muted,
		Position = UDim2.fromOffset(0, 62),
		Size = UDim2.new(1, 0, 0, 14),
		Parent = cell,
	})
