			BackgroundColor3 = T.Muted,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(1, 0, 0.5, 0),
			Size = UDim2.new(0, 1, 0.6, 0),
			Parent = cell,
		})
	end
	return value
end
