local CODE_FONT, CODE_SIZE = Enum.Font.RobotoMono, 12

-- What one character and one line of the code font cost, asked of the engine instead of guessed.
-- Measured on the tablet: this engine answers TextService:GetTextSize, and RobotoMono at 12 comes
-- back 6 canvas units wide and 12 tall. Every number the editor lays out with comes from that one
-- answer, so the text the player reads, the caret they drive and the range they scroll are the same
-- measurement and cannot disagree with each other.
-- Every monospace guide puts leading at 1.4-1.6x; the editor used 1.0x, which is what made the
-- code well read cramped and small beside the controls.
local CODE_LEAD = 1.45
local CHAR_W, LINE_H = CODE_SIZE * 0.5, math.floor(CODE_SIZE * CODE_LEAD + 0.5)
pcall(function()
	local ts = game:GetService("TextService")
	local row = ts:GetTextSize(string.rep("M", 10), CODE_SIZE, CODE_FONT, Vector2.new(9e4, 9e4))
	local block = ts:GetTextSize(string.rep("M\n", 9) .. "M", CODE_SIZE, CODE_FONT, Vector2.new(9e4, 9e4))
	if row.X > 0 then
		CHAR_W = row.X / 10
	end
	if block.Y > 0 then
		LINE_H = math.max(block.Y / 10, math.floor(CODE_SIZE * CODE_LEAD + 0.5))
	end
end)

-- One editor, two homes: the code pane and the saved-script dialog both build through this, so a
-- fix lands in both and the two can never drift apart again.
--
-- There is one text layer here, and that is the whole decision. A TextBox paints one colour, so
-- coloured Lua needs a second label on top of it, and two layers only agree while one of them knows
-- where the other is standing -- which nothing on this engine can say, because the text box scrolls
-- itself and reports no offset. Both shapes were built and photographed on the tablet: sized to the
-- text, the caret lands on the right glyph but the engine draws the focused box's own text at the
-- platform's scale, outside every clip, across the corner of the screen; sized to the well, that
-- leak stops and the caret stops agreeing with the colour. Delta ships one layer and has neither
-- fault, so this does too. The owner chose it: a caret he can trust over syntax colour.
local function makeCodeView(parent, opts)
	local area = new("Frame", {
		Position = opts.position or UDim2.new(),
		Size = UDim2.fromOffset(opts.w, opts.h),
		BackgroundColor3 = T.Editor,
		ClipsDescendants = true,
		Parent = parent,
	})
	corner(area, 8)
	stroke(area, T.StrokeSoft, 1, 0.45)
	local inset = 8
	local box = new("TextBox", {
		Font = CODE_FONT,
		TextSize = CODE_SIZE,
		TextColor3 = SYN.Default,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		-- Bug 2: the WARNING banner and a loadstring one-liner both ran off the right edge with no
		-- way to see the rest. Wrapping puts every character on screen at any window width, the box still
		-- scrolls vertically, and nothing about editing changes.
		TextWrapped = true,
		MultiLine = true,
		ClearTextOnFocus = false,
		TextEditable = true,
		PlaceholderText = opts.placeholder or "",
		PlaceholderColor3 = T.Muted,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(inset, 6),
		Size = UDim2.fromOffset(opts.w - inset * 2, opts.h - 12),
		Parent = area,
	})
	local view = { Area = area, Box = box, lines = 1, longest = 0 }

	-- Bookkeeping only. Nothing is painted by a second layer any more, so there is nothing to size.
	function view:render(text)
		local src = text:gsub("\t", "    ")
		local lines = 1
		for _ in src:gmatch("\n") do
			lines += 1
		end
		local longest = 0
		for line in src:gmatch("[^\n]*") do
			if #line > longest then
				longest = #line
			end
		end
		view.lines = lines
		view.longest = longest
	end

	-- Where in the file the player is standing, counted from the buffer the box is showing. Tabs are
	-- already four spaces by the time the box holds them, so a column here is a column on screen.
	function view:caret()
		local cp = box.CursorPosition
		if cp < 1 then
			return 1, 1
		end
		local before = box.Text:sub(1, cp - 1):gsub("\t", "    ")
		local _, nl = before:gsub("\n", "")
		return nl + 1, #(before:match("([^\n]*)$") or "") + 1
	end

	return view
end

