-- "Crozix" plus the game's version on an empty page, gone the moment the player types. It is a plate
-- over the code well, never text inside the buffer: an editor that writes a greeting into the player's
-- file has already corrupted it. The plate is silent (Active = false), so a tap lands on the box below.
do
	-- "?" used to be printed as "Game v?" when the engine reported nothing. An absent fact is
	-- shown as absent: the welcome line drops the segment instead of asking the player a question.
	local gameVer = nil
	pcall(function()
		local v = game.PlaceVersion
		if type(v) == "number" then
			gameVer = tostring(math.floor(v))
		elseif type(v) == "string" and #v > 0 then
			gameVer = v
		end
	end)
	local plate = new("Frame", {
		Name = "CrozixWelcome",
		BackgroundTransparency = 1,
		Active = false,
		Size = UDim2.new(1, 0, 1, 0),
		ZIndex = 6,
		Parent = CodeArea,
	})
	local rule = new("Frame", {
		Name = "CrozixWelcomeRule",
		BackgroundColor3 = T.Accent,
		Position = UDim2.fromOffset(18, 26),
		Size = UDim2.fromOffset(22, 2),
		ZIndex = 7,
		Parent = plate,
	})
	corner(rule, 1)
	new("TextLabel", {
		Name = "CrozixWelcomeTitle",
		Text = "CROZIX",
		Font = Enum.Font.GothamBlack,
		TextSize = 26,
		TextColor3 = T.Text,
		TextXAlignment = Enum.TextXAlignment.Left,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(18, 34),
		Size = UDim2.new(1, -36, 0, 34),
		ZIndex = 7,
		Parent = plate,
	})
	new("TextLabel", {
		Name = "CrozixWelcomeLine",
		Text = "Welcome. Start typing to write your script.",
		Font = Enum.Font.GothamMedium,
		TextSize = CROZIX.D.TYPE.Body,
		TextColor3 = T.TextSecondary,
		TextXAlignment = Enum.TextXAlignment.Left,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(18, 72),
		Size = UDim2.new(1, -36, 0, 18),
		ZIndex = 7,
		Parent = plate,
	})
	new("TextLabel", {
		Name = "CrozixWelcomeVersion",
		Text = "CROZIX " .. tostring(CROZIX.PANEL_VERSION)
			.. (gameVer ~= nil and ("   ·   Game v" .. gameVer) or ""),
		Font = Enum.Font.GothamMedium,
		TextSize = CROZIX.D.TYPE.Caption,
		TextColor3 = T.Muted,
		TextXAlignment = Enum.TextXAlignment.Left,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(18, 94),
		Size = UDim2.new(1, -36, 0, 16),
		ZIndex = 7,
		Parent = plate,
	})
	CROZIX.welcomeShown = function()
		plate.Visible = Box.Text == ""
	end
	pcall(function()
		Box.Focused:Connect(function()
			plate.Visible = false
		end)
		Box.FocusLost:Connect(function()
			CROZIX.welcomeShown()
		end)
	end)
	CROZIX.welcomeShown()
end

-- The line-number gutter left with the colour layer: it can only stay true if it knows how far the
-- box has scrolled, and the box does not say. The reading the gutter existed to give is still on
-- screen, in a line that cannot disagree with the caret because it is computed from the same buffer.
-- The status line that used to sit here ("Ln 1, Col 1  4 lines  99 wide") is gone: the owner
-- called it useless. The reading it showed is still computed from the same buffer by
-- view:caret() and goes to the harness and to Crozix/caret.txt; it is simply no longer
-- painted under the code.

local BtnRow = new("Frame", {
	Position = UDim2.fromOffset(8, 232),
	Size = UDim2.fromOffset(364, CROZIX.D.HIT),
	Parent = EditorCard,
})
new("UIListLayout", {
	FillDirection = Enum.FillDirection.Horizontal,
	HorizontalAlignment = Enum.HorizontalAlignment.Right,
	VerticalAlignment = Enum.VerticalAlignment.Center,
	Padding = UDim.new(0, 6),
	SortOrder = Enum.SortOrder.LayoutOrder,
	Parent = BtnRow,
})

-- The shape is copied from the image the owner sent: one dark plate per action, a thin cool
-- outline, the icon on the left, a hairline divider, then the label. The row is laid out by BtnRow's
-- UIListLayout, so the widths below are the only thing that decides the rhythm.
local function actionButton(text, iconName, width, order, variant)
	-- The reference draws its pills at 32 units; only our version raised the painted plate to the 44
	-- touch floor, which is what made the row read oversized beside the code. The hit area keeps 44
	-- and the plate goes back to 32, centred inside it.
	local b = new("TextButton", {
		BackgroundTransparency = 1,
		BackgroundColor3 = T.Dark,
		Size = UDim2.fromOffset(width, CROZIX.D.HIT),
		Parent = BtnRow,
	})
	local plate = new("Frame", {
		Name = "Plate",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(1, 0, 0, 32),
		Parent = b,
	})
	corner(plate, CROZIX.D.R.PILL)
	corner(b, CROZIX.D.R.PILL)
	Icon.new(iconName, plate, 14, T.Text, {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 8, 0.5, 0),
	})
	new("Frame", {
		BackgroundColor3 = T.Stroke,
		BackgroundTransparency = 0.45,
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 28, 0.5, 0),
		Size = UDim2.new(0, 1, 0, 16),
		Parent = plate,
	})
	new("TextLabel", {
		Text = text,
		Font = Enum.Font.GothamBold,
		TextSize = 11,
		TextColor3 = T.Text,
		TextXAlignment = Enum.TextXAlignment.Left,
		Position = UDim2.fromOffset(34, 0),
		Size = UDim2.new(1, -40, 1, 0),
		Parent = b,
	})
	-- On this engine a touch raises MouseEnter as well, so the pill answers a finger. The states
	-- come from the variant table: Execute is the only primary in the row.
	styleButton(b, variant or "secondary", { face = plate })
	b.LayoutOrder = order
	return b
end

-- Widths add up to 342, and BtnRow's 6px padding makes the four pills span 360 of its 364px.
-- AutoExec replaces the old Open pill: the owner's sheet has no folder on the row, and the file it
-- writes is the one the boot path already runs, so the button has a real job on the next join.
local ExecBtn = actionButton("Execute", "play", 96, 1, "primary")
local ClearBtn = actionButton("Clear", "trash", 80, 2, "secondary")
local AutoBtn = actionButton("AutoExec", "bolt", 100, 3, "secondary")
local SaveBtn = actionButton("Save", "save", 76, 4, "secondary")
ExecBtn.Name = "CrozixExec"
ClearBtn.Name = "CrozixClear"
AutoBtn.Name = "CrozixAuto"
SaveBtn.Name = "CrozixSave"
for _, b in ipairs({ ExecBtn, ClearBtn, AutoBtn, SaveBtn }) do
	CROZIX.register(b.Name, b)
end

-- Phase F (master prompt Phase 7): below a scale threshold the left Status/Community column folds
-- away and the editor spans the body, so the code well gains over 60% more characters per line on a
-- small screen instead of just shrinking with UIScale. The default 700x380 layout (the frozen
-- previews) is untouched -- this only fires when the rendered window is small. Registration names
-- and the live tap map survive: refreshScale re-reports geometry after every reflow.
do
	local COMPACT_BELOW = 0.85
	local compactOn
	local function applyCompact(scale)
		local want = scale < COMPACT_BELOW
		if want == compactOn then
			return
		end
		compactOn = want
		if want then
			Info.Visible = false
			Community.Visible = false
			EditorCard.Position = UDim2.fromOffset(14, 14)
			EditorCard.Size = UDim2.fromOffset(604, 290)
			EDITOR.Area.Size = UDim2.fromOffset(588, 174)
			Box.Size = UDim2.fromOffset(572, 162)
			BtnRow.Size = UDim2.fromOffset(588, CROZIX.D.HIT)
		else
			Info.Visible = true
			Community.Visible = true
			EditorCard.Position = UDim2.fromOffset(238, 14)
			EditorCard.Size = UDim2.fromOffset(380, 290)
			EDITOR.Area.Size = UDim2.fromOffset(364, 174)
			Box.Size = UDim2.fromOffset(348, 162)
			BtnRow.Size = UDim2.fromOffset(364, CROZIX.D.HIT)
		end
	end
	CROZIX.applyCompact = applyCompact
	applyCompact(fit)
end

------------------------------------------------------------------
	CROZIX.step("ui:tabs_state")
-- TABS / STATE
------------------------------------------------------------------
local DEFAULT_CODE = [[-- Preparing the code components ...
local player = game:GetService("Players").LocalPlayer

function spot.Script()
	if script ~= nil then
		return "Welcome to the editor"
	end
end

local function main(count)
	local rate = 0.25
	for i = 1, count do
		print("tick", i, rate * i)
	end
end

main(5)
]]

local tabs, active, tabCounter = {}, 1, 0
local closing = false
local saved = {}
-- Seeded from Crozix/saved.json through the executor's file API, so the Open picker and the Saved
-- section show what the player actually keeps between sessions instead of an empty demo table.
CROZIX.load(saved)
local loading = false
local tabFrames = {}
local tabDots = {}
local selectTab, rebuildTabs



-- The box is the text now, so a buffer swap needs no relayout -- only the reading.
local function refreshView()
	EDITOR:render(Box.Text)
end

local function addTab(name, text)
	if #tabs >= 8 then
		notify("Maximum of 8 tabs", T.Yellow)
		return nil
	end
	tabCounter += 1
	tabs[#tabs + 1] = { name = name or ("Script " .. tabCounter), text = text or "", base = text or "" }
	if type(CROZIX.persistTabs) == "function" then
		CROZIX.persistTabs()
	end
	return #tabs
end

function rebuildTabs()
	for _, f in ipairs(tabFrames) do
		f:Destroy()
	end
	tabFrames = {}
	tabDots = {}
	for i, tab in ipairs(tabs) do
		local isActive = i == active
		local f = new("Frame", {
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.new(0, 0, 1, 0),
			LayoutOrder = i,
			Parent = TabStrip,
		})
		-- A UIListLayout lays out EVERY visible GuiObject sibling, so the active-tab underline below
		-- would be a row item and push the label sideways. The row keeps the layout to itself and the
		-- underline stays the absolute overlay it was written as.
		local row = new("Frame", {
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.new(0, 0, 1, 0),
			Parent = f,
		})
		new("UIListLayout", {
			FillDirection = Enum.FillDirection.Horizontal,
			VerticalAlignment = Enum.VerticalAlignment.Center,
			Padding = UDim.new(0, 5),
			SortOrder = Enum.SortOrder.LayoutOrder,
			Parent = row,
		})
		new("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 0), Parent = row })

		-- v6: an unsaved-change dot. UIListLayout lays out only visible siblings, so a clean tab
		-- (dot invisible) keeps the exact row it had; a modified one grows a 6px mark before the name.
		local dirtyDot = new("Frame", {
			Name = "CrozixTabDirty",
			Size = UDim2.fromOffset(6, 6),
			BackgroundColor3 = T.Text,
			BackgroundTransparency = 0.25,
			Visible = tab.text ~= tab.base,
			LayoutOrder = 0,
			Parent = row,
		})
		corner(dirtyDot, CROZIX.D.R.PILL)
		tabDots[i] = dirtyDot
		local nameBtn = new("TextButton", {
			Text = tab.name,
			TextSize = 11,
			Font = isActive and Enum.Font.GothamBold or Enum.Font.GothamMedium,
			TextColor3 = isActive and T.Text or T.Muted,
			AutomaticSize = Enum.AutomaticSize.X,
			Size = UDim2.new(0, 0, 1, 0),
			LayoutOrder = 1,
			Parent = row,
		})
		-- A real glyph, not a drawn icon: at 9px the drawn X's 0.975px strokes rounded to nothing and
		-- the control existed without being visible. The multiplication sign at 16px is a whole glyph the
		-- engine cannot thin away, and the button under it is a full 44x44 hit area beside the tab name.
		local closeBtn = new("TextButton", {
			Text = "×",
			Font = Enum.Font.GothamBold,
			TextSize = CROZIX.D.TYPE.Section,
			TextColor3 = isActive and T.Text or T.Muted,
			BackgroundColor3 = T.Stroke,
			Size = UDim2.fromOffset(CROZIX.D.HIT, CROZIX.D.HIT),
			LayoutOrder = 2,
			Parent = row,
		})
		corner(closeBtn, CROZIX.D.R.XS)
		hover(closeBtn, 1, 0.72, "BackgroundTransparency")
		if not isActive then
			hover(nameBtn, T.Muted, T.Text, "TextColor3")
		end

		local rule = new("Frame", {
			Name = "CrozixTabRule",
			Visible = isActive,
			BackgroundTransparency = 0,
			BackgroundColor3 = T.Accent,
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, 6, 1, 0),
			Size = UDim2.new(1, -12, 0, 2),
			Parent = f,
		})
		-- The brief asks the tab indicator to travel rather than pop. rebuildTabs() destroys every row
		-- on each switch, so one bar shared across the tabs would have to be placed inside a scrolling
		-- frame that is also moving; what can be done truthfully here is to draw the rule in: it sweeps
		-- open from the tab left edge over the section duration, and stands at full width when motion is
		-- switched off in Settings.
		if isActive and CROZIX.effectsOn() then
			rule.Size = UDim2.new(0, 0, 0, 2)
			tw(rule, CROZIX.D.MOTION.TabRule, { Size = UDim2.new(1, -12, 0, 2) }, Enum.EasingStyle.Quart)
		end

		nameBtn.Activated:Connect(function()
			selectTab(i)
		end)
		closeBtn.Activated:Connect(function()
			if closing then
				return
			end
			-- v6: the close itself, unchanged in motion. Only the text fades, so the card, the gutter
			-- and the pill row never jump, and a second tap while the fade runs is ignored.
			local function doClose()
				closing = true
				task.wait(0.1)
				if #tabs == 1 then
					tabs[1].text = ""
					tabs[1].base = ""
					selectTab(1)
				else
					table.remove(tabs, i)
					if active > #tabs then
						active = #tabs
					elseif i < active then
						active -= 1
					end
					selectTab(active)
				end
				closing = false
			end
			-- v6: unsaved work asks before it goes; a clean tab closes as it always did.
			local tab = tabs[i]
			if tab and tab.text ~= tab.base then
				CROZIX.confirmDiscard(tab.name, doClose)
				return
			end
			doClose()
		end)
		tabFrames[#tabFrames + 1] = f
	end
end

function selectTab(i)
	active = math.clamp(i, 1, #tabs)
	loading = true
	Box.Text = tabs[active].text
	loading = false
	-- The write above is silent on purpose, and the handler that dismisses the welcome plate returns
	-- early while it happens. Without this line a restored buffer -- the normal state after a join --
	-- left "CROZIX / Welcome. Start typing" painted over the player's own script, which is what the
	-- tablet showed on 2026-11-16. The plate reads the box it is covering, once.
	if type(CROZIX.welcomeShown) == "function" then
		CROZIX.welcomeShown()
	end
	-- The write above is deliberately silent, so the buffer has to be pointed at the buffer the
	-- player is now looking at, or the next join reopens a tab they had already left.
	refreshView()
	rebuildTabs()
	-- The box keeps its own scroll and never tells anyone where it is, so the only way back to
	-- the top of a newly opened buffer is to put the caret at the start of it.
	Box.CursorPosition = 1
	if CROZIX.welcomeShown then
		CROZIX.welcomeShown()
	end
	if type(CROZIX.persistTabs) == "function" then
		CROZIX.persistTabs()
	end
end

-- A main app gives you back what you were doing. The first tab opens on the last buffer the panel
-- saved, and falls back to the reference's demo script when there is none.
-- Pages are a workspace, so they survive a restart: the count, every page's text and the page that
-- was on screen go to Crozix/tabs.txt as one length-prefixed payload. The helpers hang off CROZIX
-- rather than sitting in nine more locals, because this whole body is one function and Lua caps it
-- at 200. The write is read back, so a file that silently did not take the text cannot look saved.
do
	local TABS_FILE = "Crozix/tabs.txt"
	local TNL = string.char(10)
	local function encode()
		local parts = { "CROZIXT1" .. TNL, #tabs .. TNL, active .. TNL }
		for _, t in ipairs(tabs) do
			parts[#parts + 1] = #t.name .. TNL .. t.name .. TNL
			parts[#parts + 1] = #t.text .. TNL .. t.text .. TNL
		end
		return table.concat(parts)
	end
	local function decode(raw)
		if type(raw) ~= "string" or raw:sub(1, 8) ~= "CROZIXT1" then
			return nil
		end
		local i = 10
		local function take()
			local digits = raw:match("^%d+", i)
			if not digits then
				return nil
			end
			local n = tonumber(digits)
			i = i + #digits + 1
			local chunk = raw:sub(i, i + n - 1)
			i = i + n + 1
			return chunk
		end
		-- The header is two bare numbers; take() reads a number AND a chunk of that length, so it ate the
		-- active-page number as if it were a string and every restart fell back to a single clean page.
		local digits = raw:match("^%d+", i)
		local count = tonumber(digits)
		local act
		if digits then
			i = i + #digits + 1
			digits = raw:match("^%d+", i)
			if digits then
				act = tonumber(digits)
				i = i + #digits + 1
			end
		end
		if not count or not act or count < 1 then
			return nil
		end
		local out = {}
		for k = 1, math.min(count, 8) do
			local name = take()
			local text = take()
			if not name or not text then
				return nil
			end
			out[k] = { name = name, text = text, base = text }
		end
		return out, act
	end
	CROZIX.persistTabs = function()
		local payload = encode()
		if not pcall(writefile, TABS_FILE, payload) then
			return false
		end
		local back = nil
		pcall(function()
			if isfile and isfile(TABS_FILE) then
				back = readfile(TABS_FILE)
			end
		end)
		return type(back) == "string"
			and string.gsub(back, string.char(13) .. TNL, TNL) == payload
	end
	local restored, restoredActive
	local raw = nil
	pcall(function()
		if isfile and isfile(TABS_FILE) then
			raw = readfile(TABS_FILE)
		end
	end)
	if type(raw) == "string" then
		restored, restoredActive = decode(string.gsub(raw, string.char(13) .. TNL, TNL))
	end
	if restored then
		for _, t in ipairs(restored) do
			tabs[#tabs + 1] = t
		end
		tabCounter = #tabs
		active = math.clamp(restoredActive or 1, 1, #tabs)
	else
		-- First run: exactly one page, holding the last buffer if the panel had one. The welcome
		-- greeting is a plate over the box, so a new page's buffer is genuinely empty.
		addTab(nil, CROZIX.loadBuffer() or "")
	end
end

-- The two files the engine reads back later: the buffer the next join reopens, and auto.lua
-- the boot path runs. Both are written on a one-second throttle while typing, so anything that
-- changes the text without another keystroke -- clearing it, executing it, switching tabs --
-- has to go through here, or the old text outlives the deletion.
	local function flushBuffer()
		CROZIX.lastBuffer = os.clock()
		CROZIX.saveBuffer(Box.Text)
	end
	CROZIX.flushBuffer = flushBuffer
connect(Box:GetPropertyChangedSignal("Text"), function()
	if loading then
		return
	end
	local text = Box.Text
	if text:find("\t", 1, true) then
		local cp = Box.CursorPosition
		local _, tabsBefore = text:sub(1, math.max(cp - 1, 0)):gsub("\t", "")
		loading = true
		Box.Text = text:gsub("\t", "    ")
		loading = false
		if cp > 0 then
			Box.CursorPosition = cp + tabsBefore * 3
		end
	end
	tabs[active].text = Box.Text
	if tabDots[active] then
		tabDots[active].Visible = tabs[active].text ~= tabs[active].base
	end
	if CROZIX.welcomeShown then
		CROZIX.welcomeShown()
	end
	-- One write per second while typing, so the mobile storage is not touched on every keystroke.
	if os.clock() - (CROZIX.lastBuffer or 0) > 1 then
		CROZIX.flushBuffer()
		if type(CROZIX.persistTabs) == "function" then
			CROZIX.persistTabs()
		end
	end
	-- AutoExec is a folder the player fills from a file manager now, not a copy of this
	-- buffer, so typing here has nothing left to keep in step with.
	refreshView()
end)

connect(Box:GetPropertyChangedSignal("CursorPosition"), function()
	-- One layer now, so there is nothing to scroll to the caret: the box reveals its own caret the way
	-- the platform does. What the panel still owes anyone is the reading, and the harness's copy of it
	-- so a screenshot can be checked against a number. Crozix/harness.txt is absent on a player's install.
	if CROZIX.harness then
		local line, col = EDITOR:caret()
		local p = Box.AbsolutePosition
		local s = Box.AbsoluteSize
		pcall(writefile, "Crozix/caret.txt", string.format(
			"line=%d col=%d charW=%.2f lineH=%.2f box=%.0f,%.0f %.0fx%.0f well=%.0fx%.0f",
			line, col, CHAR_W, LINE_H, p.X, p.Y, s.X, s.Y,
			EDITOR.Area.AbsoluteSize.X, EDITOR.Area.AbsoluteSize.Y))
	end
end)

local function openScript(name, content)
	for i, t in ipairs(tabs) do
		if t.name == name then
			t.text = content
			t.base = content
			selectTab(i)
			return
		end
	end
	local idx = addTab(name, content)
	if idx then
		selectTab(idx)
	end
end

-- shared saved-scripts list (used by the popup and the Saved section)
------------------------------------------------------------------
------------------------------------------------------------------
------------------------------------------------------------------
------------------------------------------------------------------
------------------------------------------------------------------
-- DIALOGS: the questions the player has to answer before anything is written
-- The whole panel body is one Lua function, and Lua caps a function at 200 locals. The dialog state
-- therefore lives in one table instead of nine named locals, and the helpers only the dialog needs
-- hang off that table for the same reason.
local DLG = {}
local refreshSavedLists

local function trimText(s)
	return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", ""))
end

-- Built once and filled per call: a dialog that costs new instances every time it opens is a dialog
-- that leaks on a tablet already running a game.
local function ensureDialog()
	if DLG.dim then
		return
	end
	DLG.dim = new("TextButton", {
		Name = "CrozixDialogDim",
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Visible = false,
		ZIndex = 40,
		Parent = Root,
	})
	DLG.card = new("Frame", {
		Name = "CrozixDialog",
		-- Top-anchored on purpose. The Android keyboard does not shrink the ScreenGui, so a dialog
		-- centred in the window buries its own buttons under the keys the moment a field takes focus.
		AnchorPoint = Vector2.new(0.5, 0),
		Position = UDim2.fromScale(0.5, 0.05),
		Size = UDim2.fromOffset(300, 150),
		BackgroundColor3 = T.Card,
		Active = true,
		ZIndex = 41,
		Parent = DLG.dim,
	})
	corner(DLG.card, 12)
	stroke(DLG.card, T.Stroke, 1, 0.2)
	DLG.card.BackgroundTransparency = 0
	DLG.title = new("TextLabel", {
		Text = "",
		Font = Enum.Font.GothamBold,
		TextSize = 15,
		TextColor3 = T.Text,
		TextXAlignment = Enum.TextXAlignment.Left,
		Position = UDim2.fromOffset(16, 14),
		Size = UDim2.new(1, -32, 0, 20),
		ZIndex = 42,
		Parent = DLG.card,
	})
	DLG.body = new("TextLabel", {
		Text = "",
		Font = Enum.Font.GothamMedium,
		TextSize = 11,
		TextColor3 = T.Muted,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		TextWrapped = true,
		Position = UDim2.fromOffset(16, 36),
		Size = UDim2.new(1, -32, 0, 28),
		ZIndex = 42,
		Parent = DLG.card,
	})
	-- A plate behind each box, because a Roblox TextBox paints its text flush against its own left
	-- edge: without the inset the name started on top of the field outline.
	DLG.namePlate = new("Frame", {
		Name = "CrozixDlgNamePlate",
		BackgroundColor3 = T.Editor,
		BackgroundTransparency = 0,
		Size = UDim2.new(1, -32, 0, 30),
		ZIndex = 42,
		Parent = DLG.card,
	})
	corner(DLG.namePlate, 8)
	stroke(DLG.namePlate, T.StrokeSoft, 1, 0.4)
	DLG.name = new("TextBox", {
		Name = "CrozixDlgName",
		Text = "",
		PlaceholderText = "Script name",
		ClearTextOnFocus = false,
		Font = Enum.Font.GothamMedium,
		TextSize = 12,
		TextColor3 = T.Text,
		PlaceholderColor3 = T.Muted,
		TextXAlignment = Enum.TextXAlignment.Left,
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(10, 0),
		Size = UDim2.new(1, -20, 1, 0),
		ZIndex = 43,
		Parent = DLG.namePlate,
	})
	-- The same component the code pane builds with, so the dialog gets the same clipping, the same
	-- measured layout and the same colours. It used to be a bare TextBox sitting on a plate that never
	-- clipped: a script longer than the plate's seven lines painted on over the card's own edge, which
	-- is the player seeing "the code leaves the window" while editing a saved script.
	DLG.codeView = makeCodeView(DLG.card, {
		position = UDim2.fromOffset(16, 104),
		w = 268,
		h = 112,
		placeholder = "Script code",
	})
	DLG.codePlate = DLG.codeView.Area
	DLG.code = DLG.codeView.Box
	DLG.codePlate.Name = "CrozixDlgCodePlate"
	DLG.code.Name = "CrozixDlgCode"
	DLG.codePlate.BackgroundTransparency = 0
	DLG.codePlate.ZIndex = 42
	DLG.code.ZIndex = 43
	DLG.code:GetPropertyChangedSignal("Text"):Connect(function()
		DLG.codeView:render(DLG.code.Text)
	end)
	DLG.row = new("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		BackgroundTransparency = 1,
		Position = UDim2.new(0, 16, 1, -16),
		Size = UDim2.new(1, -32, 0, CROZIX.D.HIT),
		ZIndex = 42,
		Parent = DLG.card,
	})

	-- Bug 1. The keys are not part of the layout and the ScreenGui does not shrink when they open, so
	-- the dialog cannot be measured against them. It does the one thing that works whatever their
	-- height: pinned to the top of the screen, it hands the code field back the 78px its own buttons
	-- need, and takes them again when the field loses focus. Everything is pcall'd -- an engine without
	-- TextBoxFocused leaves the dialog exactly where it is instead of failing.
	do
		-- Only the resting position is remembered. The first version also captured the three
		-- heights so it could cut 78px from each one while the keyboard was up, and the render shows
		-- what that cost: the code well went 100 -> 22 and the name field, which sits at a fixed offset
		-- inside the card, fell below the card's own bottom edge -- the buttons stayed visible, the
		-- field the player types into left the dialog.
		local HOME = { pos = DLG.card.Position }
		local lifting = false
		local function setDialogLift(on)
			if on == lifting or not (DLG.card and DLG.card.Parent) then
				return
			end
			lifting = on
			local dur = on and CROZIX.D.MOTION.Open or CROZIX.D.MOTION.Section
			pcall(function()
				tw(DLG.card, dur, { Position = on and UDim2.fromScale(0.5, 0.012) or HOME.pos })
			end)
			CROZIX.dialogLifted = on
		end
		pcall(function()
			UserInputService.TextBoxFocused:Connect(function(field)
				if field ~= DLG.codeView.Box then
					return
				end
				setDialogLift(true)
			end)
			UserInputService.TextBoxFocusReleased:Connect(function(field)
				if field ~= DLG.codeView.Box then
					return
				end
				setDialogLift(false)
			end)
		end)
		CROZIX.setDialogLift = setDialogLift
	end
	new("UIListLayout", {
		FillDirection = Enum.FillDirection.Horizontal,
		HorizontalAlignment = Enum.HorizontalAlignment.Right,
		Padding = UDim.new(0, 8),
		SortOrder = Enum.SortOrder.LayoutOrder,
		Parent = DLG.row,
	})
	CROZIX.register("CrozixDialog", DLG.card)
	DLG.dim.Activated:Connect(function()
		DLG.close()
	end)
end

-- The same pill the editor row uses, so a dialog answer and an editor command look like one family.
local function dlgButton(text, kind, width, order, fn)
	-- Graphite carries the answer and red is saved for the one that destroys something: a filled red
	-- primary here would be the same mistake the panel already made before the theme pass. The primary
	-- lifts one surface step and takes a red hairline instead.
	local variant = (kind == "accent" and "primary") or (kind == "danger" and "danger")
		or (kind == "ghost" and "ghost") or "secondary"
	local base = buttonStyles()[variant].fill
	local b = new("TextButton", {
		Text = text,
		Font = Enum.Font.GothamBold,
		TextSize = 12,
		TextColor3 = T.Text,
		BackgroundColor3 = base,
		BackgroundTransparency = 0,
		Size = UDim2.fromOffset(width, CROZIX.D.HIT),
		ZIndex = 43,
		Parent = DLG.row,
	})
	b.LayoutOrder = order
	corner(b, CROZIX.D.R.PILL)
	styleButton(b, variant)
	if kind == "accent" then
		-- Keep the dialog's own primary plate, so a form can say "not yet" before the tap instead of
		-- only after it. CROZIX.editSavedScript is the one that uses it.
		DLG.primary = b
	end
	b.Activated:Connect(function()
		if fn then
			fn()
		else
			DLG.close()
		end
	end)
	return b
end

DLG.open = function(spec)
	ensureDialog()
	DLG.title.Text = spec.title or ""
	DLG.body.Text = spec.body or ""
	DLG.body.Visible = (spec.body or "") ~= ""
	local y = DLG.body.Visible and 60 or 38
	DLG.namePlate.Visible = spec.name ~= nil
	DLG.name.Text = spec.name or ""
	DLG.namePlate.Position = UDim2.fromOffset(16, y)
	if spec.name ~= nil then
		y = y + 36
	end
	DLG.codePlate.Visible = spec.code ~= nil
	DLG.code.Text = spec.code or ""
	DLG.codePlate.Position = UDim2.fromOffset(16, y)
	if spec.code ~= nil then
		-- Setting the text only fires TextChanged when it actually changes, and the view has to be
		-- sized to this buffer before the card is sized to the view.
		DLG.codeView:render(DLG.code.Text)
		DLG.code.CursorPosition = 1
		y = y + 112
	end
	-- The card starts 19 units down and the keys cover the window below ~220, so this stays visible.
	-- The row is anchored at its own bottom, 16 off the card's, and is 44 tall, so it owns the last 60
	-- units of the card. y has already passed the last field, so the height has to add that 60 plus a
	-- gap; at 42 the name dialog came out 138 tall, its row top landed at 78, and the name plate runs
	-- 60..90 -- the Cancel and Save pills were drawn across the field. 66 gives the name dialog 162
	-- (row top 102, 12 clear of the plate) and the code dialog 274 (row top 214, 6 clear of the well).
	DLG.card.Size = UDim2.fromOffset(300, y + 66)
	for _, c in ipairs(DLG.row:GetChildren()) do
		if c:IsA("GuiObject") then
			c:Destroy()
		end
	end
	for i, b in ipairs(spec.buttons or {}) do
		dlgButton(b.text, b.kind, b.width or 92, i, b.fn)
	end
	DLG.dim.Visible = true
	DLG.dim.BackgroundTransparency = 1
	DLG.card.Position = UDim2.new(0.5, 0, 0.05, 10)
	tw(DLG.dim, 0.14, { BackgroundTransparency = 0.5 })
	tw(DLG.card, 0.18, { Position = UDim2.fromScale(0.5, 0.05) }, Enum.EasingStyle.Back,
		Enum.EasingDirection.Out)
	if spec.name ~= nil then
		task.delay(0.22, function()
			pcall(function()
				DLG.name:CaptureFocus()
			end)
		end)
	end
end

DLG.close = function()
	if not DLG.dim or not DLG.dim.Visible then
		return
	end
	local tr = tw(DLG.dim, 0.12, { BackgroundTransparency = 1 })
	if tr and tr.Completed then
		tr.Completed:Connect(function()
			DLG.dim.Visible = false
		end)
	end
end

-- Every write goes through CROZIX, which reads the payload back off the disk before it says it
-- worked, so none of these toasts can claim a script the device does not hold.
DLG.write = function(name, body)
	if not CROZIX.save(name, body) then
		return false
	end
	saved[name] = body
	refreshSavedLists()
	return true
end

DLG.forget = function(name)
	saved[name] = nil
	local ok = CROZIX.forget(name)
	refreshSavedLists()
	return ok
end

DLG.commitSaveAs = function(wanted)
	local tab = tabs[active]
	if not tab then
		return
	end
	local name = trimText(wanted)
	if name == "" then
		name = tab.name
	end
	local replacing = saved[name] ~= nil and name ~= tab.name
	if Config.OnSave then
		local ok, res = pcall(Config.OnSave, name, tab.text)
		if not ok or res == false then
			notify("Could not save " .. name, T.Red)
			return
		end
	end
	if not DLG.write(name, tab.text) then
		notify("Could not save " .. name, T.Red)
		return
	end
	tab.name = name
	tab.base = tab.text
	rebuildTabs()
	DLG.close()
	notify((replacing and 'Replaced "' or 'Saved "') .. name .. '"', T.Green)
end

DLG.commitEdit = function(oldName)
	local name = trimText(DLG.name.Text)
	if name == "" then
		notify("The script needs a name", T.Yellow)
		return
	end
	if name ~= oldName and saved[name] ~= nil then
		notify('"' .. name .. '" is already saved', T.Yellow)
		return
	end
	if not CROZIX.save(name, DLG.code.Text) then
		notify("Could not save " .. name, T.Red)
		return
	end
	if name ~= oldName then
		DLG.forget(oldName)
		for _, t in ipairs(tabs) do
			if t.name == oldName then
				t.name = name
			end
		end
		rebuildTabs()
	end
	saved[name] = DLG.code.Text
	refreshSavedLists()
	DLG.close()
	notify('Updated "' .. name .. '"', T.Green)
end

function CROZIX.askSaveName()
	local tab = tabs[active]
	if not tab then
		return
	end
	DLG.open({
		title = "Name this script",
		body = "It joins Saved Scripts under this name. Leave it as it is to keep the tab's name.",
		name = tab.name,
		buttons = {
			{ text = "Cancel", kind = "ghost", width = 78 },
			{ text = "Save", kind = "accent", width = 84, fn = function()
				DLG.commitSaveAs(DLG.name.Text)
			end },
		},
	})
end

function CROZIX.editSavedScript(name)
	DLG.open({
		title = "Edit script",
		name = name,
		code = saved[name] or "",
		buttons = {
			{ text = "Cancel", kind = "ghost", width = 78 },
			{ text = "Save changes", kind = "accent", width = 122, fn = function()
				DLG.commitEdit(name)
			end },
		},
	})
	-- commitEdit refuses an empty name with "The script needs a name" after the tap. This says the
	-- same thing before it, on the button system's own Disabled look, and adds no rule: the guard is
	-- the one that was already there. Scoped by the plate's own word, so Save-as is untouched - an
	-- empty name is legal there and falls back to the tab's name.
	local function syncSavePlate()
		if DLG.primary and DLG.primary.Text == "Save changes" then
			CROZIX.setButtonEnabled(DLG.primary, trimText(DLG.name.Text) ~= "")
		end
	end
	if DLG.nameSync then
		DLG.nameSync:Disconnect()
	end
	DLG.nameSync = DLG.name:GetPropertyChangedSignal("Text"):Connect(syncSavePlate)
	syncSavePlate()
end

function CROZIX.confirmDeleteSaved(name)
	DLG.open({
		title = "Delete this script?",
		body = '"' .. name .. '" is removed from the device. This cannot be undone.',
		buttons = {
			{ text = "Cancel", kind = "ghost", width = 78 },
			{ text = "Yes, delete", kind = "danger", width = 108, fn = function()
				local ok = DLG.forget(name)
				DLG.close()
				notify(ok and ('Deleted "' .. name .. '"') or ("Could not delete " .. name),
					ok and T.Green or T.Red)
			end },
		},
	})
end
-- v6: the one question both destructive editor actions ask. Cancel is a real cancel: the callback
-- never runs, so nothing is cleared or closed. Discard closes the dialog, then runs the action.
function CROZIX.confirmDiscard(name, onConfirm)
	DLG.open({
		title = "Discard unsaved changes?",
		body = name .. " has changes that are not saved. Continuing discards them.",
		buttons = {
			{ text = "Cancel", kind = "ghost", width = 78 },
			{ text = "Discard", kind = "danger", width = 92, fn = function()
				DLG.close()
				if onConfirm then
					onConfirm()
				end
			end },
		},
	})
end
local function makeList(parent, pos, size)
	local list = new("ScrollingFrame", {
		Position = pos,
		Size = size,
		CanvasSize = UDim2.new(),
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = T.Stroke,
		Parent = parent,
	})
	new("UIListLayout", { Padding = UDim.new(0, 5), SortOrder = Enum.SortOrder.Name, Parent = list })
	return list
end

local function populateSaved(list, onPick)
	for _, c in ipairs(list:GetChildren()) do
		if c:IsA("GuiObject") then
			c:Destroy()
		end
	end
	local any = false
	for name, content in pairs(saved) do
		any = true
		local row = new("TextButton", {
			Name = name,
			BackgroundTransparency = 0.2,
			BackgroundColor3 = T.Card,
			Size = UDim2.new(1, -4, 0, CROZIX.D.HIT + 4),
			Parent = list,
		})
		corner(row, CROZIX.D.R.XS)
		hover(row, T.Card, T.Stroke)
		Icon.new("code", row, 14, T.Muted, {
			AnchorPoint = Vector2.new(0, 0.5),
			Position = UDim2.new(0, 10, 0.5, 0),
		})
		new("TextLabel", {
			Text = name,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Position = UDim2.fromOffset(33, 0),
			Size = UDim2.new(1, -96, 1, 0),
			Parent = row,
		})
		-- Two marks on the row, and the owner's own reasoning for both: editing a saved script should
		-- be one tap away, and deleting one must never happen on a mis-tap. The hairline keeps them
		-- from reading as one wide target.
		local del = new("TextButton", {
			Name = "CrozixSavedDelete",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -4, 0, 0),
			Size = UDim2.fromOffset(CROZIX.D.HIT, CROZIX.D.HIT + 4),
			ZIndex = 2,
			Parent = row,
		})
		local dic = centerIcon(del, "close", 16, T.TextSecondary)
		iconHover(del, dic, T.TextSecondary, T.Red)
		local edit = new("TextButton", {
			Name = "CrozixSavedEdit",
			AnchorPoint = Vector2.new(1, 0),
			Position = UDim2.new(1, -48, 0, 0),
			Size = UDim2.fromOffset(CROZIX.D.HIT, CROZIX.D.HIT + 4),
			ZIndex = 2,
			Parent = row,
		})
		local eic = centerIcon(edit, "pencil", 16, T.TextSecondary)
		iconHover(edit, eic, T.TextSecondary, T.Text)
		new("Frame", {
			AnchorPoint = Vector2.new(1, 0.5),
			BackgroundColor3 = T.StrokeSoft,
			BackgroundTransparency = 0.55,
			Position = UDim2.new(1, -48, 0.5, 0),
			Size = UDim2.new(0, 1, 0, 16),
			ZIndex = 2,
			Parent = row,
		})
		row.Activated:Connect(function()
			onPick(name, content)
		end)
		edit.Activated:Connect(function()
			CROZIX.editSavedScript(name)
		end)
		del.Activated:Connect(function()
			CROZIX.confirmDeleteSaved(name)
		end)
	end
	-- The third list in the panel, and the last one that used to answer an empty state with a lone
	-- grey line. Same language as Search and the console: a light glyph, a title, one quiet line.
	if not any then
		local state = new("Frame", {
			Name = "CrozixEmptyState",
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			Parent = list,
		})
		Icon.new("save", state, 60, T.Muted, {
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, -50),
			BackgroundTransparency = 1,
		})
		new("TextLabel", {
			Text = "No saved scripts yet",
			Font = Enum.Font.GothamBold,
			TextColor3 = T.TextSecondary,
			TextSize = CROZIX.D.TYPE.Section,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, 4),
			Size = UDim2.fromOffset(380, 22),
			Parent = state,
		})
		new("TextLabel", {
			Text = "Press Save in the editor and the script will wait for you here.",
			TextColor3 = T.Muted,
			TextSize = CROZIX.D.TYPE.Caption,
			TextWrapped = true,
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.new(0.5, 0, 0.5, 30),
			Size = UDim2.fromOffset(380, 30),
			Parent = state,
		})
	end
end

-- popup used by the Open button
local Dim = new("TextButton", {
	BackgroundTransparency = 0.45,
	BackgroundColor3 = Color3.new(0, 0, 0),
	Size = UDim2.fromScale(1, 1),
	Visible = false,
	ZIndex = 10,
	Parent = EditorCard,
})
corner(Dim, CROZIX.D.R.MD)

local Popup = new("Frame", {
	AnchorPoint = Vector2.new(0.5, 0.5),
	Position = UDim2.fromScale(0.5, 0.5),
	Size = UDim2.fromOffset(300, 214),
	BackgroundTransparency = 0,
	BackgroundColor3 = T.Card,
	Active = true,
	Parent = Dim,
})
corner(Popup, CROZIX.D.R.MD)
stroke(Popup, T.Stroke, 1, 0.3)
new("TextLabel", {
	Text = "Saved Scripts",
	Font = Enum.Font.GothamBold,
	TextSize = CROZIX.D.TYPE.Section,
	TextXAlignment = Enum.TextXAlignment.Left,
	Position = UDim2.fromOffset(14, 8),
	Size = UDim2.new(1, -50, 0, 24),
	Parent = Popup,
})
-- The header becomes a 44 band and the mark sits flush with the card top, so the close and the
-- title it belongs to share one centre line.
local PopupClose = new("TextButton", {
	AnchorPoint = Vector2.new(1, 0),
	Position = UDim2.new(1, -8, 0, 0),
	Size = UDim2.fromOffset(CROZIX.D.HIT, CROZIX.D.HIT),
	Parent = Popup,
})
local popupCloseIcon = centerIcon(PopupClose, "close", 14, T.Muted)
iconHover(PopupClose, popupCloseIcon, T.Muted, T.Red)

-- 52 puts the list under the 44px header band; the height loses the same 12 it started with, so the
-- bottom inset stays at 10.
local PopupList = makeList(Popup, UDim2.fromOffset(10, 52), UDim2.new(1, -20, 1, -62))

local function showPicker()
	populateSaved(PopupList, function(name, content)
		Dim.Visible = false
		openScript(name, content)
	end)
	Dim.Visible = true
end
PopupClose.Activated:Connect(function()
	Dim.Visible = false
end)
Dim.Activated:Connect(function()
	Dim.Visible = false
end)

-- editor button actions
ExecBtn.Activated:Connect(function()
	local code = Box.Text
	if code:match("^%s*$") then
		notify("Script is empty", T.Yellow)
		return
	end
	local ok, res, msg = pcall(Config.OnExecute, code, tabs[active].name)
	if not ok then
		notify("Error: " .. tostring(res), T.Red)
	elseif res then
		notify(msg or "Executed", T.Green)
	else
		notify(msg or "Execution failed", T.Red)
	end
end)

-- The Extensions pane is built before Box exists, so it reaches the open script through a
-- function the body registers here, where both Box and the tab list are in scope.
CROZIX.activeText = function()
	return Box.Text, tabs[active].name
end

ClearBtn.Activated:Connect(function()
	local tab = tabs[active]
	local function doClear()
		if tab then
			tab.text = ""
			tab.base = ""
		end
		Box.Text = ""
		-- Not a keystroke: reset the dot here, since TextChanged may not fire (or fires before base lands).
		if tabDots[active] then
			tabDots[active].Visible = false
		end
		-- The TextChanged handler throttles its write, and this one has no keystroke after it: a
		-- cleared editor that still had its script on disk would hand the script back next join.
		CROZIX.flushBuffer()
		notify("Editor cleared", T.Muted)
	end
	-- v6: clearing unsaved work asks first; an empty or already-saved buffer clears as before.
	if tab and tab.text ~= tab.base then
		CROZIX.confirmDiscard(tab.name, doClear)
		return
	end
	doClear()
end)

-- AutoExec is a join-time script, so this pill writes the file the boot path already runs, and a
-- second press removes it. Nothing is scheduled while the panel is open: the toast says which way it
-- went, and the file is verified by the same read-back the other stores use.
AutoBtn.Activated:Connect(function()
	-- Pressing this runs the folder. It has nothing to do with the editor buffer, and it does not
	-- leave a switch set for a later session: what runs is what is in the folder right now.
	local ok, ran, total, err = pcall(CROZIX.autoRun)
	if not ok then
		notify("AutoExec failed: " .. tostring(ran), T.Red)
	elseif err then
		notify(err, T.Yellow)
	else
		notify(string.format("AutoExec ran %d of %d scripts from %s", ran, total, CROZIX.AUTO_DIR), T.Green)
	end
	-- Harness only: did the finger reach this button, and what did the folder answer? A player
	-- never has Crozix/harness.txt, and so never pays for the write.
	if CROZIX.harness then
		pcall(writefile, "Crozix/auto_press.txt", string.format(
			"ok=%s ran=%s total=%s err=%s\n", tostring(ok), tostring(ran), tostring(total), tostring(err)))
	end
end)

-- The owner's flow: pressing Save does not drop the script straight into the list. It asks, in a
-- dialog over the dimmed panel, whether this script should get a name -- and only writes once he
-- answers. Cancel is a real cancel: nothing is added and nothing on disk changes.
SaveBtn.Activated:Connect(function()
	local tab = tabs[active]
	if not tab or (tab.text or ""):match("^%s*$") then
		notify("Nothing to save", T.Yellow)
		return
	end
	CROZIX.askSaveName()
end)

AddBtn.Activated:Connect(function()
	local idx = addTab(nil, "-- New script\n")
	if idx then
		selectTab(idx)
		task.defer(function()
			local cw = TabStrip.AbsoluteCanvasSize
			if cw then
				TabStrip.CanvasPosition = Vector2.new(cw.X, 0)
			end
		end)
	end
end)

------------------------------------------------------------------
	CROZIX.step("ui:section_switching")
-- SECTION SWITCHING
------------------------------------------------------------------
local mainShown = false
local currentKey = nil
local switchGen = 0

local function indexOf(key)
	for i, k in ipairs(PANE_ORDER) do
		if k == key then
			return i
		end
	end
	return 1
end

local function showSection(key)
	if key == currentKey or not Panes[key] then
		return
	end
	switchGen += 1
	local gen = switchGen
	local prev = currentKey and Panes[currentKey] or nil
	local dirn = currentKey and (indexOf(key) > indexOf(currentKey) and 1 or -1) or 1
	currentKey = key
	CROZIX.activeSection = key
	-- The editor page is a set of widgets over the game, not a page inside the window: the body's own
	-- glass and stroke fade out while it is up, so the info card, the community card and the editor read
	-- as separate surfaces with real gaps between them. Every other section gets the body back, and so
	-- does the editor if the transparency slider is used later.
	local editorUp = key == "code"
	-- The brief's first depth level is the window itself: window, then cards, then what sits on them.
	-- Hiding the body on the editor page left three boxes floating with nothing joining them, which is
	-- exactly what the offline render showed. The glass keeps whatever the player set, and the cards
	-- read as surfaces on one window again.
	tw(Body, CROZIX.D.MOTION.Section, { BackgroundTransparency = glassBase() })
	local bodyStroke = Body:FindFirstChildOfClass("UIStroke")
	if bodyStroke then
		tw(bodyStroke, CROZIX.D.MOTION.Section, { Transparency = 0.55 })
	end
	-- Over live gameplay the cards need a little more body than they need over the panel: 0.2 alpha
	-- still reads as glass, 0.45 turns the code into a smudge on a bright map.
	-- These three carry every word on the page, so they stay painted whatever the section is.
	-- The floating look the owner asked for comes from the body opening up behind them, not
	-- from the game showing through the letters.
	tw(Info, 0.2, { BackgroundTransparency = 0 })
	tw(Community, 0.2, { BackgroundTransparency = 0 })
	tw(EditorCard, 0.2, { BackgroundTransparency = 0 })
	if CROZIX.harness then
		CROZIX.uiEvents = (CROZIX.uiEvents or "")
			.. string.format("%d section %s\n", math.floor(os.time() * 1000), tostring(key))
		pcall(writefile, "Crozix/ui_events.txt", CROZIX.uiEvents)
	end
	setActiveSide(key)
	if CROZIX.sectionTitle then
		for _, def in ipairs(SIDE) do
			if def.key == key then
				CROZIX.sectionTitle.Text = def.label
				break
			end
		end
	end

	if not mainShown then
		mainShown = true
		Main.Visible = true
		-- The window is a Frame now, so the only thing that moves is its position. A CanvasGroup had to
		-- re-rasterize its whole subtree to fade, and every glyph on it came back soft at this window's
		-- fractional scale; a translate leaves the text exactly the size it was laid out at.
		Main.Position = UDim2.fromOffset(34, -6)
		tween(Main, 0.34, { Position = UDim2.fromOffset(-6, -6) }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
	end

	local nextPane = Panes[key]
	for _, p in pairs(Panes) do
		if p ~= prev and p ~= nextPane then
			p.Visible = false
		end
	end

	-- A section change is a slide, not a cross-fade. The panes are opaque, so the outgoing one leaves in
	-- the same frame the incoming one starts moving: nothing is transparent, nothing is re-rasterized,
	-- and no word on either pane changes size while it travels.
	if prev then
		prev.Visible = false
	end
	nextPane.Position = UDim2.fromOffset(0, dirn * 16)
	nextPane.Visible = true
	tween(nextPane, 0.24, { Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
end

