local HubPane = Panes.search
new("TextLabel", {
	Text = "Script Hub",
	Font = Enum.Font.GothamBold,
	TextSize = 15,
	TextXAlignment = Enum.TextXAlignment.Left,
	Position = UDim2.fromOffset(16, 12),
	Size = UDim2.fromOffset(300, 20),
	Parent = HubPane,
})
local _, HubBox = inputBox(HubPane, UDim2.fromOffset(14, 40), UDim2.fromOffset(484, 34), "search", "Search scripts...")
local HubGo = iconButton(HubPane, "Search", "search", T.Accent, UDim2.fromOffset(112, CROZIX.D.HIT), UDim2.fromOffset(506, 40), nil, 14, 12)
local HubList = makeList(HubPane, UDim2.fromOffset(14, 94), UDim2.fromOffset(604, 212))

-- Bug 5: this used to be one 11px label with nothing around it, and the game showed straight through
-- it. An empty list is a state the player is meant to read, so it gets the same language as the rest
-- of the panel: a light glyph, a title, one quiet line under it, all centred in the space the list
-- would have filled. No new behaviour -- the same two calls paint it.
local function hubMessage(title, caption)
	local state = new("Frame", {
		Name = "CrozixEmptyState",
		BackgroundTransparency = 1,
		Size = UDim2.fromScale(1, 1),
		Parent = HubList,
	})
	-- 60 not 44, Muted not StrokeSoft: the empty-state glyph is the largest thing in the space and the
	-- quietest thing on the screen, which needs a size and a grey of its own. -50 keeps the same air
	-- between glyph and title once the glyph is taller.
	Icon.new("search", state, 60, T.Muted, {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, -50),
		BackgroundTransparency = 1,
	})
	new("TextLabel", {
		Text = title,
		Font = Enum.Font.GothamBold,
		TextColor3 = T.TextSecondary,
		TextSize = CROZIX.D.TYPE.Section,
		TextWrapped = true,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 4),
		Size = UDim2.fromOffset(380, 22),
		Parent = state,
	})
	new("TextLabel", {
		Text = caption,
		TextColor3 = T.Muted,
		TextSize = CROZIX.D.TYPE.Caption,
		TextWrapped = true,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.5, 0, 0.5, 30),
		Size = UDim2.fromOffset(380, 34),
		Parent = state,
	})
end

local function CROZIX_DISCOVERY()
	-- Script Discovery. Everything below talks to ScriptBlox through the engine's own HTTP surface and
	-- paints only what the API actually returned: no seeded rows, no button that looks live and is not,
	-- and no fetch that runs what it downloaded. Run fires the same execute hook the editor's Execute
	-- button fires, so the console, the error text and the shadow environment are identical to running
	-- the player's own script.
	local SB_API = "https://scriptblox.com/api/script/"
	local SB_RAW = "https://scriptblox.com/raw/"
	local SB_HOST = "https://scriptblox.com"
	local SB_ROWS = 10
	local HttpSvc = game:GetService("HttpService")

	local function sbEncode(s)
		local out = {}
		for i = 1, #s do
			local ch = s:sub(i, i)
			-- The unreserved set of the query string. Written as one pattern this became %a%d%.%-_~ - a
			-- sequence, not a class - so nothing ever matched and every letter arrived percent-encoded.
			if ch:match("%w") or ch == "." or ch == "-" or ch == "_" or ch == "~" then
				out[#out + 1] = ch
			else
				out[#out + 1] = string.format("%%%02X", s:byte(i))
			end
		end
		return table.concat(out)
	end

	local function sbUrl(mode, q, page)
		if mode == "trending" then
			return SB_API .. "trending?page=" .. tostring(page) .. "&max=" .. SB_ROWS
		end
		return SB_API .. "search?q=" .. sbEncode(q) .. "&page=" .. tostring(page) .. "&max=" .. SB_ROWS
	end

	-- One HTTP call, deferred when the engine has task.defer: a synchronous request on the UI thread
	-- stops the panel answering for as long as the network takes, and a search box that freezes the
	-- window is not a feature.
	local function sbBody(url, done)
		local function work()
			local ok, body = CROZIX.httpGet(url)
			if not ok then
				done(false, nil, "the script library did not answer")
				return
			end
			done(true, body)
		end
		if type(task) == "table" and type(task.defer) == "function" then
			task.defer(work)
		else
			work()
		end
	end

	-- The two ScriptBlox answers are not the same shape, and that is measured, not assumed: trending
	-- returns { result = { scripts, max } } and ignores page and max, while search returns
	-- { result = { scripts, totalPages, nextPage } } and honours both. Neither one names the page it is
	-- on and neither counts its results, so the page we asked for is carried in and the count is the rows
	-- on the answer. Reading a field the API does not send is how a pane ends up showing zero forever.
	local function sbList(url, asked, mode, done)
		sbBody(url, function(ok, body, err)
			if not ok then
				done(false, nil, nil, err)
				return
			end
			local decoded
			local okJson, res = pcall(function() return HttpSvc:JSONDecode(body) end)
			if okJson and type(res) == "table" and type(res.result) == "table" then
				decoded = res
			end
			if not decoded then
				-- A captive portal or a proxy page is a string that is not a list. Saying "did not answer"
				-- would send the player looking for a network fault that does not exist.
				done(false, nil, nil, "the answer was not a script list")
				return
			end
			local rows = {}
			for _, s in ipairs(decoded.result.scripts or {}) do
				if type(s) == "table" then
					rows[#rows + 1] = {
						name = tostring(s.title or "Script"),
						game = type(s.game) == "table" and tostring(s.game.name or "") or "",
						slug = tostring(s.slug or ""),
						views = tonumber(s.views) or 0,
						needKey = s.key == true,
						universal = s.isUniversal == true,
						image = type(s.image) == "string" and s.image or nil,
						gameImage = type(s.game) == "table" and s.game.imageUrl or nil,
						code = type(s.code) == "string" and s.code or nil,
					}
				end
			end
			done(true, rows, {
				page = asked,
				last = tonumber(decoded.result.totalPages) or 0,
				next = tonumber(decoded.result.nextPage) or 0,
				total = #rows,
				mode = mode,
			})
		end)
	end

	local hub = { mode = "trending", q = "", page = 1, token = 0, run = nil }

	local function hubClear()
		for _, c in ipairs(HubList:GetChildren()) do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
	end

	-- HubList lays its children out by Name, and every child the pane adds is a shelf. The caption and
	-- the pager take the first and last names, and each result shelf carries a two-digit number, so
	-- sorting by the prefix reproduces the API's rank without touching the list the rest of the panel
	-- shares. A shelf is not a script any more: it holds two cards side by side, which is what turns a
	-- ranked list into the two-across grid the brief asks for.
	local function hubCaption(mode, count)
		local row = new("Frame", {
			Name = "00 hubCaption",
			BackgroundTransparency = 1,
			Size = UDim2.new(1, -4, 0, 74),
			Parent = HubList,
		})
		new("TextLabel", {
			Text = "Let's explore",
			Font = Enum.Font.GothamBold,
			TextColor3 = T.Text,
			TextSize = CROZIX.D.TYPE.Title,
			TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.fromOffset(12, 6),
			Size = UDim2.new(1, -24, 0, 24),
			Parent = row,
		})
		new("TextLabel", {
			Text = mode == "trending" and "Best Scripts" or "Results",
			TextColor3 = T.TextSecondary,
			TextSize = CROZIX.D.TYPE.Section,
			TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.fromOffset(12, 32),
			Size = UDim2.new(1, -24, 0, 16),
			Parent = row,
		})
		new("TextLabel", {
			Text = mode == "trending"
				and ("Trending on ScriptBlox - " .. count .. " scripts")
				or ("ScriptBlox results for " .. hub.q),
			TextColor3 = T.Muted,
			TextSize = CROZIX.D.TYPE.Caption,
			TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.fromOffset(12, 52),
			Size = UDim2.new(1, -24, 0, 14),
			Parent = row,
		})
	end

	-- The list answers taken from ScriptBlox today carry no source, so a tap normally costs one more
	-- request to its raw path. Whatever a row did arrive with is kept, so a response that includes the
	-- code is used at once and nothing waits on a fetch that has nothing to fetch.
	local function sbWithCode(r, then_)
		if type(r.code) == "string" and #r.code > 0 then
			then_(r.code)
			return
		end
		if #r.slug == 0 then
			CROZIX.notify("this result has no source address", T.Yellow)
			return
		end
		sbBody(SB_RAW .. sbEncode(r.slug), function(ok, body, err)
			if not ok then
				CROZIX.notify("could not load " .. r.name .. ": " .. tostring(err), T.Red)
				return
			end
			r.code = body
			then_(body)
		end)
	end

	-- Thumbnails. ScriptBlox sends a relative image path with every script and another with its game, and
	-- two things about this engine were measured on the tablet before this was written: request() brings a
	-- PNG back byte-identical (205,625 B, md5 matching the same file pulled on the PC, magic 89 50 4E 47),
	-- and getcustomasset() hands a workspace file back as rbxasset://<hash>/probe_img.png, which is the
	-- channel the rail logo already paints through. What the response does NOT carry is a status code, so
	-- the bytes are the check: a body that does not open with an image signature is a portal page, and it
	-- is neither written nor painted - the slot stays a plate instead of a broken image.
	local HUB_THUMB_DIR = "Crozix/hub/"
	local HUB_THUMB_CAP = 10
	local HUB_THUMB_MAX = 2
	local hubQueue, hubBusy, hubTaken = {}, 0, 0
	-- The pane is a card grid, two across: a banner picture, a bold name, one quiet line and a row of
	-- three actions. The list stacks ROW frames (it sorts by Name), and each row carries two cards side
	-- by side, so ten scripts are five rows and the pictures are the colour in the pane. The grid state
	-- lives outside hubCard: it is called once per script, and which row a card lands in is decided by
	-- which call this is, not by the script itself.
	local CARD_COLS = 2
	local CARD_GAP = 8
	-- The list is 604 wide and its rows carry a 4-unit inset, so two cards and the gap between them are
	-- 592 units: 296 each. The number is written once rather than derived, because the pane width is a
	-- fixture of the layout and the two cards must meet in the middle exactly.
	local CARD_W = 296
	local CARD_THUMB = 96
	local CARD_H = 196
	local hubGrid = { col = 0, row = nil, index = 0 }

	local function hubIsImage(b)
		if type(b) ~= "string" or #b < 16 then
			return false
		end
		local b1, b2, b3, b4 = b:byte(1, 4)
		local b9, b10, b11, b12 = b:byte(9, 12)
		if b1 == 137 and b2 == 80 and b3 == 78 and b4 == 71 then
			return true                                  -- PNG
		end
		if b1 == 255 and b2 == 216 and b3 == 255 then
			return true                                  -- JPEG
		end
		if b1 == 71 and b2 == 73 and b3 == 70 and b4 == 56 then
			return true                                  -- GIF8
		end
		if b1 == 82 and b2 == 73 and b3 == 70 and b4 == 70
			and b9 == 87 and b10 == 69 and b11 == 66 and b12 == 80 then
			return true                                  -- RIFF / WEBP
		end
		return false
	end

	local function hubSafeName(url)
		local name = tostring(url):match("[^/]+$") or ""
		name = (name:gsub("[^%w%.%-_]", ""))
		if #name == 0 then
			name = "thumb"
		end
		if #name > 48 then
			name = name:sub(#name - 47)
		end
		return name
	end

	local function hubImageOf(r)
		local path = r.image
		if type(path) ~= "string" or #path == 0 then
			path = r.gameImage
		end
		if type(path) ~= "string" or #path == 0 or path:sub(1, 1) ~= "/" then
			return nil
		end
		return SB_HOST .. path
	end

	local function hubShow(img, path)
		local url = CROZIX.assetAt(path)
		if #url > 0 then
			img.Image = url
			img.BackgroundTransparency = 1
		end
	end

	-- One image per frame at most, and never more than HUB_THUMB_MAX in flight. This is deliberately not a
	-- loop that drains the queue when a fetch answers: on an engine where the HTTP call returns on the
	-- calling thread, that recursion would download the whole page inside the first row's paint and the
	-- window would stop answering for a second per thumbnail. The frame tick is the pump, so the pictures
	-- arrive as the player watches them rather than before the first row appears.
	local function hubPump()
		if hubBusy >= HUB_THUMB_MAX or #hubQueue == 0 then
			return
		end
		local job = table.remove(hubQueue, 1)
		hubBusy = hubBusy + 1
		sbBody(job.url, function(ok, body)
			hubBusy = hubBusy - 1
			if ok and hubIsImage(body) then
				pcall(writefile, job.path, body)
				-- A newer search destroys the row it was painting; a label without a parent is not painted.
				if job.img.Parent then
					hubShow(job.img, job.path)
				end
			end
		end)
	end

	local function hubThumb(img, url)
		if type(url) ~= "string" or #url == 0 then
			return
		end
		if type(makefolder) == "function" and (type(isfolder) ~= "function" or not isfolder("Crozix/hub")) then
			pcall(makefolder, "Crozix/hub")
		end
		local path = HUB_THUMB_DIR .. hubSafeName(url)
		if type(isfile) == "function" and isfile(path) then
			hubShow(img, path)
			return
		end
		if hubTaken >= HUB_THUMB_CAP then
			return
		end
		hubTaken = hubTaken + 1
		-- Queued, not started: the frame tick is what pumps, so painting a page costs no network at all and
		-- the first row appears as fast as the list answer did.
		table.insert(hubQueue, { url = url, path = path, img = img })
	end

	-- One row's quiet line: whether the author gates the script behind a key of their own, and what the
	-- script is for. The warning leads because the line is the first thing the column truncates - on the
	-- tablet a long game name cut "needs a key" off the end, which is the one fact the player needed
	-- before tapping. When the answer carries neither, the line is not painted.
	local function hubTag(r)
		local head = r.universal and "Universal" or r.game
		if not r.needKey then
			return head
		end
		return #head > 0 and ("needs a key - " .. head) or "needs a key"
	end

	-- One card, three actions that all do something. A button whose action is not available is not drawn,
	-- which is what keeps the card honest instead of decorative. The card is drawn into a shelf the first
	-- time a call needs one, and which shelf it lands on is decided by which call this is, not by the
	-- script itself -- so a ranked answer stays ranked across the grid.
	local function hubCard(r, slot)
		if hubGrid.col == 0 then
			hubGrid.index = hubGrid.index + 1
			hubGrid.row = new("Frame", {
				Name = string.format("%02d", hubGrid.index),
				BackgroundTransparency = 1,
				Size = UDim2.new(1, -4, 0, CARD_H),
				Parent = HubList,
			})
			hubGrid.col = 1
		end
		local card = new("Frame", {
			Name = string.format("%02d", slot),
			BackgroundTransparency = 0.2,
			BackgroundColor3 = T.Card,
			ClipsDescendants = true,
			Size = UDim2.fromOffset(CARD_W, CARD_H),
			Position = UDim2.fromOffset(hubGrid.col == 1 and 0 or (CARD_W + CARD_GAP), 0),
			Parent = hubGrid.row,
		})
		corner(card, CROZIX.D.R.MD)
		-- The same edge the rest of the panel's cards carry, and the same answer to the pointer the saved
		-- rows give: the plate lifts one step. A UIStroke has no MouseEnter to connect - the tablet said so
		-- ("MouseEnter is not a valid member of UIStroke") after the offline mock, which accepts any member
		-- on any instance, had let the call through.
		litStroke(card, T.StrokeSoft, 0.34)
		hover(card, T.Card, T.Stroke)

		-- The banner is a plate first and a picture second: it holds the space the image will fill, so a
		-- card does not jump when the bytes land, and a card whose image never arrives is a card with a
		-- dark band rather than a hole in the grid. ClipsDescendants rounds its top corners to the card's.
		local thumb = new("ImageLabel", {
			Name = "CrozixThumb",
			BackgroundTransparency = 0,
			BackgroundColor3 = T.Editor,
			Image = "",
			Size = UDim2.new(1, 0, 0, CARD_THUMB),
			Position = UDim2.fromOffset(0, 0),
			Parent = card,
		})
		-- The banner is 296x96 and the source is usually a square screenshot; stretching it across the
		-- banner is what smeared the scripts' pictures. Crop scales uniformly and trims the overflow.
		pcall(function()
			thumb.ScaleType = Enum.ScaleType.Crop
		end)
		hubThumb(thumb, hubImageOf(r))

		new("TextLabel", {
			Text = r.name,
			Font = Enum.Font.GothamBold,
			TextColor3 = T.Text,
			TextSize = CROZIX.D.TYPE.Section,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextTruncate = Enum.TextTruncate.AtEnd,
			Position = UDim2.fromOffset(10, CARD_THUMB + 8),
			Size = UDim2.new(1, -20, 0, 18),
			Parent = card,
		})
		-- The quiet line stops where the view count begins: on the tablet the two shared the right-hand
		-- column and the number was drawing under the Run plate, leaving one stray letter on screen. The
		-- card keeps them on one line with the count pinned to the right edge, and the tag's colour says
		-- whether the script is gated behind a key of its own.
		local tag = hubTag(r)
		if #tag > 0 then
			new("TextLabel", {
				Text = tag,
				TextSize = CROZIX.D.TYPE.Caption,
				TextColor3 = r.needKey and T.Red or T.Muted,
				TextXAlignment = Enum.TextXAlignment.Left,
				TextTruncate = Enum.TextTruncate.AtEnd,
				Position = UDim2.fromOffset(10, CARD_THUMB + 30),
				Size = UDim2.new(1, -110, 0, 14),
				Parent = card,
			})
		end
		if r.views > 0 then
			new("TextLabel", {
				Text = string.format("%d views", r.views),
				TextSize = CROZIX.D.TYPE.Caption,
				TextColor3 = T.Muted,
				TextXAlignment = Enum.TextXAlignment.Right,
				Position = UDim2.new(1, -10, 0, CARD_THUMB + 30),
				Size = UDim2.fromOffset(80, 14),
				Parent = card,
			})
		end

		-- 18, and the number is measured rather than chosen. The marks in this glyph set are 1.6-3.2 units
		-- on the builder's 24-unit grid, so at 14 the thinnest is under one pixel and at 16 the play
		-- triangle lands at 1.07 - both under the width this engine has been measured to drop. At 18 every
		-- mark in the pane clears 1.20, and 18 is a size the panel already draws (the import pill).
		local runB = iconButton(card, "Run", "play", T.Green, UDim2.fromOffset(88, CROZIX.D.HIT),
			UDim2.fromOffset(10, CARD_H - 50), nil, 18, 11)
		local editB = iconButton(card, "Edit", "pencil", T.Editor, UDim2.fromOffset(88, CROZIX.D.HIT),
			UDim2.fromOffset(104, CARD_H - 50), nil, 18, 11)
		local saveB = iconButton(card, "Save", "save", T.Editor, UDim2.fromOffset(88, CROZIX.D.HIT),
			UDim2.fromOffset(198, CARD_H - 50), nil, 18, 11)

		-- Never on paint, never twice for one press: the code is fetched and run only when the player taps
		-- Run, and a second tap while the first is in flight is ignored rather than queued.
		-- Both actions go through the same hook the frozen buttons use -- Config.OnExecute for the editor's
		-- Execute, DLG.write for its Save -- so a hub result runs, reports and persists exactly like the
		-- player's own script. Calling CROZIX.save on its own would write the file and leave the row out of
		-- Saved Scripts until the next join, which is a half-action.
		local armed = false
		runB.Activated:Connect(function()
			if armed then return end
			armed = true
			sbWithCode(r, function(code)
				local ok, res, msg = pcall(Config.OnExecute, code, r.name)
				armed = false
				if not ok then
					CROZIX.notify("Error: " .. tostring(res), T.Red)
				elseif res then
					CROZIX.notify(msg or ("ran " .. r.name), T.Green)
				else
					CROZIX.notify(msg or ("could not run " .. r.name), T.Red)
				end
			end)
		end)
		editB.Activated:Connect(function()
			if armed then return end
			armed = true
			sbWithCode(r, function(code)
				armed = false
				openScript(r.name, code)
				showSection("code")
			end)
		end)
		saveB.Activated:Connect(function()
			if armed then return end
			armed = true
			sbWithCode(r, function(code)
				armed = false
				if DLG.write(r.name, code) then
					CROZIX.notify('Saved "' .. r.name .. '"', T.Green)
				else
					CROZIX.notify("Could not save " .. r.name, T.Red)
				end
			end)
		end)
		-- A full shelf wraps back to column zero, so the next card opens the shelf after it.
		hubGrid.col = hubGrid.col + 1
		if hubGrid.col > CARD_COLS then
			hubGrid.col = 0
		end
	end

	-- Only a list with another page gets a pager. Trending answers with one ranked block and no page
	-- metadata at all, so a control there would lead nowhere and its count rides in the caption instead.
	-- Search carries totalPages and nextPage, and the page the player asked for is the page we state,
	-- because the answer never names itself.
	local function hubPager(meta)
		if meta.next <= 0 and meta.page <= 1 then
			return false
		end
		local row = new("Frame", {
			Name = "99 hubPager",
			BackgroundTransparency = 0.2,
			BackgroundColor3 = T.Card,
			Size = UDim2.new(1, -4, 0, CROZIX.D.HIT + 4),
			Parent = HubList,
		})
		corner(row, 8)
		new("TextLabel", {
			Text = meta.last > 0 and string.format("Page %d of %d", meta.page, meta.last)
				or string.format("Page %d", meta.page),
			TextColor3 = T.TextSecondary,
			TextSize = CROZIX.D.TYPE.Caption,
			TextXAlignment = Enum.TextXAlignment.Left,
			Position = UDim2.fromOffset(12, 14),
			Size = UDim2.new(1, -280, 0, 16),
			Parent = row,
		})
		-- The glyph the panel owns is a chevron that points down. Rotation is what turns it into the
		-- pair a pager needs, so the page control uses the frozen icon set instead of a new shape and a
		-- button that cannot act: Prev is drawn only past page one, Next only when the answer offered one.
		if meta.page > 1 then
			local prev, prevIc = iconButton(row, "Prev", "chevron", T.Editor,
				UDim2.fromOffset(72, CROZIX.D.HIT), UDim2.new(1, -264, 0, 2), nil, 18, 11)
			if prevIc and prevIc.Root then
				prevIc.Root.Rotation = 90
			end
			prev.Activated:Connect(function()
				hub.page = meta.page - 1
				hub.run()
			end)
		end
		if meta.next > 0 then
			local nextB, nextIc = iconButton(row, "Next", "chevron", T.Editor,
				UDim2.fromOffset(72, CROZIX.D.HIT), UDim2.new(1, -186, 0, 2), nil, 18, 11)
			if nextIc and nextIc.Root then
				nextIc.Root.Rotation = 270
			end
			nextB.Activated:Connect(function()
				hub.page = meta.next
				hub.run()
			end)
		end
		return true
	end

	-- Painting an answer is where the pane can meet a shape it did not expect, and an error here aborts
	-- the rest of the panel's own startup: the chunk runs top to bottom and Script Discovery sits in the
	-- middle of it. So the paint is guarded and a failure becomes a state the player can read, with the
	-- engine's own words in it, instead of a half-drawn list and a window that stopped building.
	local function hubPaint(rows, meta, mode)
		hubGrid.col = 0
		hubGrid.row = nil
		hubGrid.index = 0
		hubCaption(mode, #rows)
		for i, r in ipairs(rows) do
			hubCard(r, i)
		end
		if type(meta) == "table" then
			hubPager(meta)
		end
	end

	hub.run = function()
		hub.token = hub.token + 1
		local mine = hub.token
		local asked = hub.page
		local mode = hub.mode
		hubClear()
		-- A new answer is a new budget: the rows it replaces are gone, so the queue they queued goes with
		-- them. Requests already in flight land on a label with no parent and are dropped by the guard.
		hubTaken = 0
		for i = #hubQueue, 1, -1 do
			hubQueue[i] = nil
		end
		-- The wait is a state the player reads, not an animation: one quiet line in the space the results
		-- will fill.
		hubMessage("Searching the script library", "ScriptBlox - results appear here when they arrive.")
		sbList(sbUrl(mode, hub.q, asked), asked, mode, function(ok, rows, meta, err)
			if mine ~= hub.token then
				-- A slower answer from an earlier keystroke must not overwrite the newer one.
				return
			end
			hubClear()
			if not ok or type(rows) ~= "table" or #rows == 0 then
				hubMessage(err or "No scripts matched that search",
					"Try a shorter word, or part of a script's name.")
				return
			end
			local painted, why = pcall(hubPaint, rows, meta, mode)
			if not painted then
				hubClear()
				hubMessage("The results could not be drawn", tostring(why))
			end
		end)
	end

	local function hubSubmit()
		hub.q = HubBox.Text
		hub.mode = (#hub.q > 0) and "search" or "trending"
		hub.page = 1
		hub.run()
	end

	HubGo.Activated:Connect(hubSubmit)
	HubBox.FocusLost:Connect(function(enter)
		if enter then
			hubSubmit()
		end
	end)
	-- Debounced live search: every keystroke would be a request, so a deadline collapses a typed word
	-- into one fetch. os.clock is compared, not accumulated, because a frame signal that adds scaled time
	-- drifts on a lagging client. RenderStepped is the tick the panel already runs on (the caret blink
	-- and the window drag both use it), which keeps this inside the surface the engine is known to have.
	local hubDue = 0
	connect(HubBox:GetPropertyChangedSignal("Text"), function()
		hubDue = os.clock() + 0.45
	end)
	connect(RunService.RenderStepped, function()
		if hubDue == 0 or os.clock() < hubDue then return end
		hubDue = 0
		if HubBox.Text == hub.q then return end
		hubSubmit()
	end)
	-- The same tick drives the thumbnail queue, so a page of results costs at most one fetch per frame.
	connect(RunService.RenderStepped, hubPump)
	hub.run()
end
CROZIX_DISCOVERY()

