local SettingsPane = Panes.settings

local function pct(v)
	return math.floor(v * 100 + 0.5) .. "%"
end

-- The reference drew a 42x22 button, which is a target a thumb misses on a phone: rule 5 says 44.
-- The press area is now 44 tall and the track is a child drawn at the same size as before, so the
-- look keeps its scale and the touch stops being a coin flip. The knob travels the extra 2px the
-- wider track gives it, and both moves read the state step from the token table.
local function makeSwitch(parent, pos, value, onChange, name)
	local b = new("TextButton", {
		AnchorPoint = Vector2.new(1, 0),
		Position = pos,
		Size = UDim2.fromOffset(52, CROZIX.D.HIT),
		BackgroundTransparency = 1,
		Parent = parent,
	})
	if name then
		b.Name = name
	end
	local track = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(48, 28),
		BackgroundTransparency = 0,
		BackgroundColor3 = T.Dark,
		Parent = b,
	})
	corner(track, CROZIX.D.R.PILL)
	litStroke(track, T.StrokeSoft, 0.5)
	local knob = new("Frame", {
		AnchorPoint = Vector2.new(0, 0.5),
		Position = UDim2.new(0, 4, 0.5, 0),
		Size = UDim2.fromOffset(20, 20),
		BackgroundTransparency = 0,
		BackgroundColor3 = Color3.new(1, 1, 1),
		Parent = track,
	})
	corner(knob, CROZIX.D.R.PILL)
	local sw = { value = value, button = b }
	function sw.set(v, silent)
		sw.value = v
		tw(track, CROZIX.D.MOTION.State, { BackgroundColor3 = v and T.Accent or T.Dark })
		tw(knob, CROZIX.D.MOTION.State, {
			Position = v and UDim2.new(1, -24, 0.5, 0) or UDim2.new(0, 4, 0.5, 0),
		})
		if not silent and onChange then
			onChange(v)
		end
	end
	b.Activated:Connect(function()
		sw.set(not sw.value)
	end)
	sw.set(value, true)
	return sw
end

local activeSlider
local function makeSlider(parent, pos, width, label, min, max, step, value, fmt, onChange)
	local holder = new("Frame", { Position = pos, Size = UDim2.fromOffset(width, 40), Parent = parent })
	new("TextLabel", {
		Text = label,
		Font = Enum.Font.GothamBold,
		TextXAlignment = Enum.TextXAlignment.Left,
		Size = UDim2.new(0.6, 0, 0, 16),
		Parent = holder,
	})
	local valueLabel = new("TextLabel", {
		Text = "",
		Font = Enum.Font.GothamBold,
		TextColor3 = T.Accent,
		TextXAlignment = Enum.TextXAlignment.Right,
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.fromScale(1, 0),
		Size = UDim2.new(0.4, 0, 0, 16),
		Parent = holder,
	})
	-- 4px of track reads as a line rather than a bar, and the fill is the one place the accent is allowed
	-- to run as a gradient: dark at the left, lit at the thumb, so the value is readable without looking
	-- at the number. The knob grew two pixels and lost its 2px red ring for a single hairline, because a
	-- ring that thick turns a round handle into a bullseye at arm's length.
	local track = new("Frame", {
		-- The rail's own handle: a drive test reaches this frame and gives it AbsolutePosition and
		-- AbsoluteSize, which is the pair the real slider reads. Without it the only offline route to
		-- a slider value was faking the saved file, and that is not the seam the owner moves.
		Name = "CrozixSliderTrack_" .. label:gsub("%s", ""),
		Position = UDim2.fromOffset(0, 30),
		Size = UDim2.fromOffset(width, 4),
		BackgroundTransparency = 0,
		BackgroundColor3 = T.Editor,
		Parent = holder,
	})
	corner(track, CROZIX.D.R.PILL)
	litStroke(track, T.StrokeSoft, 0.55)
	local fillBar = new("Frame", {
		Size = UDim2.fromScale(0, 1),
		BackgroundTransparency = 0,
		BackgroundColor3 = T.Accent,
		ZIndex = 1,
		Parent = track,
	})
	corner(fillBar, CROZIX.D.R.PILL)
	CROZIX.trackEffect(new("UIGradient", {
		Rotation = 0,
		Color = ColorSequence.new(T.AccentDeep, T.AccentHover),
		Parent = fillBar,
	}))
	local knob = new("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0, 0.5),
		Size = UDim2.fromOffset(18, 18),
		BackgroundTransparency = 0,
		BackgroundColor3 = T.Text,
		ZIndex = 2,
		Parent = track,
	})
	corner(knob, CROZIX.D.R.PILL)
	stroke(knob, T.AccentDeep, 1, 0.15)
	-- The press area is the whole row the slider sits in, not a 28px strip across it.
	local hit = new("TextButton", {
		Position = UDim2.fromOffset(-10, 12),
		Size = UDim2.fromOffset(width + 20, CROZIX.D.HIT),
		ZIndex = 3,
		Parent = holder,
	})
		hit.Name = "CrozixSlider_" .. label:gsub("%s", "")
		CROZIX.register(hit.Name, hit)

	local s = { value = value }
	function s.set(v, silent)
		v = math.clamp(math.floor(v / step + 0.5) * step, min, max)
		s.value = v
		local a = (v - min) / (max - min)
		fillBar.Size = UDim2.fromScale(a, 1)
		knob.Position = UDim2.fromScale(a, 0.5)
		valueLabel.Text = fmt(v)
		if not silent and onChange then
			onChange(v)
		end
	end
	function s.update(x)
		local a = math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)
		s.set(min + (max - min) * a)
	end
	hit.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			activeSlider = s
			s.update(input.Position.X)
		end
	end)
	s.set(value, true)
	return s
end
connect(UserInputService.InputChanged, function(input)
	if
		activeSlider
		and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch)
	then
		activeSlider.update(input.Position.X)
	end
end)
connect(UserInputService.InputEnded, function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		activeSlider = nil
		remapSoon()
	end
end)

