local RightCard = card(SettingsScroll, { Position = UDim2.fromOffset(330, 14), Size = UDim2.fromOffset(288, 290) })
-- Protection rows for the Settings pane.
--
-- These four rows are OUR engine's. Two device measurements shaped this file:
--   1. Crozix/prot_env.txt (2026-11-10): the vendor's private setantiscam / setallowrobux /
--      setallowteleports natives are nil in every environment the panel can reach (128 roots,
--      872 functions, found=none). The engine keeps them in a Lua context only its own UI owns.
--   2. Crozix/hook_probe.txt + namecall_probe.txt (2026-11-11): a service method is a stable C
--      closure; hookfunction on it installs but a namecall never reaches it, and calling the hooked
--      C closure directly faults the process. The service is not a Lua table, so its fields cannot
--      be replaced either. The ONE place every `svc:Method()` passes through is the metatable's
--      __namecall -- and a handler that dispatches MANUALLY (look the method up, call it directly)
--      works, blocks, and restores cleanly. Chaining to the original metamethod is what faults, so
--      this file never does that.
--
--   3. Crozix/call.txt (2026-11-11): a game's own LocalScript reaches the marketplace outside that
--      hook -- invoking the gamepass button's handler runs its pcall'd PromptGamePassPurchase and the
--      hooked namecall never sees it. The button that owns such a script is visible from Lua, so the
--      guards also watch purchase buttons and refuse on their click.
--
-- The handler is installed only while at least one guard is on, and removed when the last one goes
-- off, so a player who uses none of this pays nothing for it.
;(function()
	local ProtCard = card(SettingsScroll, { Position = UDim2.fromOffset(14, 318), Size = UDim2.fromOffset(604, 230) })
	new("TextLabel", {
		Text = "Protection",
		Font = Enum.Font.GothamBold,
		TextSize = 15,
		TextXAlignment = Enum.TextXAlignment.Left,
		Position = UDim2.fromOffset(14, 10),
		Size = UDim2.new(1, -28, 0, 20),
		Parent = ProtCard,
	})
	new("Frame", {
		BackgroundColor3 = T.StrokeSoft,
		BackgroundTransparency = 0.5,
		Position = UDim2.fromOffset(14, 34),
		Size = UDim2.new(1, -28, 0, 1),
		Parent = ProtCard,
	})

	local SETTING = { afk = "AntiAfk", scam = "AntiScam", robux = "NoRobux", tele = "SafeTeleports" }

	-- The calls that can move value out of the account, and the calls that can leave this place.
	-- Kept as literals and looked up on the service: a name this build does not have reads as absent.
	local MARKET = {
		"PromptProductPurchase", "PromptGamePassPurchase", "PromptPurchase", "PromptBulkPurchase",
		"PromptNativePurchase", "PromptBundlePurchase", "PromptPremiumPurchase", "PromptRobloxPurchase",
	}
	local CURRENCY = { "PromptCurrencyPurchase", "PromptRobuxPurchase" }
	local TELE = { "Teleport", "TeleportAsync", "TeleportToPlaceInstance", "TeleportPartyAsync", "TeleportToPrivateServer" }
	local KIND = {}
	for i = 1, #MARKET do
		KIND[MARKET[i]] = "purchase"
	end
	for i = 1, #CURRENCY do
		KIND[CURRENCY[i]] = "purchase"
	end
	for i = 1, #TELE do
		KIND[TELE[i]] = "tele"
	end

	local GUARD = { scam = false, robux = false, tele = false }
	local STOPPED = { scam = 0, robux = 0, tele = 0 }
	local CAPS = { route = "none", namecall = "unmeasured", market = 0, currency = 0, tele = 0 }
	local promptSeen, promptKilled = 0, 0
	local alertsShown, marketDropped = 0, 0
	local SRC = { button = 0, namecall = 0, prompt = 0 }
	local tagDup = 0
	local guardAlert

	-- Two copies of this window in one session each listen to the same buttons: one tap then counts
	-- twice while only one message can be seen. The handle travels through the shared executor
	-- environment, so the second copy sees the first copy's tags and leaves them alone.
	local SHARED
	do
		local okg, g = pcall(function()
			if type(getgenv) == "function" then
				return getgenv()
			end
			return nil
		end)
		if okg and type(g) == "table" then
			local okr, reg = pcall(function()
				return rawget(g, "__crozixGuardShared")
			end)
			if not okr or type(reg) ~= "table" then
				reg = { boots = 0, tags = setmetatable({}, { __mode = "k" }) }
				pcall(function()
					rawset(g, "__crozixGuardShared", reg)
				end)
			end
			SHARED = reg
			pcall(function()
				SHARED.boots = (tonumber(SHARED.boots) or 0) + 1
			end)
		end
	end
	local BOOTS = (SHARED and tonumber(SHARED.boots)) or 1

	local function say(line)
		pcall(function()
			if CROZIX.log then
				CROZIX.log(line)
			end
		end)
	end

	-- One line per refusal, on the device, so "the message did not show" can be told apart from
	-- "the block never happened". Appends; capped so a long session cannot grow it without bound.
	local function glog(line)
		pcall(function()
			local prev = ""
			local okr, s = pcall(readfile, "Crozix/guard_log.txt")
			if okr and type(s) == "string" then
				prev = s
				if #prev > 8000 then
					prev = string.sub(prev, -4000)
				end
			end
			writefile("Crozix/guard_log.txt", prev .. tostring(line) .. "\n")
		end)
	end
	glog("boot instance #" .. tostring(BOOTS) .. " shared=" .. tostring(SHARED ~= nil))
	local function svc(name)
		local ok, s = pcall(function()
			return game:GetService(name)
		end)
		if ok and s ~= nil then
			return s
		end
		return nil
	end
	local function api(name)
		local ok, v = pcall(function()
			if type(ENGINE_ENV) == "table" then
				local v0 = rawget(ENGINE_ENV, name)
				if v0 ~= nil then
					return v0
				end
			end
			local e = rawget(_ENV or _G, name)
			if e ~= nil then
				return e
			end
			if type(getgenv) == "function" then
				local ok2, g = pcall(getgenv)
				if ok2 and type(g) == "table" then
					local v2 = rawget(g, name)
					if v2 ~= nil then
						return v2
					end
				end
			end
			return rawget(_G, name)
		end)
		if ok then
			return v
		end
		return nil
	end

	local GRM = api("getrawmetatable")
	local SRO = api("setreadonly")
	local GNM = api("getnamecallmethod")
	local NCC = api("newcclosure")
	local GBC = api("getscriptbytecode")

	local installed, oldNamecall = false, nil
	local measuring, probeHit = false, false

	local function writeLedger()
		if type(writefile) ~= "function" then
			return
		end
		local out = {
			"caps route=" .. CAPS.route .. " namecall=" .. tostring(CAPS.namecall) ..
				" market=" .. CAPS.market .. " currency=" .. CAPS.currency .. " tele=" .. CAPS.tele,
			"guard scam=" .. tostring(GUARD.scam) .. " robux=" .. tostring(GUARD.robux) ..
				" tele=" .. tostring(GUARD.tele),
			"stopped scam=" .. STOPPED.scam .. " robux=" .. STOPPED.robux .. " tele=" .. STOPPED.tele,
			"prompts seen=" .. promptSeen .. " killed=" .. promptKilled,
			"alerts shown=" .. alertsShown .. " market-dropped=" .. marketDropped,
			"calls button=" .. SRC.button .. " namecall=" .. SRC.namecall .. " prompt=" .. SRC.prompt,
			"instance boots=" .. tostring(BOOTS) .. " tag-dup=" .. tagDup,
			"place=" .. tostring(game.PlaceId) .. " afk=" .. tostring(Settings.AntiAfk),
		}
		local names = {}
		for k in pairs(KIND) do
			names[#names + 1] = k
		end
		table.sort(names)
		out[#out + 1] = "methods " .. table.concat(names, ",")
		pcall(writefile, "Crozix/prot_state.txt", table.concat(out, "\n") .. "\n")
	end

	local function stop(key, label, src)
		STOPPED[key] = STOPPED[key] + 1
		if src and SRC[src] then
			SRC[src] = SRC[src] + 1
		end
		local msg
		if key == "robux" then
			msg = "Disable Robux stopped a purchase"
			say("Disable Robux stopped " .. label)
		elseif key == "scam" then
			msg = "Anti Scam stopped a purchase"
			say("Anti Scam stopped " .. label)
		else
			msg = "Teleport stopped: another Place ID"
			say("Verify Teleports stopped " .. label)
		end
		-- The refusal has already happened by the time we get here. Nothing below may be allowed to
		-- abort it, and the player still has to be told: every attempt shows the message again.
		local okToast = pcall(notify, msg, T.Green)
		local okAlert = false
		if guardAlert then
			local ok, res = pcall(guardAlert, msg)
			okAlert = ok and res == true
		end
		glog(string.format("stop %s via %s | toast=%s alert=%s rootVisible=%s",
			key, tostring(label), tostring(okToast), tostring(okAlert), tostring(Root and Root.Visible)))
		writeLedger()
	end

	-- Every namecall in the game passes through here while a guard is on. Anything not guarded is
	-- dispatched manually: the method is looked up on the instance and called directly, which never
	-- re-enters __namecall and never touches the original metamethod (calling that is what faults).
	local function handler(self, ...)
		local m = GNM()
		if measuring and m == "GetPlayerByUserId" then
			probeHit = true
			return nil
		end
		local kind = KIND[m]
		if kind == "purchase" then
			if GUARD.robux then
				stop("robux", m, "namecall")
				return nil
			end
			if GUARD.scam then
				stop("scam", m, "namecall")
				return nil
			end
			-- No purchase guard is on, but this call still cannot be re-issued from a wrapped
			-- closure: measured on the tablet, dispatching PromptGamePassPurchase this way never
			-- returns and the sheet never opens. Dropping it keeps the caller alive and is recorded.
			marketDropped = marketDropped + 1
			if marketDropped == 1 or marketDropped % 10 == 0 then
				glog("purchase with no guard: dropped " .. tostring(m))
			end
			return nil
		elseif kind == "tele" and GUARD.tele then
			local place = ...
			if type(place) == "number" and place ~= game.PlaceId then
				stop("tele", m .. " to place " .. tostring(place), "namecall")
				return nil
			end
		end
		local okf, f = pcall(function()
			return self[m]
		end)
		if okf and type(f) == "function" then
			return f(self, ...)
		end
		return nil
	end

	local function uninstall()
		if not installed then
			return
		end
		pcall(function()
			local mt = GRM(game)
			SRO(mt, false)
			rawset(mt, "__namecall", oldNamecall)
			SRO(mt, true)
		end)
		installed = false
		CAPS.route = "none"
	end

	local countMethods
	local function install()
		if installed then
			return CAPS.namecall == "intercepted"
		end
		-- Services can finish registering after the window is up; recount now, not only at boot.
		pcall(countMethods)
		if type(GRM) ~= "function" or type(SRO) ~= "function" or type(GNM) ~= "function" then
			CAPS.namecall = "hook-refused"
			return false
		end
		local okmt, mt = pcall(GRM, game)
		if not okmt or type(mt) ~= "table" then
			CAPS.namecall = "hook-refused"
			return false
		end
		local old = rawget(mt, "__namecall")
		if type(old) ~= "function" then
			CAPS.namecall = "hook-refused"
			return false
		end
		local h = handler
		if type(NCC) == "function" then
			local okc, wrapped = pcall(NCC, handler)
			if okc and type(wrapped) == "function" then
				h = wrapped
			end
		end
		local okw = pcall(function()
			SRO(mt, false)
			rawset(mt, "__namecall", h)
			SRO(mt, true)
		end)
		if not okw then
			CAPS.namecall = "hook-refused"
			return false
		end
		installed, oldNamecall = true, old
		CAPS.route = "namecall"
		-- Prove interception on a harmless read before any switch is allowed to stay on.
		probeHit = false
		measuring = true
		pcall(function()
			local pl = svc("Players")
			if pl then
				pl:GetPlayerByUserId(0)
			end
		end)
		measuring = false
		CAPS.namecall = probeHit and "intercepted" or "missed"
		if not probeHit then
			uninstall()
			return false
		end
		return true
	end

	-- How many of the calls each guard promises to stop this build actually exposes. Read-only.
	-- Each read is its own pcall: this engine RAISES at index time for a member it does not have
	-- (PromptCurrencyPurchase is not a real MarketplaceService member), so one missing name must not
	-- abort the count of the rest.
	local function hasMethod(obj, name)
		local ok, v = pcall(function()
			return obj[name]
		end)
		return ok and type(v) == "function"
	end
	countMethods = function()
		CAPS.market, CAPS.currency, CAPS.tele = 0, 0, 0
		local mps = svc("MarketplaceService")
		if mps then
			for i = 1, #MARKET do
				if hasMethod(mps, MARKET[i]) then
					CAPS.market = CAPS.market + 1
				end
			end
			for i = 1, #CURRENCY do
				if hasMethod(mps, CURRENCY[i]) then
					CAPS.currency = CAPS.currency + 1
				end
			end
		end
		local ts = svc("TeleportService")
		if ts then
			for i = 1, #TELE do
				if hasMethod(ts, TELE[i]) then
					CAPS.tele = CAPS.tele + 1
				end
			end
		end
	end
	pcall(countMethods)

	local function anyGuard()
		return GUARD.scam or GUARD.robux or GUARD.tele
	end

	-- A purchase prompt is not always requested through __namecall. Measured on the tablet
	-- (Crozix/diag_sources.txt): the hook saw 30,824 foreign namecalls and every method name, yet
	-- the billboard's prompt still appeared with zero stops. The dialog itself is ordinary CoreGui
	-- Lua, though: on this build it is an OverlayPortal under CoreGui.FoundationOverlay
	-- (Crozix/find_prompt.txt). Watch that tree and drop a portal the moment it proves it is a
	-- purchase sheet, so the dialog never reaches the player.
	local MARKERS = { BuyButton = true, ItemName = true, ItemCost = true, RobuxAmount = true }
	local promptConns = {}
	local hiddenPortals = setmetatable({}, { __mode = "k" })
	local watchedPortals = setmetatable({}, { __mode = "k" })
	local promptMounted = false

	local function after(t, fn)
		if type(task) == "table" and type(task.delay) == "function" then
			pcall(task.delay, t, fn)
		elseif type(task) == "table" and type(task.spawn) == "function" then
			pcall(task.spawn, function()
				task.wait(t)
				fn()
			end)
		elseif type(wait) == "function" then
			pcall(function()
				wait(t)
				fn()
			end)
		end
	end

	-- The panel's own toast lives under Root, and Root is hidden whenever the player is just playing.
	-- A block that only appears there is invisible at the exact moment it matters, so the same words
	-- are also shown on a sibling chip under the window's ScreenGui, where Root's visibility does not
	-- reach. It wears the window's surface and one accent dot; it never covers a control and fades by
	-- itself. Only used while the panel is closed -- the normal toast covers the open case.
	local alert
	local function guardAlertNow(text)
		if Root and Root.Visible then
			glog("alert: panel open, toast covers this one")
			return false
		end
		if not alert then
			local ok, err = pcall(function()
				local host = new("Frame", {
					Name = "CrozixGuardAlert",
					AnchorPoint = Vector2.new(0.5, 0),
					Position = UDim2.new(0.5, 0, 0, 74),
					Size = UDim2.fromOffset(560, 60),
					BackgroundTransparency = 1,
					Visible = false,
					ZIndex = 60,
					Parent = Gui,
				})
				local bg = new("Frame", {
					Name = "CrozixGuardAlertCard",
					BackgroundColor3 = T.PanelTop,
					BackgroundTransparency = 0.06,
					Size = UDim2.fromScale(1, 1),
					ZIndex = 60,
					Parent = host,
				})
				corner(bg, 16)
				local dot = new("Frame", {
					BackgroundColor3 = T.Green,
					Position = UDim2.fromOffset(22, 26),
					Size = UDim2.fromOffset(9, 9),
					ZIndex = 61,
					Parent = bg,
				})
				corner(dot, 9)
				local label = new("TextLabel", {
					BackgroundTransparency = 1,
					Position = UDim2.fromOffset(44, 0),
					Size = UDim2.new(1, -64, 1, 0),
					Text = "",
					Font = Enum.Font.GothamBold,
					TextSize = 21,
					TextColor3 = T.Text,
					TextXAlignment = Enum.TextXAlignment.Left,
					ZIndex = 61,
					Parent = bg,
				})
				alert = { host = host, label = label, token = 0 }
			end)
			if not ok then
				glog("alert build failed: " .. tostring(err))
				return false
			end
		end
		alert.token = alert.token + 1
		local token = alert.token
		alert.label.Text = text
		alert.host.Visible = true
		alertsShown = alertsShown + 1
		glog("alert shown #" .. alertsShown)
		after(4, function()
			if alert and alert.token == token then
				alert.host.Visible = false
			end
		end)
		return true
	end
	guardAlert = guardAlertNow

	local function purchasePortal(portal)
		local ok, desc = pcall(function()
			return portal:GetDescendants()
		end)
		if not ok or type(desc) ~= "table" then
			return false
		end
		for i = 1, #desc do
			local okn, name = pcall(function()
				return desc[i].Name
			end)
			if okn and MARKERS[name] then
				return true
			end
		end
		return false
	end

	-- Hiding, never destroying. Destroy() on the sheet leaves Foundation's overlay bookkeeping holding
	-- a dead object; the next purchase in the same session then gets no sheet at all -- exactly the
	-- "first one showed a message, the second showed nothing" the owner reported.
	local function hidePortal(portal)
		local ok = pcall(function()
			portal.Visible = false
		end)
		if ok then
			return true
		end
		local okc, kids = pcall(function()
			return portal:GetChildren()
		end)
		if not okc or type(kids) ~= "table" then
			return false
		end
		local any = false
		for i = 1, #kids do
			pcall(function()
				if kids[i]:IsA("GuiObject") then
					kids[i].Visible = false
					any = true
				end
			end)
		end
		return any
	end

	local function clock()
		local ok, t = pcall(function()
			return os.clock()
		end)
		if ok and type(t) == "number" then
			return t
		end
		return 0
	end

	local function spawnTask(fn)
		if type(task) == "table" and type(task.spawn) == "function" then
			if pcall(task.spawn, fn) then
				return
			end
		end
		local sp = api("spawn")
		if type(sp) == "function" then
			if pcall(sp, fn) then
				return
			end
		end
		pcall(fn)
	end

	local function pause(t)
		if type(task) == "table" and type(task.wait) == "function" then
			pcall(task.wait, t)
		elseif type(wait) == "function" then
			pcall(wait, t)
		end
	end

	-- Foundation raises the sheet again when the game re-prompts, so a hidden portal is not gone.
	-- Poll it for the rest of the attempt and re-hide + re-alert every time it returns. That is what
	-- makes the block land on the second, third and tenth tap, not only the first.
	local function watchHidden(portal)
		if watchedPortals[portal] then
			return
		end
		watchedPortals[portal] = true
		spawnTask(function()
			local lastAlert = clock()
			for _ = 1, 300 do
				pause(0.4)
				if not (GUARD.robux or GUARD.scam) then
					break
				end
				local okp, parent = pcall(function()
					return portal.Parent
				end)
				if not okp or parent == nil then
					break
				end
				local okv, vis = pcall(function()
					return portal.Visible
				end)
				if not (okv and vis == false) then
					hidePortal(portal)
					local t = clock()
					if (t - lastAlert) >= 1.5 then
						lastAlert = t
						stop(GUARD.robux and "robux" or "scam", "purchase prompt", "prompt")
					end
				end
			end
			watchedPortals[portal] = nil
		end)
	end

	local function dropPortal(portal)
		if hiddenPortals[portal] then
			watchHidden(portal)
			return
		end
		if not purchasePortal(portal) then
			return
		end
		hiddenPortals[portal] = true
		promptSeen = promptSeen + 1
		if not (GUARD.robux or GUARD.scam) then
			return
		end
		hidePortal(portal)
		promptKilled = promptKilled + 1
		stop(GUARD.robux and "robux" or "scam", "purchase prompt", "prompt")
		watchHidden(portal)
	end

	local function watchPortal(portal)
		local ok = pcall(function()
			local c = portal.DescendantAdded:Connect(function(d)
				local okn, name = pcall(function()
					return d.Name
				end)
				if okn and MARKERS[name] then
					dropPortal(portal)
				end
			end)
			promptConns[#promptConns + 1] = c
		end)
		if not ok then
			return
		end
		-- The sheet fills a frame or two after the portal is parented; re-check once it is complete.
		after(0.4, function()
			dropPortal(portal)
		end)
		after(1.2, function()
			dropPortal(portal)
		end)
	end

	local function watchOverlay(root)
		if not root then
			return
		end
		pcall(function()
			local c = root.DescendantAdded:Connect(function(d)
				local okn, name = pcall(function()
					return d.Name
				end)
				if not okn then
					return
				end
				if name == "OverlayPortal" then
					watchPortal(d)
				elseif MARKERS[name] then
					-- A marker can arrive before the portal is noticed: climb to the portal root.
					local p = d
					for _ = 1, 8 do
						local okp, parent = pcall(function()
							return p.Parent
						end)
						if not okp or not parent then
							return
						end
						local okn2, pname = pcall(function()
							return parent.Name
						end)
						if okn2 and pname == "OverlayPortal" then
							dropPortal(parent)
							return
						end
						p = parent
					end
				end
			end)
			promptConns[#promptConns + 1] = c
		end)
		-- A sheet can already be open when the player flips the switch on.
		local ok, desc = pcall(function()
			return root:GetDescendants()
		end)
		if ok and type(desc) == "table" then
			for i = 1, #desc do
				local okn, name = pcall(function()
					return desc[i].Name
				end)
				if okn and name == "OverlayPortal" then
					dropPortal(desc[i])
				end
			end
		end
	end

	-- A game's own LocalScript reaches the marketplace outside the Lua namecall path: measured on the
	-- tablet (Crozix/call.txt), calling the gamepass button's own handler runs its pcall'd
	-- PromptGamePassPurchase and the hook below never sees it. What IS visible from Lua is the button
	-- that owns that script -- so a tampered button is caught by its own click, and the refusal is
	-- said out loud on every tap instead of only when a sheet happens to appear.
	local BUY_METHODS = { "PromptGamePassPurchase", "PromptProductPurchase", "PromptPurchase",
		"PromptBulkPurchase", "PromptBundlePurchase", "PromptPremiumPurchase", "PromptRobuxPurchase" }
	local buyButtons = setmetatable({}, { __mode = "k" })
	local buyConns = {}
	local taggedList = {}

	local function promptsPurchases(script)
		if type(GBC) ~= "function" then
			return false
		end
		local ok, bc = pcall(GBC, script)
		if not ok or type(bc) ~= "string" then
			return false
		end
		for i = 1, #BUY_METHODS do
			if string.find(bc, BUY_METHODS[i], 1, true) then
				return true
			end
		end
		return false
	end

	local function tagButton(btn)
		if not btn or buyButtons[btn] then
			return
		end
		local okt, seen = pcall(function()
			return SHARED and SHARED.tags[btn]
		end)
		if okt and seen then
			-- Another copy of this window already guards this button; a second listener would stop the
			-- same tap twice and report one stop it never showed.
			buyButtons[btn] = true
			tagDup = tagDup + 1
			return
		end
		local ok = pcall(function()
			local c = btn.MouseButton1Click:Connect(function()
				if GUARD.robux then
					stop("robux", "purchase button " .. tostring(btn.Name), "button")
				elseif GUARD.scam then
					stop("scam", "purchase button " .. tostring(btn.Name), "button")
				end
			end)
			buyConns[#buyConns + 1] = c
		end)
		if ok then
			buyButtons[btn] = true
			taggedList[#taggedList + 1] = btn
			pcall(function()
				if SHARED then
					SHARED.tags[btn] = true
				end
			end)
		end
	end

	local function scanBuyScript(scr)
		if not scr or not promptsPurchases(scr) then
			return
		end
		local okp, p = pcall(function()
			return scr.Parent
		end)
		if okp and p then
			tagButton(p)
		end
	end

	local function mountBuyButtons()
		local pl = svc("Players")
		pl = pl and pl.LocalPlayer
		if not pl then
			return
		end
		local okp, pg = pcall(function()
			return pl:FindFirstChild("PlayerGui")
		end)
		if not okp or pg == nil then
			return
		end
		pcall(function()
			local desc = pg:GetDescendants()
			for i = 1, #desc do
				local okc, cls = pcall(function()
					return desc[i].ClassName
				end)
				if okc and (cls == "LocalScript" or cls == "Script") then
					scanBuyScript(desc[i])
				end
			end
		end)
		pcall(function()
			local c = pg.DescendantAdded:Connect(function(d)
				local okc, cls = pcall(function()
					return d.ClassName
				end)
				if okc and (cls == "LocalScript" or cls == "Script") then
					after(0.3, function()
						scanBuyScript(d)
					end)
				end
			end)
			buyConns[#buyConns + 1] = c
		end)
	end

	local function mountPrompts()
		if promptMounted then
			return
		end
		local ok, cg = pcall(function()
			return game:GetService("CoreGui")
		end)
		if not ok or cg == nil then
			return
		end
		promptMounted = true
		watchOverlay(cg:FindFirstChild("FoundationOverlay"))
		pcall(function()
			local c = cg.ChildAdded:Connect(function(child)
				local okn, name = pcall(function()
					return child.Name
				end)
				if okn and name == "FoundationOverlay" then
					watchOverlay(child)
				end
			end)
			promptConns[#promptConns + 1] = c
		end)
		mountBuyButtons()
	end

	local function unmountPrompts()
		for i = 1, #promptConns do
			pcall(function()
				promptConns[i]:Disconnect()
			end)
		end
		promptConns = {}
		for i = 1, #buyConns do
			pcall(function()
				buyConns[i]:Disconnect()
			end)
		end
		buyConns = {}
		for i = 1, #taggedList do
			local b = taggedList[i]
			pcall(function()
				if SHARED then
					SHARED.tags[b] = nil
				end
			end)
		end
		taggedList = {}
		buyButtons = setmetatable({}, { __mode = "k" })
		promptMounted = false
	end

	-- A guard is only switched on when the handler is installed AND a namecall really reached it.
	local function guardReason(key)
		if not installed or CAPS.namecall ~= "intercepted" then
			if CAPS.namecall == "missed" then
				return "this engine build does not route the call through a hook"
			end
			return "this engine build exposes no namecall hook"
		end
		local n
		if key == "tele" then
			n = CAPS.tele
		elseif key == "robux" then
			n = CAPS.market + CAPS.currency
		else
			n = CAPS.market
		end
		if n == 0 then
			return "this engine build does not expose the call it must stop"
		end
		return nil
	end
	local function capability(key)
		return guardReason(key) == nil
	end

	-- Anti AFK stays local: Idled fires as the client is about to time the player out, and a virtual
	-- click is the input that resets that timer. It needs no hook at all.
	local afkConn
	local function setAfkLocal(on)
		local ok, res = pcall(function()
			local lp = game:GetService("Players").LocalPlayer
			if on then
				if not afkConn then
					afkConn = lp.Idled:Connect(function()
						pcall(function()
							local vu = game:GetService("VirtualUser")
							vu:CaptureController()
							vu:ClickButton2(Vector2.new(0, 0))
						end)
					end)
				end
				return true
			end
			if afkConn then
				afkConn:Disconnect()
				afkConn = nil
			end
			return true
		end)
		return ok and res == true
	end
	local function afkState()
		local s = Settings.AntiAfk
		if type(s) == "boolean" then
			return s
		end
		return true
	end

	-- The saved choices are re-applied on join, so a rejoin keeps the protection the player left on.
	local wantOn = false
	for _, key in ipairs({ "scam", "robux", "tele" }) do
		if Settings[SETTING[key]] == true then
			wantOn = true
		end
	end
	if wantOn then
		pcall(install)
		for _, key in ipairs({ "scam", "robux", "tele" }) do
			if Settings[SETTING[key]] == true and capability(key) then
				GUARD[key] = true
			end
		end
		if GUARD.scam or GUARD.robux then
			mountPrompts()
		end
		if not anyGuard() then
			uninstall()
		end
	end
	if afkState() then
		pcall(setAfkLocal, true)
	end
	pcall(writeLedger)

	local rowSwitch = {}
	local function afkChange(v)
		Settings.AntiAfk = v
		if not setAfkLocal(v) then
			Settings.AntiAfk = not v
			if rowSwitch.afk then
				rowSwitch.afk.set(not v, true)
			end
			notify("Anti AFK: the local player is not available yet", T.Red)
			return
		end
		settingsChanged()
		notify("Anti AFK" .. (v and " enabled" or " disabled"), v and T.Green or T.Muted)
		writeLedger()
	end
	local function guardChange(key, label)
		return function(v)
			if v then
				if not installed then
					pcall(install)
				end
				local why = guardReason(key)
				if why then
					if not anyGuard() then
						uninstall()
					end
					if rowSwitch[key] then
						rowSwitch[key].set(false, true)
					end
					notify(label .. ": " .. why, T.Red)
					say(label .. " refused: " .. why)
					writeLedger()
					return
				end
			end
			GUARD[key] = v
			Settings[SETTING[key]] = v
			if GUARD.scam or GUARD.robux then
				mountPrompts()
			else
				unmountPrompts()
			end
			if not v and not anyGuard() then
				uninstall()
			end
			settingsChanged()
			notify(label .. (v and " enabled" or " disabled"), v and T.Green or T.Muted)
			writeLedger()
		end
	end

