local function setVisible(v)
	shown = v
	if v then
		Fab.Visible = false
		-- Position first, then show: the window is never painted for one frame somewhere it is not about
		-- to be. The scale is written once and never tweened -- a UIScale tween is what made every glyph
		-- on the panel grow while the window opened.
		Scale.Scale = fit
		if mainShown then
			Main.Position = UDim2.fromOffset(34, -6)
		end
		Sidebar.Position = UDim2.fromOffset(700, 0)
		Root.Visible = true
		if mainShown then
			tween(Main, 0.26, { Position = UDim2.fromOffset(-6, -6) }, Enum.EasingStyle.Quart,
				Enum.EasingDirection.Out)
		end
		tween(Sidebar, 0.3, { Position = UDim2.fromOffset(644, 0) }, Enum.EasingStyle.Quart,
			Enum.EasingDirection.Out)
	else
		-- Closing is the same two translations in reverse. The square takes over only after they land,
		-- and the panel is hidden rather than shrunk, so the last frame before it goes is the window
		-- sliding out of frame -- no size change anywhere on it.
		tween(Main, 0.18, { Position = UDim2.fromOffset(34, -6) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		tween(Sidebar, 0.18, { Position = UDim2.fromOffset(700, 0) }, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		task.delay(0.2, function()
			if not shown then
				Root.Visible = false
				Fab.Visible = true
				Fab.Size = UDim2.fromOffset(46, 46)
				tw(Fab, 0.24, { Size = UDim2.fromOffset(58, 58) }, Enum.EasingStyle.Back,
					Enum.EasingDirection.Out)
			end
		end)
	end
end

HideBtn.Activated:Connect(function()
