end)
-- Dragging the square: the position follows the finger 1:1 while held, because lag is what makes a
-- floating button feel stiff, and it is clamped inside the camera viewport so it can never end up half
-- off-screen. On release it stays exactly where the finger let go -- no snap to an edge. A drag is not
-- a tap -- fabMoved is what tells them apart, and it resets on the next press.
do
	local fabDrag, fabMoved, fabGrabX, fabGrabY, fabStartX, fabStartY = false, false, 0, 0, 0, 0
	-- Gui.AbsoluteSize reads 0x0 on this engine, so anything anchored by scale inside the ScreenGui
	-- collapses onto the top edge -- that is what pushed the square to cy=-25, off the screen. The
	-- camera's viewport is the number that is actually right, so the square is placed and clamped in
	-- real pixels against it and never uses a scale anchor at all.
	local function fabVp()
		local x, y = 0, 0
		pcall(function()
			local cam = game:GetService("Workspace").CurrentCamera
			x, y = cam.ViewportSize.X, cam.ViewportSize.Y
		end)
		pcall(function()
			local s = Gui.AbsoluteSize
			x, y = math.max(x, s.X), math.max(y, s.Y)
		end)
		if x < 50 then
			x = 1280
		end
		if y < 50 then
			y = 720
		end
		return x, y
	end
	local function clampFab(x, y)
		local half = Fab.Size.X.Offset / 2
		local vx, vy = fabVp()
		return math.clamp(x, half + 6, vx - half - 6), math.clamp(y, half + 6, vy - half - 6)
	end
	do
		local vx, vy = fabVp()
		Fab.Position = UDim2.fromOffset(math.floor(vx * 0.035) + 10, math.floor(vy / 2))
	end
	Fab.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1
			or input.UserInputType == Enum.UserInputType.Touch then
			fabDrag, fabMoved = true, false
			fabGrabX, fabGrabY = input.Position.X, input.Position.Y
			fabStartX, fabStartY = Fab.Position.X.Offset, Fab.Position.Y.Offset
		end
	end)
	connect(UserInputService.InputChanged, function(input)
		if not fabDrag then
			return
		end
		if input.UserInputType ~= Enum.UserInputType.MouseMovement
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		local nx, ny = clampFab(fabStartX + (input.Position.X - fabGrabX),
			fabStartY + (input.Position.Y - fabGrabY))
		if math.abs(nx - fabStartX) > 4 or math.abs(ny - fabStartY) > 4 then
			fabMoved = true
		end
		Fab.Position = UDim2.new(0, nx, 0, ny)
	end)
	connect(UserInputService.InputEnded, function(input)
		if not fabDrag then
			return
		end
		if input.UserInputType ~= Enum.UserInputType.MouseButton1
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		fabDrag = false
		if not fabMoved then
			return
		end
		-- The square stays where it was dropped. It used to ease to the nearest edge, which pulled the
		-- logo away from the spot the player chose.
		remapSoon()
	end)
	Fab.Activated:Connect(function()
		if fabMoved then
			return
		end
		if revealed then
			setVisible(true)
		end
	end)
end
connect(UserInputService.InputBegan, function(input, processed)
	if processed or not revealed then
		return
	end
	if input.KeyCode == Config.ToggleKey then
		if not locked then
			setVisible(not shown)
		end
		return
	end
	-- Ctrl+Enter runs the buffer and Ctrl+S saves it, so the toolbar is a shortcut and not the only
	-- door. They sit on the raw key event, which is what lets them fire while the editor has focus.
	local down = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl)
		or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
	if down and input.KeyCode == Enum.KeyCode.Return then
		ExecBtn.Activated:Fire()
	elseif down and input.KeyCode == Enum.KeyCode.S then
		SaveBtn.Activated:Fire()
	end
end)

local dragging, dragStart, startPos = false, nil, nil
CROZIX.register("TopBar", TopBar)
TopBar.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		dragging = true
		dragStart = input.Position
		startPos = Root.Position
		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then
				dragging = false
			CROZIX.saveSettings(Settings, Root)
			end
		end)
	end
end)
connect(UserInputService.InputChanged, function(input)
	if
		dragging
		and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch)
	then
		local d = (input.Position - dragStart) / Scale.Scale
		Root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
	end
end)

-- There is no "close the executor" button any more. This one locks the panel away, and the floating
-- square is what brings it back, so a mis-tap never throws the session (and the open script) away.
CROZIX.register("CrozixPower", PowerBtn)
PowerBtn.Activated:Connect(function()
	-- Written before any branch: "nothing happened" is only useful if it says whether the handler ran
	-- at all and what the gate flags were when it did.
	pcall(writefile, "Crozix/power_hit.txt", string.format(
		"entered locked=%s revealed=%s shown=%s\n", tostring(locked), tostring(revealed), tostring(shown)))
	if locked then
		return
	end
	-- If the animated hide fails for any reason the panel still has to go away and hand over to the
	-- square, so the state is set directly when the tween path raises.
	local okSet, errSet = pcall(setVisible, false)
	if not okSet then
		Root.Visible = false
		Fab.Visible = true
		shown = false
	end
	notify("locked - tap the red button to reopen", T.Yellow)
	-- Re-read the geometry now that the square is the only thing on screen. The file is the proof the
	-- lock worked: CrozixFab flips to visible=true and the window's widgets flip to visible=false.
	CROZIX.hotspots(Gui, { "CrozixFab", "CrozixPower" })
	-- The square only becomes hit-testable now that it is on screen, so re-map it off the click
	-- thread: the sweep is a few thousand hit-tests and must not hitch the animation.
	task.spawn(function()
		task.wait(0.7)
		CROZIX.tapmap({ "CrozixFab" })
	end)
	pcall(writefile, "Crozix/power_hit.txt",
		"setVisible ok=" .. tostring(okSet) .. " err=" .. tostring(errSet)
			.. " fab=" .. tostring(Fab.Visible) .. " root=" .. tostring(Root.Visible) .. "\n")
end)

-- live stats
local frames, last = 0, os.clock()
connect(RunService.RenderStepped, function()
	-- The game keeps rendering while the panel is locked away, so this loop would keep paying a ping
	-- read and three label writes every half second for a window nobody can see. Root starts hidden
	-- and is hidden again on lock, so it is exactly the "is the panel on screen" flag. Resetting the
	-- clock here means the first reading after a reopen covers only time the panel was actually up.
	if not Root.Visible then
		frames, last = 0, os.clock()
		return
	end
	frames += 1
	local now = os.clock()
	if now - last >= 0.5 then
		fpsLabel.Text = tostring(math.floor(frames / (now - last) + 0.5))
		frames, last = 0, now
		-- The brief asks for a slow breathing glow that stops in Lite. It rides the half-second tick the
		-- stats already take, which is inside the `if not Root.Visible then return end` guard above, so a
		-- closed panel writes nothing and an open one writes one number per glow. No extra loop, no extra
		-- tween, and the edge holds still the moment Lite is on.
		if CROZIX.effectsOn() then
			local beat = 0.62 + 0.22 * math.sin(now * 1.4)
			for _, glow in ipairs(CROZIX.glowLayers) do
				if glow.Parent then
					glow.Transparency = beat
				end
			end
		end
		local ok, ping = pcall(function()
			return Stats.Network.ServerStatsItem["Data Ping"]:GetValue()
		end)
		pingLabel.Text = ok and (math.floor(ping) .. "ms") or "--"
		playersLabel.Text = tostring(#Players:GetPlayers())
	end
end)

selectTab(active)

------------------------------------------------------------------
-- REVEAL: sections slide in from the side, then content opens
------------------------------------------------------------------


------------------------------------------------------------------
-- OUTPUT: what the executor did, in the player's own words
------------------------------------------------------------------
do
	local pane = Panes.output
	if pane then
		-- v8: one rail section, two real consoles. Crozix Console keeps the panel's own log; Roblox
		-- Console is the game's actual output, read from LogService. Each carries its own Copy and
		-- Clear underneath, so neither log can be mistaken for the other.
		local function consoleCard(x, title)
			local c = card(pane, {
				Position = UDim2.fromOffset(x, 14),
				Size = UDim2.fromOffset(295, 290),
			})
			new("TextLabel", {
				Text = title,
				Font = Enum.Font.GothamBold,
				TextSize = 15,
				TextXAlignment = Enum.TextXAlignment.Left,
				Position = UDim2.fromOffset(14, 10),
				Size = UDim2.new(1, -28, 0, 20),
				Parent = c,
			})
			new("Frame", {
				BackgroundColor3 = T.StrokeSoft,
				BackgroundTransparency = 0.5,
				Position = UDim2.fromOffset(14, 34),
				Size = UDim2.new(1, -28, 0, 1),
				Parent = c,
			})
			return c
		end
		local crozixCard = consoleCard(14, "Crozix Console")
		local robloxCard = consoleCard(323, "Roblox Console")

		-- One builder, two wells: same darkest surface, same thin scrollbar, same row language.
		-- The raw text is kept beside the numbered rows so Copy lifts the words, not the decoration.
		local function buildConsole(parentCard, listName, emptyTitle, emptyCaption, emptyIcon, cap)
			local list = new("ScrollingFrame", {
				Name = listName,
				Position = UDim2.fromOffset(12, 44),
				Size = UDim2.new(1, -24, 1, -102),
				BackgroundColor3 = T.Editor,
				BackgroundTransparency = 0,
				CanvasSize = UDim2.new(),
				AutomaticCanvasSize = Enum.AutomaticSize.Y,
				ScrollingDirection = Enum.ScrollingDirection.Y,
				ScrollBarThickness = 3,
				ScrollBarImageColor3 = T.StrokeSoft,
				ScrollBarImageTransparency = 0.35,
				Parent = parentCard,
			})
			corner(list, CROZIX.D.R.XS)
			litStroke(list, T.StrokeSoft, 0.55)
			new("UIListLayout", {
				Padding = UDim.new(0, 3),
				SortOrder = Enum.SortOrder.LayoutOrder,
				Parent = list,
			})
			local empty
			local function buildEmpty()
				empty = new("Frame", {
					Name = listName .. "Empty",
					BackgroundTransparency = 1,
					Size = UDim2.fromScale(1, 1),
					Parent = list,
				})
				Icon.new(emptyIcon, empty, 40, T.StrokeSoft, {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.new(0.5, 0, 0.5, -44),
					BackgroundTransparency = 1,
				})
				new("TextLabel", {
					Text = emptyTitle,
					Font = Enum.Font.GothamBold,
					TextColor3 = T.TextSecondary,
					TextSize = CROZIX.D.TYPE.Section,
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.new(0.5, 0, 0.5, 4),
					Size = UDim2.fromOffset(250, 22),
					Parent = empty,
				})
				new("TextLabel", {
					Text = emptyCaption,
					TextColor3 = T.Muted,
					TextSize = CROZIX.D.TYPE.Caption,
					TextWrapped = true,
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.new(0.5, 0, 0.5, 30),
					Size = UDim2.fromOffset(250, 30),
					Parent = empty,
				})
			end
			buildEmpty()
			local n = 0
			local raw = {}
			local function addLine(text, color)
				n = n + 1
				if empty then
					empty:Destroy()
					empty = nil
				end
				local s = tostring(text)
				raw[#raw + 1] = s
				-- Callers pass a colour when they know one; otherwise the word in the line decides.
				local probe = s:lower()
				local inferred = T.Muted
				if probe:find("error") or probe:find("failed") or probe:find("refused") then
					inferred = T.Red
				elseif probe:find("warn") or probe:find("missing") or probe:find("not connected") then
					inferred = T.Yellow
				elseif probe:find("ran ") or probe:find("saved") or probe:find("imported") then
					inferred = T.Green
				end
				local row = new("TextLabel", {
					Text = string.format("%02d  %s", n % 100, s),
					Font = Enum.Font.RobotoMono,
					TextSize = CROZIX.D.TYPE.Code,
					TextColor3 = color or inferred,
					TextXAlignment = Enum.TextXAlignment.Left,
					TextTruncate = Enum.TextTruncate.AtEnd,
					Size = UDim2.new(1, 0, 0, 15),
					LayoutOrder = n,
					Parent = list,
				})
				if n > cap then
					for _, c in ipairs(list:GetChildren()) do
						if c:IsA("TextLabel") and c.LayoutOrder <= n - cap then
							c:Destroy()
						end
					end
					while #raw > cap do
						table.remove(raw, 1)
					end
				end
				pcall(function()
					list.CanvasPosition = Vector2.new(0, list.AbsoluteCanvasSize.Y)
				end)
				return row
			end
			local function copyAll()
				local have = type(setclipboard) == "function"
				if have then
					pcall(setclipboard, table.concat(raw, "\n"))
				end
				addLine(have and ("copied " .. #raw .. " lines") or "no clipboard on this engine", have and T.Green or T.Yellow)
			end
			local function clearAll()
				for _, c in ipairs(list:GetChildren()) do
					if c:IsA("TextLabel") then
						c:Destroy()
					end
				end
				raw = {}
				n = 0
				buildEmpty()
			end
			return addLine, copyAll, clearAll
		end

		local crozixAdd, crozixCopy, crozixClear = buildConsole(crozixCard, "CrozixConsole",
			"No output yet", "Every message the panel sends you lands here.", "output", 120)
		local robloxAdd, robloxCopy, robloxClear = buildConsole(robloxCard, "RobloxConsole",
			"No Roblox output yet", "The game's own print, warn and error messages land here.", "code", 200)

		-- Mark plus word, always. The old version only drew a mark once copy.png / trash.png existed and
		-- then deleted the word, so today the two console buttons were bare text while every other
		-- action in the panel carried a glyph, and the day the files landed the control would have
		-- become an unnamed 13-unit picture. Icon.new already falls back to the drawn mark, so the
		-- button is complete now and switches to the owner's PNG with no code change. The pair is
		-- centred as one group, measured by the engine rather than guessed, so Copy and Clear line up
		-- with each other instead of each glyph floating at the plate's left edge.
		local function withMark(btn, key, text)
			local tw = #text * 11 * 0.6
			pcall(function()
				local ts = game:GetService("TextService")
				local one = ts:GetTextSize(text, 11, Enum.Font.GothamMedium, Vector2.new(131, 44))
				if one.X > 0 then
					tw = one.X
				end
			end)
			local inner = 13 + 6 + math.ceil(tw)
			local x = math.floor((131 - inner) / 2)
			btn.Text = ""
			Icon.new(key, btn, 13, T.Text, {
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, x, 0.5, 0),
			})
			new("TextLabel", {
				Text = text,
				Font = Enum.Font.GothamMedium,
				TextSize = 11,
				TextColor3 = T.Text,
				TextXAlignment = Enum.TextXAlignment.Left,
				BackgroundTransparency = 1,
				AnchorPoint = Vector2.new(0, 0.5),
				Position = UDim2.new(0, x + 19, 0.5, 0),
				Size = UDim2.new(0, math.ceil(tw) + 2, 0, 16),
				Parent = btn,
			})
		end
		local function consoleButtons(parentCard, copyFn, clearFn, copyName, clearName)
			local copyBtn = new("TextButton", {
				Name = copyName,
				Position = UDim2.fromOffset(12, 238),
				Size = UDim2.fromOffset(131, CROZIX.D.HIT),
				Text = "Copy",
				Font = Enum.Font.GothamMedium,
				TextSize = 11,
				Parent = parentCard,
			})
			corner(copyBtn, CROZIX.D.R.XS)
			styleButton(copyBtn, "ghost")
			local clearBtn = new("TextButton", {
				Name = clearName,
				Position = UDim2.fromOffset(152, 238),
				Size = UDim2.fromOffset(131, CROZIX.D.HIT),
				Text = "Clear",
				Font = Enum.Font.GothamMedium,
				TextSize = 11,
				Parent = parentCard,
			})
			corner(clearBtn, CROZIX.D.R.XS)
			styleButton(clearBtn, "ghost")
			withMark(copyBtn, "copy", "Copy")
			withMark(clearBtn, "trash", "Clear")
			-- Rest as a surface, take the brand colour only under the finger.
			for _, b in ipairs({ copyBtn, clearBtn }) do
				b.BackgroundColor3 = T.Dark
				b.BackgroundTransparency = 0.2
				b.MouseEnter:Connect(function()
					tw(b, 0.14, { BackgroundColor3 = T.AccentDeep })
				end)
				b.MouseLeave:Connect(function()
					tw(b, 0.2, { BackgroundColor3 = T.Dark })
				end)
			end
			copyBtn.Activated:Connect(copyFn)
			clearBtn.Activated:Connect(clearFn)
			CROZIX.register(copyName, copyBtn)
			CROZIX.register(clearName, clearBtn)
		end
		consoleButtons(crozixCard, crozixCopy, crozixClear, "CrozixOutCopy", "CrozixOutClear")
		consoleButtons(robloxCard, robloxCopy, robloxClear, "RobloxOutCopy", "RobloxOutClear")

		-- Every toast already says something to the player; the Crozix well keeps those statements
		-- reviewable after they fade. Script print/warn/error belongs to the game, so it goes to the
		-- Roblox well below, never into this one.
		CROZIX.log = crozixAdd

		-- The real Roblox console: LogService.MessageOut is the game's own output channel, and
		-- GetLogHistory brings back what was said before the panel opened. The message type is read
		-- by name, not by enum identity -- this engine's enum surface is not Roblox's.
		local function msgColor(mt)
			local s
			if type(mt) == "table" then
				s = tostring(mt.Name or "")
			else
				s = tostring(mt or "")
			end
			if s:find("Error") then
				return T.Red
			end
			if s:find("Warning") then
				return T.Yellow
			end
			if s:find("Info") then
				return T.TextSecondary
			end
			return nil
		end
		local okLog, logService = pcall(function()
			return game:GetService("LogService")
		end)
		if okLog and logService then
			pcall(function()
				local hist = logService:GetLogHistory()
				if type(hist) == "table" then
					for i = math.max(1, #hist - 99), #hist do
						local e = hist[i]
						if type(e) == "table" and e.message ~= nil then
							robloxAdd(tostring(e.message), msgColor(e.messageType))
						end
					end
				end
			end)
			pcall(function()
				connect(logService.MessageOut, function(msg, mtype)
					robloxAdd(tostring(msg), msgColor(mtype))
				end)
			end)
		else
			robloxAdd("LogService is not available on this engine", T.Yellow)
		end
		crozixAdd("panel ready", T.Green)
	end
end

------------------------------------------------------------------
-- EXTENSIONS: the store (header, toolbar, cards, add modal, banner)
------------------------------------------------------------------
-- Scan protection is the tool the owner named first: it reads the script that is open and reports
-- what it found. Every card's action is derived from its metadata (itemType, source, actionType),
-- never from its name, and the counters, filters and sort read that same table.
-- The whole store is one function so its ~45 locals live in their own register frame: the body
-- function already sits close to Lua's 200-local ceiling, and a do-block would spend them there.
local function extensionsUI()
	local pane = Panes.extensions
	if pane then
		----------------------------------------------------------------
		-- PALETTE + TYPE (the spec's numbers, one table)
		----------------------------------------------------------------
		-- The store reads the window's own theme instead of restating it. It used to carry a violet-black
		-- surface set plus a blue/purple category pair, so Extensions looked like a different product next
		-- to the editor and put two hues into an interface whose palette contract is one red on graphite.
		-- Red stays the brand and the state colour; a built-in extension wears the neutral `steel` mark
		-- instead of a second accent, and a user item wears the brightest neutral so "mine" still reads at
		-- a glance. Geometry, type and hit areas are untouched.
		local C = {
			red = T.Accent,
			red2 = T.AccentDeep,
			deep = T.AccentDeep,
			bg = T.PanelBottom,
			panel = T.PanelTop,
			card = T.Card,
			card2 = T.CardLift,
			line = T.StrokeSoft,
			text = T.Text,
			muted = T.TextSecondary,
			steel = T.TextSecondary,
			green = T.Green,
			amber = T.Yellow,
			onRedSoft = T.Text,
			tintRed = T.CardLift,
		}
		local FB = Enum.Font.GothamBold
		local FL = Enum.Font.GothamBlack
		local FM = Enum.Font.GothamMedium
		local FMONO = Enum.Font.RobotoMono
		local TRUNC = Enum.TextTruncate.AtEnd
		local NONE = Enum.TextTruncate.None
		local LEFT = Enum.TextXAlignment.Left
		local CENTER = Enum.TextXAlignment.Center
		local RIGHT = Enum.TextXAlignment.Right

		----------------------------------------------------------------
		-- PRIMITIVES
		----------------------------------------------------------------
		local function plate(parent, x, y, w, h, fill, radius, alpha, borderColor, borderAlpha)
			local f = new("Frame", {
				Position = UDim2.fromOffset(x, y),
				Size = UDim2.fromOffset(w, h),
				BackgroundColor3 = fill,
				BackgroundTransparency = alpha or 0,
				Parent = parent,
			})
			if radius and radius > 0 then
				corner(f, radius)
			end
			if borderColor then
				stroke(f, borderColor, 1, borderAlpha or 0.4)
			end
			return f
		end

		local function label(parent, text, x, y, w, h, size, color, font, align)
			return new("TextLabel", {
				Text = text,
				Font = font or FM,
				TextSize = size or CROZIX.D.TYPE.Caption,
				TextColor3 = color or C.text,
				TextXAlignment = align or LEFT,
				TextTruncate = TRUNC,
				BackgroundTransparency = 1,
				Position = UDim2.fromOffset(x, y),
				Size = UDim2.fromOffset(w, h),
				Parent = parent,
			})
		end

		local function wrap(l)
			l.TextWrapped = true
			l.TextTruncate = NONE
			return l
		end

		----------------------------------------------------------------
		-- ICONS: the registry's image first, the drawn glyph second
		----------------------------------------------------------------
		local function mk(kind, parent, size, color, bgc, pos)
			-- One asset path for every mark in the panel. The Extensions store used to be the one place a
			-- PNG could not reach: it had its own renderer, so twenty-odd of the panel's icons had no slot
			-- the owner could fill. A file dropped in Crozix/icons/ now replaces this glyph here exactly as
			-- it replaces a rail icon, and a missing file keeps the drawing unchanged.
			local shot = CROZIX.iconImage(kind, parent, size, color, { Position = pos or UDim2.new() })
			if shot then
				return shot
			end
			local k = size / 24
			-- named Icon_* like the rest of the panel: one glyph drawn from overlapping bars in one
			-- colour, so the preview's sibling-overlap rule reads it as a primitive, not as a layout row
			local root = new("Frame", {
				Name = "Icon_" .. tostring(kind),
				Size = UDim2.fromOffset(size, size),
				BackgroundTransparency = 1,
				Position = pos or UDim2.new(),
				Parent = parent,
			})
			local tinted = {}

			local function fill(x, y, w, h, r, col)
				local f = new("Frame", {
					Position = UDim2.fromOffset(x * k, y * k),
					Size = UDim2.fromOffset(math.max(w * k, 1), math.max(h * k, 1)),
					BackgroundColor3 = col or color,
					BackgroundTransparency = 0,
					Parent = root,
				})
				if r and r > 0 then
					corner(f, r * k)
				end
				if col == nil then
					tinted[#tinted + 1] = f
				end
				return f
			end

			local function dot(cx, cy, d, col)
				local f = new("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromOffset(cx * k, cy * k),
					Size = UDim2.fromOffset(d * k, d * k),
					BackgroundColor3 = col or color,
					BackgroundTransparency = 0,
					Parent = root,
				})
				new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = f })
				if col == nil then
					tinted[#tinted + 1] = f
				end
				return f
			end

			local function line(x1, y1, x2, y2, th, col)
				th = th or 2.2
				local dx, dy = x2 - x1, y2 - y1
				local len = math.sqrt(dx * dx + dy * dy) + th * 0.5
				local f = new("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromOffset((x1 + x2) / 2 * k, (y1 + y2) / 2 * k),
					Size = UDim2.fromOffset(len * k, th * k),
					Rotation = math.deg(math.atan2(dy, dx)),
					BackgroundColor3 = col or color,
					BackgroundTransparency = 0,
					Parent = root,
				})
				new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = f })
				if col == nil then
					tinted[#tinted + 1] = f
				end
				return f
			end

			local function ring(cx, cy, d, th, col)
				local f = new("Frame", {
					AnchorPoint = Vector2.new(0.5, 0.5),
					Position = UDim2.fromOffset(cx * k, cy * k),
					Size = UDim2.fromOffset(d * k, d * k),
					BackgroundTransparency = 1,
					Parent = root,
				})
				new("UICorner", { CornerRadius = UDim.new(0.5, 0), Parent = f })
				local s = stroke(f, col or color, th * k, 0)
				if col == nil then
					tinted[#tinted + 1] = s
				end
				return f
			end

			local function obox(x, y, w, h, r, th, col)
				local f = new("Frame", {
					Position = UDim2.fromOffset(x * k, y * k),
					Size = UDim2.fromOffset(w * k, h * k),
					BackgroundTransparency = 1,
					Parent = root,
				})
				corner(f, r * k)
				local s = stroke(f, col or color, th * k, 0)
				if col == nil then
					tinted[#tinted + 1] = s
				end
				return f
			end

			local function arc(cx, cy, r, a0, a1, th, col)
				local steps = math.max(6, math.floor(math.abs(a1 - a0) / 20))
				local lx, ly
				for i = 0, steps do
					local a = math.rad(a0 + (a1 - a0) * i / steps)
					local x, y = cx + r * math.cos(a), cy + r * math.sin(a)
					if lx then
						line(lx, ly, x, y, th, col)
					end
					lx, ly = x, y
				end
			end

			local function poly(pts, th, closed, col)
				for i = 1, #pts - 1 do
					line(pts[i][1], pts[i][2], pts[i + 1][1], pts[i + 1][2], th, col)
				end
				if closed then
					line(pts[#pts][1], pts[#pts][2], pts[1][1], pts[1][2], th, col)
				end
			end

			if kind == "puzzle" then
				fill(4, 4, 16, 16, 3)
				dot(12, 4, 6.6)
				dot(4, 12, 6.6)
				dot(20, 12, 5.2, bgc)
				dot(12, 20, 5.2, bgc)
			elseif kind == "puzzleMini" then
				fill(4.4, 5.4, 15.2, 15.2, 3)
				dot(12, 5.4, 6.4)
				dot(4.4, 13, 6.4)
			elseif kind == "grid" then
				fill(3, 3, 7.4, 7.4, 2)
				fill(13.6, 3, 7.4, 7.4, 2)
				fill(3, 13.6, 7.4, 7.4, 2)
				fill(13.6, 13.6, 7.4, 7.4, 2)
			elseif kind == "code" then
				poly({ { 9.5, 6.5 }, { 4.2, 12 }, { 9.5, 17.5 } }, 2.4)
				poly({ { 14.5, 6.5 }, { 19.8, 12 }, { 14.5, 17.5 } }, 2.4)
			elseif kind == "search" then
				ring(10.5, 10.5, 12, 2.4)
				line(16, 16, 21, 21, 2.6)
			elseif kind == "user" then
				dot(12, 8.2, 7)
				arc(12, 20.5, 6.5, 180, 360, 2.6)
			elseif kind == "crown" then
				line(4, 17, 20, 17, 2.6)
				poly({ { 4.6, 16.4 }, { 6.2, 8.2 }, { 9.6, 13.4 }, { 12, 6.6 }, { 14.4, 13.4 }, { 17.8, 8.2 }, { 19.4, 16.4 } }, 2.1)
			elseif kind == "chevron" then
				poly({ { 10.4, 9.2 }, { 14, 13 }, { 10.4, 16.8 } }, 2)
			elseif kind == "sortDown" then
				line(12, 5, 12, 18, 2.1)
				poly({ { 7.6, 13.4 }, { 12, 18 }, { 16.4, 13.4 } }, 2.1)
			elseif kind == "plus" then
				fill(10.4, 5.6, 3.2, 12.8, 1.4)
				fill(5.6, 10.4, 12.8, 3.2, 1.4)
			elseif kind == "play" then
				poly({ { 9.2, 6.4 }, { 18.2, 12 }, { 9.2, 17.6 } }, 2.8, true)
			elseif kind == "shield" then
				poly({ { 12, 3.2 }, { 19.6, 6.2 }, { 19, 13.6 }, { 12, 20.8 }, { 5, 13.6 }, { 4.4, 6.2 } }, 2.1, true)
			elseif kind == "shieldCheck" then
				poly({ { 12, 3.2 }, { 19.6, 6.2 }, { 19, 13.6 }, { 12, 20.8 }, { 5, 13.6 }, { 4.4, 6.2 } }, 2.1, true)
				poly({ { 8.4, 11.6 }, { 11, 14.6 }, { 16.2, 8.4 } }, 2.1)
			elseif kind == "shieldScan" then
				poly({ { 12, 3.2 }, { 19.6, 6.2 }, { 19, 13.6 }, { 12, 20.8 }, { 5, 13.6 }, { 4.4, 6.2 } }, 1.8, true)
				ring(12.4, 11, 7.2, 1.7)
				line(14.6, 13.4, 17.6, 16.6, 1.9)
			elseif kind == "terminal" then
				obox(3.4, 5, 17.2, 14, 3, 1.9)
				poly({ { 6.6, 10.4 }, { 9.2, 13 }, { 6.6, 15.6 } }, 1.8)
				line(11.6, 16.2, 16.4, 16.2, 1.8)
			elseif kind == "bulb" then
