		-- Label boxes are sized from the engine's own text advance. Measured off the tablet at 2.25
		-- device px per panel unit: "EXTENSIONS" inks 45.8 and "MY ITEMS" 34.7 at size 8.5, i.e.
		-- ~0.54 em for an uppercase run. The flat 4.15/char guess this replaces sized "ALL" one pixel
		-- short of its 13 px box and the engine answered with "A…"; "EXTENSION" and "USER" chips were
		-- cut the same way. 0.60 keeps a margin over the widest string measured.
		local ADV = 0.60
		local function textW(text, size)
			return math.ceil(#text * size * ADV)
		end

		-- A card carries one title line and two description lines, and it is 78 units tall at every
		-- column count, so copy that runs past its box used to be clipped by the card's own
		-- ClipsDescendants -- visibly, as a sentence cut mid-word. The budget comes from the same
		-- advance the chips are sized with; a player's own item name and description are fitted here,
		-- and work/check_card_copy.js holds the built-in copy to the same budget so it never truncates.
		local ELL = "..."
		local function fitCopy(text, width, size, lines)
			text = tostring(text or "")
			local budget = math.max(4, math.floor((width * lines) / (size * ADV)))
			if #text <= budget then
				return text
			end
			return string.sub(text, 1, budget - #ELL) .. ELL
		end

		local function chipWidth(text, hasIcon)
			return (hasIcon and 21 or 12) + textW(text, 8)
		end

		local function chip(parent, x, y, text, color, kind, bgc)
			local w = chipWidth(text, kind ~= nil)
			local f = plate(parent, x, y, w, 14, C.card2, 7, 0, color, 0.42)
			if kind then
				-- 9, not 8: at 8 an owner PNG or the drawn crown both collapse into a blob, and the
				-- pill pays 12 units of width for a mark nobody can read.
				mk(kind, f, 9, color, bgc or C.card2, UDim2.fromOffset(3, 2.5))
			end
			label(f, text, kind and 15 or 5, 0, w - (kind and 16 or 6), 14, 8, color, FB)
			return w
		end

