		----------------------------------------------------------------
		-- USER STORE (CROZIXE1, eight escaped fields per line)
		----------------------------------------------------------------
		local STORE = "Crozix/extensions.txt"
		local HEAD = "CROZIXE1"
		local NL = string.char(10)

		local function esc(s)
			s = tostring(s or "")
			s = string.gsub(s, "\\", "\\\\")
			s = string.gsub(s, "\n", "\\n")
			s = string.gsub(s, "\r", "\\r")
			s = string.gsub(s, "\t", "\\t")
			return s
		end

		local function unesc(s)
			local out = {}
			local i, n = 1, #s
			while i <= n do
				local ch = string.sub(s, i, i)
				if ch == "\\" and i < n then
					local nx = string.sub(s, i + 1, i + 1)
					if nx == "n" then
						out[#out + 1] = NL
					elseif nx == "r" then
						out[#out + 1] = string.char(13)
					elseif nx == "t" then
						out[#out + 1] = "\t"
					else
						out[#out + 1] = nx
					end
					i = i + 2
				else
					out[#out + 1] = ch
					i = i + 1
				end
			end
			return table.concat(out)
		end

		local function splitTabs(line)
			local out, start = {}, 1
			while true do
				local tab = string.find(line, "\t", start, true)
				if not tab then
					out[#out + 1] = string.sub(line, start)
					break
				end
				out[#out + 1] = string.sub(line, start, tab - 1)
				start = tab + 1
			end
			return out
		end

		local function makeUser(rec)
			local ext = rec[4] == "extension"
			return {
				id = rec[1],
				name = rec[2],
				description = rec[3],
				icon = ext and "puzzle" or "code",
				category = ext and (rec[8] ~= "" and rec[8] or "Utility") or "Custom",
				itemType = rec[4],
				source = "user",
				status = "active",
				actionType = ext and "run" or "execute",
				version = "1.0",
				createdAt = rec[6],
				updatedAt = rec[6],
				created = tonumber(rec[6]) or os.time(),
				uses = tonumber(rec[7]) or 0,
				code = rec[5],
				extensionType = rec[8],
				keywords = { "custom", "user", rec[4] },
			}
		end

		local USER = {}
		local function loadUser()
			USER = {}
			local raw, existed = nil, false
			pcall(function()
				if type(isfile) == "function" and isfile(STORE) then
					existed = true
					raw = readfile(STORE)
				end
			end)
			if type(raw) ~= "string" then
				return false, existed
			end
			raw = string.gsub(raw, string.char(13) .. NL, NL)
			local sawHead = false
			for line in string.gmatch(raw, "([^\n]+)") do
				if not sawHead then
					if line ~= HEAD then
						USER = {}
						return false, true
					end
					sawHead = true
				else
					local f = splitTabs(line)
					if #f >= 8 and f[2] ~= "" then
						USER[#USER + 1] = makeUser(f)
					end
				end
			end
			return sawHead, existed
		end

		local function persist()
			local lines = { HEAD }
			for _, it in ipairs(USER) do
				lines[#lines + 1] = table.concat({
					esc(it.id), esc(it.name), esc(it.description), esc(it.itemType), esc(it.code),
					esc(it.createdAt), esc(it.uses), esc(it.extensionType or ""),
				}, "\t")
			end
			local text = table.concat(lines, NL) .. NL
			if type(writefile) ~= "function" then
				return false, "this engine has no file writer"
			end
			if not pcall(writefile, STORE, text) then
				return false, "the device refused the write"
			end
			local back
			pcall(function()
				back = readfile(STORE)
			end)
			if type(back) ~= "string" then
				return false, "the file could not be read back"
			end
			local n = 0
			for line in string.gmatch(back, "([^\n]+)") do
				if line ~= HEAD then
					n = n + 1
				end
			end
			if n ~= #USER then
				return false, "the device kept " .. n .. " of " .. #USER .. " items"
			end
			return true
		end

		local hadStore, fileExisted = loadUser()
		-- One destination per kind: user scripts older builds kept here are copied into the shared
		-- saved-scripts store once, then this store keeps tools only. Content is preserved; a row is
		-- only dropped after its copy verifies.
		do
			local moved = false
			local keep = {}
			for _, it in ipairs(USER) do
				if it.itemType == "script" and type(CROZIX.save) == "function" then
					if pcall(CROZIX.save, it.name, it.code) then
						moved = true
					else
						keep[#keep + 1] = it
					end
				else
					keep[#keep + 1] = it
				end
			end
			if moved then
				USER = keep
				persist()
			end
		end
		if not hadStore and not fileExisted then
			-- The starter card from the reference: a real snippet, so MY ITEMS, the counters and
			-- the search are not empty on a first run. It is saved once and can be deleted by hand.
			local now = os.time()
			USER = { {
				id = "user_seed",
				name = "My Custom Script",
				description = "Added by you. A starter snippet saved on this device.",
				icon = "dashedPlus",
				category = "Custom",
				itemType = "script",
				source = "user",
				status = "active",
				actionType = "execute",
				version = "1.0",
				createdAt = tostring(now),
				updatedAt = tostring(now),
				created = now,
				uses = 0,
				code = 'print("Crozix: my first script ran.")',
				extensionType = "",
				keywords = { "custom", "user", "script", "starter" },
			} }
			persist()
		end

		-- Scripts are managed in the unified Scripts section; the store lists application tools only.
		local function allItems()
			local out = {}
			for _, it in ipairs(BUILTIN) do
				if it.itemType == "extension" then
					out[#out + 1] = it
				end
			end
			for _, it in ipairs(USER) do
				if it.itemType == "extension" then
					out[#out + 1] = it
				end
			end
			return out
		end

