		local function openScript()
			if type(CROZIX.activeText) ~= "function" then
				return nil, nil, "the editor is not ready yet"
			end
			local src, name = CROZIX.activeText()
			if type(src) ~= "string" or src:match("^%s*$") then
				return nil, nil, "no script is open"
			end
			return src, name, nil
		end

		----------------------------------------------------------------
		-- ACTIONS (one real handler per actionType)
		----------------------------------------------------------------
		local function runCode(code, name)
			if type(code) ~= "string" or code == "" then
				notify("This item has no code yet.", C.amber)
				return
			end
			local ok, res, msg = pcall(Config.OnExecute, code, name or "Extension")
			if not ok then
				notify("Could not run " .. tostring(name) .. ": " .. tostring(res), C.red)
			elseif res == false then
				notify(tostring(msg or "The engine refused it."), C.red)
			else
				notify(tostring(name or "Script") .. " sent to the engine.", C.green)
			end
		end

		local KB_URL = "https://crozomods.xyz/assets/MobileKeyboard.txt"
		local KB_LOCAL = "Crozix/assets/MobileKeyboard.txt"

		local function runKeyboard()
			local code
			pcall(function()
				if type(isfile) == "function" and isfile(KB_LOCAL) then
					code = readfile(KB_LOCAL)
				end
			end)
			if type(code) == "string" and #code > 100 then
				runCode(code, "Virtual Keyboard")
				return
			end
			notify("Fetching the keyboard...", C.muted)
			local function work()
				local ok, body = CROZIX.httpGet(KB_URL)
				if ok and #body > 100 then
					runCode(body, "Virtual Keyboard")
				else
					notify("The keyboard did not download.", C.red)
				end
			end
			if type(task) == "table" and type(task.defer) == "function" then
				task.defer(work)
			else
				work()
			end
		end

		-- Scanning and checking read the open script and never call it. The verdict comes from the
		-- adapter's scan, so this pane and the Execute button cannot drift apart.
		local TONE = {
			high = C.red, medium = C.amber, low = C.muted, none = C.green,
			ok = C.green, info = C.text, warn = C.amber, danger = C.red,
		}

		local function scanScript()
			local src, name, err = openScript()
			local rows = {}
			if not src then
				rows[1] = { text = tostring(err), tone = "warn" }
				showResults("SCAN SCRIPT", "Script Checker", rows,
					"Open a script in the editor, then run the scan again.")
				return
			end
			if type(CROZIX.protectionScan) ~= "function" then
				rows[1] = { text = "The protection scan is not available in this build.", tone = "danger" }
				showResults("SCAN SCRIPT", "Script Checker", rows, "Nothing was read.")
				return
			end
			local result = CROZIX.protectionScan(src)
			if type(result) ~= "table" then
				rows[1] = { text = "There is nothing to scan.", tone = "warn" }
				showResults("SCAN SCRIPT", "Script Checker", rows, "Nothing was read.")
				return
			end
			rows[#rows + 1] = {
				text = string.format("%s: %d lines, %s", tostring(name or "the open script"),
					tonumber(result.lines) or 0, tostring(result.size or "")),
				tone = "info",
			}
			for _, f in ipairs(result.findings or {}) do
				local where = (tonumber(f.line) or 0) > 0 and ("line " .. f.line .. ": ") or ""
				rows[#rows + 1] = { text = where .. tostring(f.label), tone = f.sev or "low" }
			end
			if (tonumber(result.urls) or 0) > 0 then
				rows[#rows + 1] = {
					text = result.urls .. " line(s) mention a URL - that code is not visible here",
					tone = "medium",
				}
			end
			rows[#rows + 1] = { text = "Verdict: " .. tostring(result.verdict), tone = result.worst or "none" }
			showResults("SCAN SCRIPT", "Looking for risky calls in the open script.", rows,
				"A scan is a review, not a guarantee of safety. Scanning and checking read the open script; neither runs it.")
		end

		local function compileScript()
			local src, name, err = openScript()
			local rows = {}
			if not src then
				rows[1] = { text = tostring(err), tone = "warn" }
				showResults("CHECK CODE", "Compile Check", rows, "Open a script in the editor, then try again.")
				return
			end
			local compile = loadstring or load
			if type(compile) ~= "function" then
				rows[1] = { text = "This engine gives no compiler here.", tone = "danger" }
				showResults("CHECK CODE", "Compile Check", rows, "Nothing was compiled.")
				return
			end
			local chunk, cerr = compile(src)
			if chunk then
				rows[1] = {
					text = tostring(name or "the script") .. " compiles clean (" .. #src .. " B). Nothing was run.",
					tone = "ok",
				}
			else
				rows[1] = { text = "It will not run: " .. tostring(cerr), tone = "danger" }
			end
			showResults("CHECK CODE", "Compile check - syntax only.", rows,
				"Compiling is a syntax check only. The chunk is never called.")
		end

		-- A user extension is a registered interface: it returns a function that receives the open
		-- script (source, name). It is never installed as a button by itself.
		local function runUserExtension(it)
			local compile = loadstring or load
			if type(compile) ~= "function" then
				notify("This engine gives no compiler here.", C.red)
				return
			end
			local chunk, cerr = compile(it.code)
			if not chunk then
				notify("This extension does not compile: " .. tostring(cerr), C.red)
				return
			end
			local ok, fn = pcall(chunk)
			if not ok or type(fn) ~= "function" then
				notify("This extension must return a function(source, name).", C.red)
				return
			end
			local src, name
			if type(CROZIX.activeText) == "function" then
				src, name = CROZIX.activeText()
			end
			local ran, out = pcall(fn, src or "", name or "")
			if not ran then
				notify("The extension failed: " .. tostring(out), C.red)
			elseif type(out) == "string" and out ~= "" then
				if type(CROZIX.log) == "function" then
					pcall(CROZIX.log, out, T.TextSecondary)
				end
				notify(it.name .. " finished - see Crozix Console.", C.green)
			else
				notify(it.name .. " finished.", C.green)
			end
		end

		local function act(it)
			it.uses = (it.uses or 0) + 1
			if it.id == "fps_boost" then
				runCode(FPS_CODE, it.name)
			elseif it.id == "virtual_keyboard" then
				runKeyboard()
			elseif it.id == "auto_rejoin" then
				runCode(REJOIN_CODE, it.name)
			elseif it.id == "script_checker" or it.id == "scan_protection" then
				scanScript()
			elseif it.id == "compile_check" then
				compileScript()
			elseif it.source == "user" and it.itemType == "extension" then
				runUserExtension(it)
			elseif it.source == "user" then
				runCode(it.code, it.name)
			else
				notify("This item has no action.", C.amber)
			end
			if it.source == "user" then
				persist()
			end
		end

