		----------------------------------------------------------------
		-- CARDS + GRID
		----------------------------------------------------------------
		-- Section 18 (responsive): the store reflows 3/2/1 columns with the rendered window instead
		-- of only shrinking the same 196-unit card under UIScale. The content width is kept and handed
		-- to fewer, wider cards; the height grows one step so a wide row keeps the same text rhythm.
		local COLS, CW, CH, CGAP = 3, 196, 78, 8
		local GRID_INNER = 604
		local CARD_H = { [3] = 78, [2] = 78, [1] = 100 }
		local GRID_VIEW = 164
		-- Section 18: the viewport shows whole rows only. A row clipped mid-card against the banner
		-- reads as a broken layout, so the viewport is the tallest whole number of rows that fits the
		-- store's original height; scrolling still reveals the remaining rows.
		local function viewHeightFor(n)
			local h = CARD_H[n] or CARD_H[3]
			local rows = math.max(1, math.floor((GRID_VIEW + CGAP) / (h + CGAP)))
			return rows * (h + CGAP) - CGAP
		end
		local grid = new("ScrollingFrame", {
			Name = "ExtGrid",
			Position = UDim2.fromOffset(10, 98),
			Size = UDim2.fromOffset(612, GRID_VIEW),
			BackgroundTransparency = 1,
			CanvasSize = UDim2.new(),
			ScrollingDirection = Enum.ScrollingDirection.Y,
			ScrollBarThickness = 3,
			ScrollBarImageColor3 = C.line,
			ZIndex = 2,
			Parent = pane,
		})

		local function makeCard(it, x, y)
			local isExt = it.itemType == "extension"
			local isUser = it.source == "user"
			local accent = isUser and C.text or (isExt and C.steel or C.red)
			local art = isUser and C.text or (isExt and C.steel or C.red)
			local tint = C.card2

			local b = new("TextButton", {
				Name = "ExtCard_" .. tostring(it.id),
				Size = UDim2.fromOffset(CW, CH),
				Position = UDim2.fromOffset(x, y),
				BackgroundColor3 = C.card,
				BackgroundTransparency = 0,
				ClipsDescendants = true,
				ZIndex = 2,
				Parent = grid,
			})
			corner(b, 12)
			new("UIGradient", { Rotation = 90, Color = ColorSequence.new(C.card2, C.card), Parent = b })
			local cs = stroke(b, C.line, 1, 0.3)

			local tile = plate(b, 8, 8, 30, 30, C.card2, 8, 0, accent, 0.62)
			new("UIGradient", { Rotation = 90, Color = ColorSequence.new(tint, C.card2), Parent = tile })
			tile.ZIndex = 3
			local artFrame = mk(it.icon, b, 21, art, tint, UDim2.fromOffset(12, 12))
			artFrame.Root.ZIndex = 4

			local ttl = label(b, fitCopy(it.name, CW - 50, 11, 1), 42, 4, CW - 50, 14, 11, C.text, FB)
			ttl.ZIndex = 3
			local dsc = wrap(label(b, fitCopy(it.description, CW - 50, 9, 2), 42, 19, CW - 50, 20, 9, C.muted, FM))
			dsc.ZIndex = 3

			local catIcon = CATEGORY_ICON[it.category] or "info"
			-- 11, not 9: a 64-unit mark scaled to 9 loses its own interior and reads as a smudge
			-- beside the category word it is duplicating.
			mk(catIcon, b, 11, C.muted, C.card, UDim2.fromOffset(7, 42)).Root.ZIndex = 3
			local catLabel = label(b, it.category, 22, 41, 86, 14, 8, C.muted, FM)
			catLabel.ZIndex = 3

			if isUser then
				local sw = chipWidth("USER", true)
				chip(b, CW - 8 - sw, 41, "USER", C.text, "user", C.card)
			else
				local sw = chipWidth("BUILT-IN", true)
				chip(b, CW - 8 - sw, 41, "BUILT-IN", C.red, "crown", C.card)
			end

			local typeText = isUser and (isExt and "USER EXTENSION" or "USER SCRIPT")
				or (isExt and "EXTENSION" or "SCRIPT")
			local typeColor = isUser and C.text or (isExt and C.steel or C.red)
			chip(b, 8, CH - 20, typeText, typeColor, nil, C.card)

			local A = ACTION[it.actionType] or ACTION.execute
			-- named: the action pill is the one control that must sit on the card's right edge in
			-- every column count, and the layout probe reads it by name.
			local pill = plate(b, CW - 88, CH - 20, 80, 18, C.red2, 9, 0, C.red, 0.25)
			pill.Name = "ExtAction"
			pill.ZIndex = 4
			new("UIGradient", { Rotation = 90, Color = ColorSequence.new(C.red, C.red2), Parent = pill })
			mk(A.icon, b, 7, C.text, nil, UDim2.fromOffset(CW - 82, CH - 15)).Root.ZIndex = 5
			local al = label(b, A.text, CW - 72, CH - 20, 62, 18, 7.5, C.text, FB, CENTER)
			al.ZIndex = 5

			b.Activated:Connect(function()
				act(it)
			end)
			b.MouseEnter:Connect(function()
				tw(cs, 0.12, { Transparency = 0.05, Color = accent })
			end)
			b.MouseLeave:Connect(function()
				tw(cs, 0.12, { Transparency = 0.3, Color = C.line })
			end)
			return b
		end

		renderGrid = function()
			for _, c in ipairs(gridCards) do
				c:Destroy()
			end
			gridCards = {}

			local all = allItems()
			local counts = { ALL = #all, SCRIPTS = 0, EXTENSIONS = 0, ["MY ITEMS"] = 0 }
			for _, it in ipairs(all) do
				if it.itemType == "script" then
					counts.SCRIPTS = counts.SCRIPTS + 1
				else
					counts.EXTENSIONS = counts.EXTENSIONS + 1
				end
				if it.source == "user" then
					counts["MY ITEMS"] = counts["MY ITEMS"] + 1
				end
			end
			for key, l in pairs(countLabels) do
				l.Text = tostring(counts[key] or 0)
			end
			for key, btn in pairs(filterBtns) do
				btn.set(key == state.filter)
			end

			local list = {}
			local q = state.q
			for _, it in ipairs(all) do
				local keep = true
				if state.filter == "SCRIPTS" then
					keep = it.itemType == "script"
				elseif state.filter == "EXTENSIONS" then
					keep = it.itemType == "extension"
				elseif state.filter == "MY ITEMS" then
					keep = it.source == "user"
				end
				if keep and q ~= "" then
					local hay = string.lower(table.concat({
						it.name, it.description, it.category, it.itemType, it.source,
						table.concat(it.keywords or {}, " "),
					}, " "))
					keep = string.find(hay, q, 1, true) ~= nil
				end
				if keep then
					list[#list + 1] = it
				end
			end

			table.sort(list, function(a, b)
				if state.sort == "oldest" then
					return (a.created or 0) < (b.created or 0)
				elseif state.sort == "name" then
					return string.lower(a.name) < string.lower(b.name)
				elseif state.sort == "used" then
					return (a.uses or 0) > (b.uses or 0)
				end
				return (a.created or 0) > (b.created or 0)
			end)

			if #list == 0 then
				gridCards[#gridCards + 1] = label(grid, "Nothing matches that yet.", 0, 44, 604, 22, 11, C.text, FB, CENTER)
				gridCards[#gridCards + 1] = label(grid, "Try another word or switch the filter.", 0, 68, 604, 18, 9.5, C.muted, FM, CENTER)
			end

			local rows = 0
			for i, it in ipairs(list) do
				local col = (i - 1) % COLS
				local row = math.floor((i - 1) / COLS)
				rows = row + 1
				gridCards[#gridCards + 1] = makeCard(it, col * (CW + CGAP), row * (CH + CGAP))
			end
			local canvas = math.max(GRID_VIEW, rows * (CH + CGAP) - CGAP)
			grid.CanvasSize = UDim2.fromOffset(GRID_INNER, canvas)
			pcall(function()
				grid.CanvasPosition = Vector2.new(0, 0)
			end)
		end

		-- 3 columns on a desktop-sized window, 2 once the panel is scaled below its compact
		-- threshold (0.85, the same point that folds the editor columns), 1 on a phone (0.62, just
		-- above the 0.45 smart floor). A reflow rebuilds the handful of cards -- same widgets and
		-- actions, new geometry -- and returns whether anything moved, so callers can stay quiet.
		-- Section 18: the tablet class is about the device, not only its fit; this tablet renders
		-- the window at desktop scale, so the scale ladder alone hands it three columns. Touch-only
		-- devices are classified by the viewport short side; mouse/keyboard windows keep the ladder
		-- so a merely narrow desktop window still reflows.
		local function colsForDevice(scale, class)
			if class == "tablet" then
				return 2
			elseif class == "phone" then
				return 1
			end
			if scale < 0.62 then
				return 1
			elseif scale < 0.85 then
				return 2
			end
			return 3
		end
		local function deviceClass(scale)
			local cls = "desktop"
			pcall(function()
				if not (UserInputService.TouchEnabled and not UserInputService.MouseEnabled) then
					return
				end
				local minSide = 0
				pcall(function()
					local vp = Gui.AbsoluteSize
					minSide = math.min(vp.X, vp.Y)
				end)
				if minSide <= 1 then
					cls = ((scale or 1) < 0.85) and "phone" or "tablet"
				else
					cls = minSide >= 600 and "tablet" or "phone"
				end
			end)
			return cls
		end
		local function colsFor(scale)
			return colsForDevice(scale, deviceClass(scale))
		end

		local function applyLayout(scale)
			local n = colsFor(scale or 1)
			local w = math.floor((GRID_INNER - (n - 1) * CGAP) / n)
			local h = CARD_H[n]
			if n == COLS and w == CW and h == CH then
				return false
			end
			COLS, CW, CH = n, w, h
			grid.Size = UDim2.fromOffset(612, viewHeightFor(n))
			renderGrid()
			return true
		end

