				saveLabel.Text = "Save Extension"
				codeLabel.Text = "EXTENSION CODE"
				codeLabel.Position = UDim2.fromOffset(14, 158)
				codePlate.Position = UDim2.fromOffset(14, 170)
				codePlate.Size = UDim2.fromOffset(432, 56)
				codeBox.PlaceholderText = "return function(source, name) ... end"
				typeRow.Visible = true
			else
				formTitle.Text = "Add Custom Script"
				formKind.Text = "SCRIPT"
				formKind.TextColor3 = C.red
				saveLabel.Text = "Save Script"
				codeLabel.Text = "SCRIPT CODE"
				codeLabel.Position = UDim2.fromOffset(14, 90)
				codePlate.Position = UDim2.fromOffset(14, 104)
				codePlate.Size = UDim2.fromOffset(432, 122)
				codeBox.PlaceholderText = "Paste the code here..."
				typeRow.Visible = false
			end
			pcall(function()
				nameBox:CaptureFocus()
			end)
		end

		openModal = function()
			showChoose()
			modalLayer.Visible = true
		end

		local function saveItem()
			local name = string.gsub(nameBox.Text or "", "^%s*(.-)%s*$", "%1")
			local desc = string.gsub(descBox.Text or "", "^%s*(.-)%s*$", "%1")
			local code = codeBox.Text or ""
			errLabel.Text = ""
			if name == "" then
				errLabel.Text = "Give it a name first."
				return
			end
			if #name > 40 then
				errLabel.Text = "The name is longer than 40 characters."
				return
			end
			if string.gsub(code, "%s", "") == "" then
				errLabel.Text = "There is no code to save."
				return
			end
			local compile = loadstring or load
			if type(compile) ~= "function" then
				errLabel.Text = "This engine gives no compiler here."
				return
			end
			local chunk, cerr = compile(code)
			if not chunk then
				errLabel.Text = "It does not compile: " .. tostring(cerr)
				return
			end
			if modalShape == "extension" then
				local head = string.gsub(code, "^%s+", "")
				if not string.find(head, "^return%s+function") then
					errLabel.Text = "An extension must return a function(source, name)."
					return
				end
			end
			if desc == "" then
				desc = modalShape == "extension" and "A tool added by you." or "A script added by you."
			end
			local now = os.time()
			local it = {
				id = "user_" .. tostring(now) .. "_" .. tostring(#USER + 1),
				name = name,
				description = desc,
				icon = modalShape == "extension" and "puzzle" or "code",
				category = modalShape == "extension" and chosenType or "Custom",
				itemType = modalShape,
				source = "user",
				status = "active",
				actionType = modalShape == "extension" and "run" or "execute",
				version = "1.0",
				createdAt = tostring(now),
				updatedAt = tostring(now),
				created = now,
				uses = 0,
				code = code,
				extensionType = modalShape == "extension" and chosenType or "",
				keywords = { "custom", "user", modalShape },
			}
			if modalShape == "script" then
				local sok, swhy = pcall(CROZIX.save, name, code)
				if not sok then
					errLabel.Text = "Not saved: " .. tostring(swhy)
					return
				end
				closeModal()
				notify(name .. " saved to Scripts > Saved Scripts.", C.green)
				return
			end
			USER[#USER + 1] = it
			local ok, why = persist()
			if not ok then
				USER[#USER] = nil
				errLabel.Text = "Not saved: " .. tostring(why)
				return
			end
			closeModal()
			renderGrid()
			notify(name .. " saved on this device.", C.green)
		end

		pathScript.Activated:Connect(function()
			showForm("script")
		end)
		pathExtension.Activated:Connect(function()
			showForm("extension")
		end)
		cancelBtn.Activated:Connect(closeModal)
		backBtn.Activated:Connect(showChoose)
		saveBtn.Activated:Connect(saveItem)

		----------------------------------------------------------------
		-- HEADER
		----------------------------------------------------------------
		local header = plate(pane, 10, 4, 612, 42, C.panel, 12, 0, C.red, 0.7)
		header.ZIndex = 2
		new("UIGradient", { Rotation = 90, Color = ColorSequence.new(C.card, C.panel), Parent = header })
		mk("puzzle", header, 28, C.red, C.panel, UDim2.fromOffset(10, 8)).Root.ZIndex = 3
		label(header, "Extensions", 46, 4, 260, 22, 17.5, C.text, FL).ZIndex = 3
		label(header, "Enhance your experience with powerful extensions.", 46, 26, 340, 13, 10, C.muted, FM).ZIndex = 3

		-- the button's red halo sits above the header, so it reads as light on the surface rather than
		-- a painted plate hidden under it; the button itself is one layer above the halo
		local glow = plate(pane, 420, 1, 206, 48, C.red, 14, 0.9)
		glow.ZIndex = 3
		local addBtn = new("TextButton", {
			Name = "CrozixExtAdd",
			Size = UDim2.fromOffset(190, 44),
			Position = UDim2.fromOffset(432, 3),
			BackgroundColor3 = C.red,
			BackgroundTransparency = 0,
			ZIndex = 4,
			Parent = pane,
		})
		corner(addBtn, 12)
		stroke(addBtn, C.red, 1, 0.15)
		new("UIGradient", { Rotation = 90, Color = ColorSequence.new(C.red, C.red2), Parent = addBtn })
		mk("plus", addBtn, 12, C.text, nil, UDim2.fromOffset(12, 16)).Root.ZIndex = 4
		label(addBtn, "Add Custom Extension", 32, 6, 136, 15, 10, C.text, FB).ZIndex = 4
		label(addBtn, "Using a Script", 32, 22, 136, 12, 8.5, C.onRedSoft, FM).ZIndex = 4
		mk("code", addBtn, 11, C.text, nil, UDim2.fromOffset(170, 17)).Root.ZIndex = 4

		----------------------------------------------------------------
		-- TOOLBAR
		----------------------------------------------------------------
		local PILLS = {
			{ key = "ALL", text = "ALL", icon = "grid" },
			{ key = "SCRIPTS", text = "SCRIPTS", icon = "code" },
			{ key = "EXTENSIONS", text = "EXTENSIONS", icon = "puzzleMini" },
			{ key = "MY ITEMS", text = "MY ITEMS", icon = "user" },
		}
		local px = 10
		for _, p in ipairs(PILLS) do
			-- 20 is the glyph column, 21 the counter badge and its clearance; what is left is the
			-- label box, so a pill is never narrower than the word it carries.
			p.w = 20 + textW(p.text, 8.5) + 21
			local holder = new("TextButton", {
				Name = "ExtFilter_" .. p.key,
				Size = UDim2.fromOffset(p.w, 44),
				Position = UDim2.fromOffset(px, 50),
				BackgroundTransparency = 1,
				ZIndex = 2,
				Parent = pane,
			})
			local pill = plate(holder, 0, 9, p.w, 26, C.card, 13, 0, C.line, 0.3)
			pill.ZIndex = 2
			local glyph = mk(p.icon, pill, 10, C.muted, C.card, UDim2.fromOffset(7, 8))
			glyph.Root.ZIndex = 3
			local tl = label(pill, p.text, 20, 0, p.w - 41, 26, 8.5, C.muted, FB)
			tl.ZIndex = 3
			local badge = plate(pill, p.w - 21, 7, 15, 12, C.card2, 6, 0)
			badge.ZIndex = 3
			local bl = label(badge, "0", 0, 0, 15, 12, 7.5, C.muted, FB, CENTER)
			bl.ZIndex = 4
			countLabels[p.key] = bl
			local st = stroke(pill, C.line, 1, 0.3)
			local function set(on)
				pill.BackgroundColor3 = on and C.red or C.card
				pill.BackgroundTransparency = on and 0.82 or 0
				st.Color = on and C.red or C.line
				st.Transparency = on and 0 or 0.3
				tl.TextColor3 = on and C.text or C.muted
				bl.TextColor3 = on and C.text or C.muted
				glyph.SetColor(on and C.text or C.muted)
				badge.BackgroundTransparency = on and 0.7 or 0
			end
			filterBtns[p.key] = { set = set }
			holder.Activated:Connect(function()
				state.filter = p.key
				sortPopup.Visible = false
				sortScrim.Visible = false
				renderGrid()
			end)
			px = px + p.w + 4
		end

		local sortBtn = new("TextButton", {
			Name = "ExtSort",
			Size = UDim2.fromOffset(100, 44),
			Position = UDim2.fromOffset(334, 50),
			BackgroundTransparency = 1,
			ZIndex = 2,
			Parent = pane,
		})
		local sortPill = plate(sortBtn, 0, 9, 100, 26, C.card, 13, 0, C.line, 0.3)
		sortPill.ZIndex = 2
		sortLabel = label(sortPill, "Latest Additions", 10, 0, 74, 26, 8.5, C.text, FB)
		sortLabel.ZIndex = 3
		mk("sortDown", sortPill, 9, C.muted, C.card, UDim2.fromOffset(86, 8)).Root.ZIndex = 3

		sortScrim = new("TextButton", {
			Name = "ExtSortScrim",
			Size = UDim2.fromScale(1, 1),
			BackgroundTransparency = 1,
			Visible = false,
			ZIndex = 59,
			Parent = pane,
		})
		sortPopup = plate(pane, 326, 94, 150, 184, C.panel, 12, 0, C.red, 0.62)
		sortPopup.ZIndex = 60
		sortPopup.Visible = false
		local sortRows = {}
		local sortKeys = { "latest", "oldest", "name", "used" }
		for i, key in ipairs(sortKeys) do
			local row = new("TextButton", {
				Name = "ExtSort_" .. key,
				Size = UDim2.fromOffset(134, 44),
				Position = UDim2.fromOffset(8, 4 + (i - 1) * 44),
				BackgroundTransparency = 1,
				ZIndex = 60,
				Parent = sortPopup,
			})
			local rl = label(row, SORT_LABEL[key], 8, 0, 100, 44, 9, C.muted, FB)
			rl.ZIndex = 61
			local rk = mk("check", row, 9, C.red, nil, UDim2.fromOffset(114, 17))
			rk.Root.ZIndex = 61
			rk.Root.Visible = false
			sortRows[key] = { row = row, label = rl, check = rk.Root }
			row.Activated:Connect(function()
				state.sort = key
				sortLabel.Text = SORT_LABEL[key]
				for k, o in pairs(sortRows) do
					o.label.TextColor3 = k == key and C.text or C.muted
					o.check.Visible = k == key
				end
				sortPopup.Visible = false
				sortScrim.Visible = false
				renderGrid()
			end)
		end
		sortRows.latest.check.Visible = true
		sortRows.latest.label.TextColor3 = C.text

		sortBtn.Activated:Connect(function()
			sortPopup.Visible = not sortPopup.Visible
			sortScrim.Visible = sortPopup.Visible
		end)
		sortScrim.Activated:Connect(function()
			sortPopup.Visible = false
			sortScrim.Visible = false
		end)

		local searchFrame = new("Frame", {
			Position = UDim2.fromOffset(438, 50),
			Size = UDim2.fromOffset(182, 44),
			BackgroundTransparency = 1,
			ZIndex = 2,
			Parent = pane,
		})
		local searchPlate = plate(searchFrame, 0, 9, 182, 26, C.card, 13, 0, C.line, 0.3)
		searchPlate.ZIndex = 2
		local searchStroke = stroke(searchPlate, C.line, 1, 0.3)
		mk("search", searchFrame, 11, C.muted, nil, UDim2.fromOffset(8, 16)).Root.ZIndex = 3
		searchBox = new("TextBox", {
			Name = "ExtSearch",
			Text = "",
			PlaceholderText = "Search for an extension or script...",
			PlaceholderColor3 = C.muted,
			ClearTextOnFocus = false,
			TextXAlignment = LEFT,
			TextSize = 8.5,
			TextColor3 = C.text,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(24, 0),
			Size = UDim2.fromOffset(158, 44),
			ZIndex = 3,
			Parent = searchFrame,
		})
		searchBox.Changed:Connect(function(prop)
			if prop == "Text" then
				state.q = string.lower(searchBox.Text or "")
				renderGrid()
			end
		end)
		searchBox.Focused:Connect(function()
			searchStroke.Color = C.red
			searchStroke.Transparency = 0
		end)
		searchBox.FocusLost:Connect(function()
			searchStroke.Color = C.line
			searchStroke.Transparency = 0.3
		end)

		----------------------------------------------------------------
		-- BANNER
		----------------------------------------------------------------
		local banner = plate(pane, 10, 268, 612, 40, C.panel, 10, 0, C.red, 0.72)
		banner.ClipsDescendants = true
		banner.ZIndex = 2
		new("UIGradient", { Rotation = 0, Color = ColorSequence.new(C.deep, C.panel), Parent = banner })
		for i = 1, 3 do
			local bar = plate(banner, 512 + (i - 1) * 26, -14, 16, 70, C.red2, 4, 0.42 + i * 0.12)
			bar.Rotation = 32
			bar.ZIndex = 2
		end
		mk("bulb", banner, 22, C.red, C.panel, UDim2.fromOffset(12, 9)).Root.ZIndex = 4
		label(banner, "Extensions & Addons", 44, 2, 400, 15, 11, C.text, FB).ZIndex = 4
		local bd = wrap(label(banner,
			"Extensions provide tools to inspect and work with scripts. Addons introduce additional features to CROZIX. Scripts themselves live in the Scripts section.",
			44, 17, 460, 22, 8.5, C.muted, FM))
		bd.ZIndex = 4

		addBtn.Activated:Connect(openModal)

		-- refreshScale already calls CROZIX.applyCompact on every viewport change; chaining keeps
		-- the editor reflow and adds the store's. Exposed on CROZIX so a harness can drive a
		-- reflow without resizing the window.
		local prevCompact = CROZIX.applyCompact
		CROZIX.applyCompact = function(s)
			if prevCompact then
				prevCompact(s)
			end
			applyLayout(s)
		end
		CROZIX.extLayout = applyLayout
		CROZIX.extCols = colsForDevice
		CROZIX.extViewH = viewHeightFor
		CROZIX.uiKit = { plate = plate, label = label, wrap = wrap, mk = mk, chip = chip, textW = textW, C = C }
		CROZIX.builtinScripts = function()
			local out = {}
			for _, it in ipairs(BUILTIN) do
				if it.itemType == "script" then
					out[#out + 1] = it
				end
			end
			return out
		end
		CROZIX.builtinCode = function(id)
			if id == "fps_boost" then
				return FPS_CODE
			end
			if id == "auto_rejoin" then
				return REJOIN_CODE
			end
			if id == "virtual_keyboard" then
				local code
				pcall(function()
					if type(isfile) == "function" and isfile(KB_LOCAL) then
						code = readfile(KB_LOCAL)
					end
				end)
				return code
			end
			return nil
		end
		CROZIX.runBuiltin = function(id)
			for _, it in ipairs(BUILTIN) do
				if it.id == id then
					act(it)
					return true
				end
			end
			return false
		end
		CROZIX.runCode = runCode
		applyLayout(fit)

		renderGrid()
	end
end

extensionsUI()

------------------------------------------------------------------
-- SCRIPTS: the one central script-management section.
-- Three internal tabs (Built-in / Saved / AutoExec), no All tab. Built-in rows reuse the
-- extensions store's own records and executor; Saved rows reuse the shared saved-scripts
-- store and its dialogs; AutoExec is a configuration manager that references those same
-- records instead of copying them. Script Hub stays a separate discovery section.
------------------------------------------------------------------
local function scriptsUI()
	local pane = Panes.save
	local kit = CROZIX.uiKit
	if not pane or not kit then
		return
	end
	local C = kit.C
	local plate, label, wrap, mk, chip = kit.plate, kit.label, kit.wrap, kit.mk, kit.chip
	local textW = kit.textW
	-- label() forwards its tenth argument straight into TextXAlignment, so handing it a TextTruncate
	-- member is accepted by the offline mock and throws on the real engine ("EnumItem of type
	-- TextXAlignment expected"). Callers keep passing only LEFT/CENTER/RIGHT; anything else is dropped
	-- here so a stray TRUNC can never take the whole panel down.
	local rawLabel = label
	label = function(parent, text, x, y, w, h, size, color, font, align)
		if align ~= LEFT and align ~= CENTER and align ~= RIGHT then
			align = nil
		end
		return rawLabel(parent, text, x, y, w, h, size, color, font, align)
	end
	local FB = Enum.Font.GothamBold
	local FM = Enum.Font.GothamMedium
	local FL = Enum.Font.GothamBlack
	local LEFT = Enum.TextXAlignment.Left
	local CENTER = Enum.TextXAlignment.Center
	local TRUNC = Enum.TextTruncate.AtEnd
	local NONE = Enum.TextTruncate.None
	local NL = string.char(10)
	local SEP = string.char(31)
	local refreshSaved, openEditor, syncScope, doSearch, addPlace, saveEditor
	local syncPlaces, renderAssign, aePersistSave
	-- The experience search talks to a remote endpoint, so it keeps the same discipline as the
	-- script hub: one request in flight per term, and a token that drops an answer which a newer
	-- search has already made obsolete.
	local searchToken = 0
	local searchBusy = false
	local searchQuery = ""
	local function copyList(t)
		local o = {}
		for i, v in ipairs(t or {}) do
			o[i] = v
		end
		return o
	end

	-- A layout probe reports a text collision by widget name. A row whose labels are all called
	-- "TextLabel" turns a measurable overlap into a riddle, so the row states its own vocabulary.
	local function named(obj, name, z)
		obj.Name = name
		if z then
			obj.ZIndex = z
		end
		return obj
	end

	------------------------------------------------------------------
	-- HEADER + TAB BAR
	------------------------------------------------------------------
	local header = plate(pane, 10, 4, 612, 42, C.card, 12, 0, C.line, 0.3)
	header.ZIndex = 2
	new("UIGradient", { Rotation = 90, Color = ColorSequence.new(C.card2, C.card), Parent = header })
	mk("save", header, 26, C.red, C.card, UDim2.fromOffset(10, 8)).Root.ZIndex = 3
	label(header, "Scripts", 44, 4, 260, 22, 17.5, C.text, FL).ZIndex = 3
	label(header, "Built-in, saved and automatic scripts in one place.", 44, 26, 400, 13, 10, C.muted, FM).ZIndex = 3

	local TABS = { "Built-in Scripts", "Saved Scripts", "AutoExec" }
	local tabBtns, viewFrames = {}, {}
	local activeTab = 0
	local tabRail = plate(pane, 122, 54, 368, 44, C.panel, 12, 0, C.line, 0.25)
	tabRail.ZIndex = 2
	local tabIndicator = plate(tabRail, 4, 7, 120, 30, C.tintRed, 9, 0, C.red, 0.58)
	tabIndicator.ZIndex = 3
	local tabIndicatorStroke = tabIndicator:FindFirstChildOfClass("UIStroke")
	local function setTab(i)
		local previous = activeTab
		if previous == i then
			return
		end
		activeTab = i
		for k = 1, 3 do
			local on = k == i
			tabBtns[k].TextColor3 = on and C.onRedSoft or C.muted
			if k == previous then
				viewFrames[k].Visible = false
			end
		end
		tw(tabIndicator, 0.18, { Position = UDim2.fromOffset(4 + (i - 1) * 120, 7) },
			Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
		if tabIndicatorStroke then
			tw(tabIndicatorStroke, 0.18, { Transparency = 0.58 })
		end
		local nextView = viewFrames[i]
		if previous == 0 then
			nextView.Visible = true
			return
		end
		local direction = i > previous and 1 or -1
		nextView.Position = UDim2.fromOffset(10 + direction * 7, 104)
		nextView.Visible = true
		tw(nextView, 0.18, { Position = UDim2.fromOffset(10, 104) },
			Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
	end
	for i, name in ipairs(TABS) do
		local b = new("TextButton", {
			Name = "ScriptsTab_" .. i,
			Text = name,
			Font = FB,
			TextSize = 9.5,
			TextColor3 = i == 1 and C.onRedSoft or C.muted,
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(4 + (i - 1) * 120, 0),
			Size = UDim2.fromOffset(120, 44),
			ZIndex = 4,
			Parent = tabRail,
		})
		tabBtns[i] = b
		local f = new("Frame", {
			Name = "ScriptsView_" .. i,
			Position = UDim2.fromOffset(10, 104),
			Size = UDim2.fromOffset(612, 204),
			BackgroundTransparency = 1,
			Visible = false,
			ZIndex = 2,
			Parent = pane,
		})
		viewFrames[i] = f
		b.MouseEnter:Connect(function()
			if activeTab ~= i then
				tw(b, CROZIX.D.MOTION.State, { TextColor3 = C.text })
			end
		end)
		b.MouseLeave:Connect(function()
			if activeTab ~= i then
				tw(b, CROZIX.D.MOTION.State, { TextColor3 = C.muted })
			end
		end)
		b.Activated:Connect(function()
			setTab(i)
		end)
	end

	-- The visible plate stays compact but the tap target is the 44px touch floor: a transparent
	-- button carries the hit area and the painted plate sits inside it.
	local function smallBtn(parent, x, y, w, text, kind, fn)
		local b = new("TextButton", {
			Text = "",
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(x, y - 12),
			Size = UDim2.fromOffset(w, 44),
			ZIndex = 3,
			Parent = parent,
		})
		local face = plate(b, 0, 12, w, 20, kind == "accent" and C.red or C.card2, 8, 0,
			kind == "accent" and C.red or C.line, 0.3)
		face.ZIndex = 3
		local lbl = label(face, text, 0, 0, w, 20, 8, kind == "accent" and C.text or C.muted, FB, CENTER)
		lbl.ZIndex = 4
		local scale = new("UIScale", { Scale = 1, Parent = face })
		b.MouseEnter:Connect(function()
			if kind ~= "accent" then
				tw(face, CROZIX.D.MOTION.State, { BackgroundColor3 = C.line })
			end
		end)
		b.MouseLeave:Connect(function()
			tw(face, CROZIX.D.MOTION.State, { BackgroundColor3 = kind == "accent" and C.red or C.card2 })
			tw(scale, CROZIX.D.MOTION.Press, { Scale = 1 })
		end)
		b.MouseButton1Down:Connect(function()
			tw(scale, CROZIX.D.MOTION.Press, { Scale = 0.96 })
		end)
		b.MouseButton1Up:Connect(function()
			tw(scale, CROZIX.D.MOTION.Press, { Scale = 1 })
		end)
		b.Activated:Connect(fn)
		return b, face, lbl
	end

	------------------------------------------------------------------
	-- TAB 1: BUILT-IN SCRIPTS (records + executor owned by the store)
	------------------------------------------------------------------
	local builtinList = new("ScrollingFrame", {
		Name = "ScriptsBuiltinList",
		Size = UDim2.fromOffset(612, 214),
		BackgroundTransparency = 1,
		CanvasSize = UDim2.new(),
		ScrollingDirection = Enum.ScrollingDirection.Y,
		ScrollBarThickness = 3,
		ScrollBarImageColor3 = C.line,
		Parent = viewFrames[1],
	})
	local function renderBuiltin()
		for _, c in ipairs(builtinList:GetChildren()) do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		local items = CROZIX.builtinScripts()
		local y = 0
		for _, it in ipairs(items) do
			local row = plate(builtinList, 0, y, 606, 64, C.card, 12, 0, C.line, 0.3)
