	------------------------------------------------------------------
	-- TAB 3: AUTOEXEC (configurations referencing existing records)
	------------------------------------------------------------------
	local AE_STORE = "Crozix/autoexec.txt"
	local AE_HEAD = "CROZIXA1"
	local configs = {}
	local function aeEsc(s)
		s = tostring(s or "")
		s = string.gsub(s, "\\", "\\\\")
		s = string.gsub(s, "\t", "\\t")
		s = string.gsub(s, NL, "\\n")
		return s
	end
	local function aeUnesc(s)
		s = string.gsub(s, "\\n", NL)
		s = string.gsub(s, "\\t", "\t")
		s = string.gsub(s, "\\\\", "\\")
		return s
	end
	local function aeSplit(line)
		local out = {}
		for f in string.gmatch(line .. "\t", "([^\t]*)\t") do
			out[#out + 1] = f
		end
		return out
	end
	local function aeLoad()
		configs = {}
		local raw
		pcall(function()
			if type(isfile) == "function" and isfile(AE_STORE) then
				raw = readfile(AE_STORE)
			end
		end)
		if type(raw) ~= "string" then
			return
		end
		raw = string.gsub(raw, string.char(13) .. NL, NL)
		local sawHead = false
		for line in string.gmatch(raw, "([^\n]+)") do
			if not sawHead then
				if line ~= AE_HEAD then
					return
				end
				sawHead = true
			else
				local f = aeSplit(line)
				if #f >= 6 and f[2] ~= "" then
					local places, pnames, refs = {}, {}, {}
					for id in string.gmatch(f[5], "([^" .. SEP .. "]+)") do
						places[#places + 1] = id
					end
					for nm in string.gmatch(f[6], "([^" .. SEP .. "]+)") do
						pnames[#pnames + 1] = aeUnesc(nm)
					end
					for r in string.gmatch(f[7] or "", "([^" .. SEP .. "]+)") do
						refs[#refs + 1] = aeUnesc(r)
					end
					configs[#configs + 1] = {
						id = f[1], name = aeUnesc(f[2]), scope = f[3],
						enabled = f[4] == "1", places = places, placeNames = pnames, refs = refs,
					}
				end
			end
		end
	end
	local function aePersist()
		local lines = { AE_HEAD }
		for _, cf in ipairs(configs) do
			local pn = {}
			for _, nm in ipairs(cf.placeNames) do
				pn[#pn + 1] = aeEsc(nm)
			end
			local rf = {}
			for _, r in ipairs(cf.refs) do
				rf[#rf + 1] = aeEsc(r)
			end
			lines[#lines + 1] = table.concat({
				aeEsc(cf.id), aeEsc(cf.name), cf.scope, cf.enabled and "1" or "0",
				table.concat(cf.places, SEP), table.concat(pn, SEP), table.concat(rf, SEP),
			}, "\t")
		end
		local ok, why = pcall(writefile, AE_STORE, table.concat(lines, NL) .. NL)
		return ok, why
	end
	aeLoad()

