	local function resolveRef(r)
		local kind, key = string.match(r, "^([bs]):(.*)$")
		if kind == "b" then
			return "builtin", key
		elseif kind == "s" then
			return "saved", key
		end
		return nil, nil
	end
	local function refLabel(r)
		local kind, key = resolveRef(r)
		if kind == "builtin" then
			for _, it in ipairs(CROZIX.builtinScripts()) do
				if it.id == key then
					return it.name
				end
			end
			return key .. " (missing)"
		elseif kind == "saved" then
			if saved[key] ~= nil then
				return key
			end
			return key .. " (missing)"
		end
		return r
	end

