		local all = editorState.scope == "all"
		scopeAllFace.BackgroundColor3 = all and C.red or C.card2
		scopeAllLabel.TextColor3 = all and C.text or C.muted
		scopeSpecFace.BackgroundColor3 = (not all) and C.red or C.card2
		scopeSpecLabel.TextColor3 = (not all) and C.text or C.muted
		specGroup.Visible = not all
		-- A global config has no experience picker; collapse its reserved band so the sheet stays
		-- compact instead of showing a dead gap above the assignment list.
		local off = all and -212 or 0
		placesRow.Position = UDim2.fromOffset(40, 396 + off)
		assignHeader.Position = UDim2.fromOffset(40, 418 + off)
		assignCount.Position = UDim2.fromOffset(380, 420 + off)
		assignList.Position = UDim2.fromOffset(16, 440 + off)
		edErr.Position = UDim2.fromOffset(16, 572 + off)
		edCancel.Position = UDim2.fromOffset(440, 588 + off)
		edSave.Position = UDim2.fromOffset(526, 588 + off)
		-- The canvas must cover whatever actually sits deepest: the assignment list's own rows when
		-- the picker band is collapsed, and the action row when it is not. Deriving it from `off`
		-- alone left the all-scope sheet shorter than the rows it still has to scroll past.
		local deepest = (16 + 440) + 126
		if not all then
			deepest = math.max(deepest, 588 + 32)
		end
		edScroll.CanvasSize = UDim2.fromOffset(612, math.max(636 + off, deepest + 12))
	end
	addPlace = function(id, name)
		for _, p in ipairs(editorState.places) do
			if p == id then
				return
			end
		end
		editorState.places[#editorState.places + 1] = id
		editorState.placeNames[#editorState.placeNames + 1] = name
		syncPlaces()
	end
	syncPlaces = function()
		if #editorState.places == 0 then
			placesRow.Text = "Selected: none"
		else
			placesRow.Text = "Selected: " .. table.concat(editorState.placeNames, ", ")
		end
	end
	doSearch = function(q, force)
		q = string.gsub(q or "", "^%s+", "")
		q = string.gsub(q, "%s+$", "")
		if q == "" then
			searchState.Text = "Type a name to search."
			searchState.TextColor3 = C.muted
			return
		end
		-- One live request per term: a second press must not open a second connection while the
		-- first one is still on the wire. RETRY passes force and always asks again.
		if not force and searchBusy and searchQuery == q then
			return
		end
		searchBusy = true
		searchQuery = q
		searchToken = searchToken + 1
		local mine = searchToken
		searchState.Text = "Searching..."
		searchState.TextColor3 = C.muted
		retryBtn.Visible = false
		for _, c in ipairs(resultList:GetChildren()) do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		local url = "https://games.roblox.com/v1/games/list?model.keyword="
			.. string.gsub(q, "([^%w])", function(ch)
				return string.format("%%%02X", string.byte(ch))
			end)
			.. "&model.startRows=0&model.maxRows=8"
		task.spawn(function()
			local ok, body = CROZIX.httpGet(url)
			-- A newer search has already started, so this answer is stale: it must not paint over
			-- the results the user is waiting for, and it must not touch the state line either.
			if mine ~= searchToken then
				return
			end
			searchBusy = false
			local games
			if ok and type(body) == "string" then
				local pok, decoded = pcall(function()
					return game:GetService("HttpService"):JSONDecode(body)
				end)
				if pok and type(decoded) == "table" then
					games = decoded.games
				end
			end
			if type(games) ~= "table" then
				searchState.Text = "Search unavailable. Use Add by ID instead."
				searchState.TextColor3 = C.amber
				retryBtn.Visible = true
				return
			end
			if #games == 0 then
				searchState.Text = "No experiences match that name."
				searchState.TextColor3 = C.muted
				return
			end
			searchState.Text = tostring(#games) .. " result(s). Tap one to select."
			searchState.TextColor3 = C.muted
			local y = 0
			for _, g in ipairs(games) do
				local pid = tostring(g.rootPlaceId or g.placeId or "")
				local selected = false
				for _, place in ipairs(editorState.places) do
					if place == pid then selected = true end
				end
				local row = plate(resultList, 0, y, 578, 40, selected and C.tintRed or C.card, 8, 0, selected and C.red or C.line, 0.3)
				row.ZIndex = 44
				local img = new("ImageLabel", {
					Image = "rbxthumb://type=GameIcon&id=" .. tostring(g.universeId or 0) .. "&w=48&h=48",
					BackgroundTransparency = 1,
					Position = UDim2.fromOffset(3, 10),
					Size = UDim2.fromOffset(20, 20),
					ZIndex = 45,
					Parent = row,
				})
				label(row, tostring(g.name or "Unknown"), 28, 0, 330, 40, 9.5, C.text, FB).ZIndex = 45
				label(row, pid, 360, 0, 120, 40, 8.5, C.muted, FM).ZIndex = 45
				local pick = new("TextButton", {
					Text = "",
					BackgroundTransparency = 1,
					Position = UDim2.fromOffset(506, 0),
					Size = UDim2.fromOffset(66, 44),
					ZIndex = 45,
					Parent = row,
				})
				local pickFace = plate(pick, 0, 11, 66, 18, C.red, 7, 0)
				pickFace.ZIndex = 45
				local pickLabel = label(pickFace, selected and "SELECTED" or "SELECT", 0, 0, 66, 18, 7.5, C.text, FB, CENTER)
				pickLabel.ZIndex = 46
				pick.Activated:Connect(function()
					if pid ~= "" then
						addPlace(pid, tostring(g.name or ("Place " .. pid)))
						row.BackgroundColor3 = C.tintRed
						pickLabel.Text = "SELECTED"
					end
				end)
				y = y + 44
			end
			resultList.CanvasSize = UDim2.fromOffset(578, math.max(y, 1))
		end)
	end
	renderAssign = function()
		for _, c in ipairs(assignList:GetChildren()) do
			if c:IsA("GuiObject") then
				c:Destroy()
			end
		end
		local options = {}
		for _, it in ipairs(CROZIX.builtinScripts()) do
			options[#options + 1] = { ref = "b:" .. it.id, name = it.name, tag = "BUILT-IN" }
		end
		local names = {}
		for name in pairs(saved) do
			names[#names + 1] = name
		end
		table.sort(names)
		for _, name in ipairs(names) do
			options[#options + 1] = { ref = "s:" .. name, name = name, tag = "SAVED" }
		end
		local y = 0
		for _, op in ipairs(options) do
			local on = false
			for _, r in ipairs(editorState.refs) do
				if r == op.ref then
					on = true
				end
			end
			local row = plate(assignList, 0, y, 578, 40, on and C.tintRed or C.card, 8, 0, on and C.red or C.line, 0.4)
			row.ZIndex = 43
			local box = plate(row, 6, 13, 14, 14, on and C.red or C.card2, 4, 0, C.line, 0.4)
			box.ZIndex = 44
			if on then
				mk("check", box, 10, C.text, C.red, UDim2.fromOffset(2, 2)).Root.ZIndex = 45
			end
			label(row, op.name, 28, 0, 330, 40, 9.5, C.text, FB).ZIndex = 44
			label(row, op.tag, 400, 0, 100, 40, 8, C.muted, FM).ZIndex = 44
			local hit = new("TextButton", {
				Text = "",
				BackgroundTransparency = 1,
				Size = UDim2.fromOffset(578, 44),
				ZIndex = 46,
				Parent = row,
			})
			hit.Activated:Connect(function()
				if on then
					for i, r in ipairs(editorState.refs) do
						if r == op.ref then
							table.remove(editorState.refs, i)
							break
						end
					end
				else
					editorState.refs[#editorState.refs + 1] = op.ref
				end
				renderAssign()
			end)
			y = y + 44
		end
		assignCount.Text = tostring(#editorState.refs) .. " assigned"
		assignList.CanvasSize = UDim2.fromOffset(578, math.max(y, 1))
	end
	openEditor = function(cf)
		editorState = {
			id = cf and cf.id or ("ae_" .. tostring(os.time())),
			name = cf and cf.name or "",
			scope = cf and cf.scope or "all",
			enabled = cf and cf.enabled or true,
			places = copyList(cf and cf.places),
			placeNames = copyList(cf and cf.placeNames),
			refs = copyList(cf and cf.refs),
			existing = cf ~= nil,
		}
		edTitle.Text = cf and "Edit configuration" or "New configuration"
		edName.Text = editorState.name
		edErr.Text = ""
		syncScope()
		syncPlaces()
		renderAssign()
		-- A ScrollingFrame keeps its CanvasPosition between opens, so a form closed while scrolled to
		-- its footer came back showing the footer: on the tablet the section steps and the name field
		-- were off-screen. Every open starts at the top of the sheet.
		edScroll.CanvasPosition = Vector2.new(0, 0)
		editorLayer.Visible = true
	end
	saveEditor = function()
		local name = string.gsub(edName.Text, "^%s+", "")
		name = string.gsub(name, "%s+$", "")
		if name == "" then
			edErr.Text = "The configuration needs a name."
			return
		end
		if editorState.scope == "specific" and #editorState.places == 0 then
			edErr.Text = "Select at least one experience, or switch to All Experiences."
			return
		end
		if #editorState.refs == 0 then
			edErr.Text = "Assign at least one script."
			return
		end
		editorState.name = name
		local ok, why = aePersistSave()
		if not ok then
			edErr.Text = "Not saved: " .. tostring(why)
			return
		end
		editorLayer.Visible = false
		refreshAutoExec()
		notify("Configuration \"" .. name .. "\" saved.", C.green)
	end
	aePersistSave = function()
		if editorState.existing then
			for i, cf in ipairs(configs) do
				if cf.id == editorState.id then
					configs[i] = editorState
					break
				end
			end
		else
			configs[#configs + 1] = editorState
		end
		return aePersist()
	end

	------------------------------------------------------------------
	-- BOOT: run matching enabled configurations through the real executor
	------------------------------------------------------------------
	local ran = false
	local function runAutoExec()
		if ran then
			return 0
		end
		ran = true
		local place = tostring(game.PlaceId)
		local fired = 0
		for _, cf in ipairs(configs) do
			if cf.enabled then
				local match = cf.scope == "all"
				if not match then
					for _, p in ipairs(cf.places) do
						if p == place then
							match = true
						end
					end
				end
				if match then
					for _, r in ipairs(cf.refs) do
						local kind, key = resolveRef(r)
						if kind == "builtin" then
							if CROZIX.runBuiltin(key) then
								fired = fired + 1
							end
						elseif kind == "saved" and saved[key] ~= nil then
							CROZIX.runCode(saved[key], key)
							fired = fired + 1
						else
							notify("AutoExec: \"" .. refLabel(r) .. "\" is unavailable.", C.amber)
						end
					end
				end
			end
		end
		if fired > 0 then
			notify(string.format("AutoExec ran %d script(s).", fired), C.green)
		end
		return fired
	end
	CROZIX.autoExecRun = runAutoExec
	CROZIX.autoExecConfigs = function()
		return configs
	end
	task.defer(runAutoExec)

	renderBuiltin()
	refreshSaved()
	refreshAutoExec()
	setTab(1)
end

