------------------------------------------------------------------
-- BOOT: edge glow -> logo -> key screen
------------------------------------------------------------------
local function waitForAssets(minT, maxT)
	local list = { Gui }
	for _, v in pairs(Config.Icons) do
		if v ~= "" then
			list[#list + 1] = v
		end
	end
	if Config.LogoImage ~= "" then
		list[#list + 1] = Config.LogoImage
	end
	for _, v in ipairs(Config.Preload) do
		list[#list + 1] = v
	end
	-- "It was loading" is only a claim if the wait is measured. This counts the items handed to
	-- PreloadAsync, times the call itself, and times the whole gate, then writes all three to a marker
	-- the harness reads -- so the glow is backed by numbers instead of by a timer that always fires.
	local done, took = false, 0
	task.spawn(function()
		local t0 = os.clock()
		pcall(function()
			ContentProvider:PreloadAsync(list)
		end)
		took = os.clock() - t0
		done = true
	end)
	local t0 = os.clock()
	while true do
		local el = os.clock() - t0
		local ok, r = pcall(Config.IsEngineReady)
		local engine = (not ok) or r ~= false
		if el >= maxT or (el >= minT and done and engine) then
			break
		end
		task.wait(0.05)
	end
	local waited = (os.clock() - t0) * 1000
	CROZIX.preload = string.format(
		"items=%d decode=%.0fms gate=%.0fms min=%.0fms cap=%.0fms done=%s",
		#list, took * 1000, waited, minT * 1000, maxT * 1000, tostring(done))
	pcall(writefile, "Crozix/preload.txt", CROZIX.preload .. "\n")
end

-- red light that travels around the DEVICE screen edges
local function createGlow()
	local G = new("Frame", { Name = "Glow", Size = UDim2.fromScale(1, 1), ZIndex = 100, Parent = Gui })
	-- Five passes instead of three: a 2px bright core, then 8 / 18 / 34 / 54 px halos that fade out.
	-- Stacking translucent wide layers is what makes a light look like it glows on a game screen
	-- without needing a blur, which Roblox cannot do on a Frame.
	local layers = {
		{ th = 2, minT = 0.0 },
		{ th = 8, minT = 0.34 },
		{ th = 18, minT = 0.6 },
		{ th = 34, minT = 0.78 },
		{ th = 54, minT = 0.9 },
	}
	local rots = { 0, 90, 180, 270 }
	local grads = {}
	for _, L in ipairs(layers) do
		for i = 1, 4 do
			local props = { BackgroundTransparency = 0, BackgroundColor3 = T.Stroke, Parent = G }
			if i == 1 then
				props.Size = UDim2.new(1, 0, 0, L.th)
			elseif i == 2 then
				props.AnchorPoint = Vector2.new(1, 0)
				props.Position = UDim2.fromScale(1, 0)
				props.Size = UDim2.new(0, L.th, 1, 0)
			elseif i == 3 then
				props.AnchorPoint = Vector2.new(0, 1)
				props.Position = UDim2.fromScale(0, 1)
				props.Size = UDim2.new(1, 0, 0, L.th)
			else
				props.Size = UDim2.new(0, L.th, 1, 0)
			end
			local f = new("Frame", props)
			local g = new("UIGradient", { Rotation = rots[i], Parent = f })
			grads[#grads + 1] = { g = g, edge = i, layer = L }
		end
	end

	local ctl = { fade = 0 }
	function ctl.layout()
		local vp = Gui.AbsoluteSize
		local lens = { vp.X, vp.Y, vp.X, vp.Y }
		local spot = math.max(vp.X, vp.Y) * 0.52
		for _, e in ipairs(grads) do
			local w = math.clamp(spot / math.max(lens[e.edge], 1), 0.05, 0.9)
			local a = 0.5 - w / 2
			local minT = 1 - (1 - e.layer.minT) * (1 - ctl.fade)
			e.g.Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1),
				NumberSequenceKeypoint.new(a, 1),
				NumberSequenceKeypoint.new(0.5, minT),
				NumberSequenceKeypoint.new(1 - a, 1),
				NumberSequenceKeypoint.new(1, 1),
			})
		end
	end
	function ctl.step()
		local vp = Gui.AbsoluteSize
		local lens = { vp.X, vp.Y, vp.X, vp.Y }
		local starts = { 0, vp.X, vp.X + vp.Y, 2 * vp.X + vp.Y }
		local P = 2 * (vp.X + vp.Y)
		local s = (os.clock() * (P / 2.1)) % P
		for _, e in ipairs(grads) do
			local cp = ((s - starts[e.edge] + P / 2) % P) - P / 2
			local c = cp / math.max(lens[e.edge], 1)
			e.g.Offset = Vector2.new(math.clamp(c - 0.5, -1, 1), 0)
		end
	end
	ctl.layout()
	ctl.stepConn = RunService.RenderStepped:Connect(ctl.step)
	ctl.sizeConn = Gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(ctl.layout)
	function ctl.fadeOut(dur)
		local t0 = os.clock()
		while true do
			local a = (os.clock() - t0) / dur
			if a >= 1 then
				break
			end
			ctl.fade = a
			ctl.layout()
			task.wait()
		end
		ctl.destroy()
	end
	function ctl.destroy()
		ctl.stepConn:Disconnect()
		ctl.sizeConn:Disconnect()
		G:Destroy()
	end
	return ctl
end

