	})
	new("TextLabel", {
		Text = "Pick a duration, open the link, then paste your key below.",
		TextSize = 11,
		TextColor3 = T.Muted,
		TextWrapped = true,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextYAlignment = Enum.TextYAlignment.Top,
		Position = UDim2.fromOffset(18, 36),
		Size = UDim2.fromOffset(260, 28),
		Parent = CardGroup,
	})

	local selected = "24h"
	local chips = {}
	local function selectDuration(id)
		selected = id
		for cid, c in pairs(chips) do
			local on = cid == id
			tw(c.btn, 0.15, {
				BackgroundColor3 = on and T.Accent or T.Card,
				BackgroundTransparency = on and 0.1 or 0.25,
			})
			tw(c.stroke, 0.15, { Color = on and lighten(T.Accent, 0.5) or T.StrokeSoft })
			c.small.TextColor3 = on and T.Text or T.Muted
		end
	end
	for i, opt in ipairs(KEY_OPTIONS) do
		local chip = new("TextButton", {
			Position = UDim2.fromOffset(18 + (i - 1) * 90, 72),
			Size = UDim2.fromOffset(82, 46),
			BackgroundTransparency = 0.25,
			BackgroundColor3 = T.Card,
			Parent = CardGroup,
		})
		corner(chip, CROZIX.D.R.SM)
		local cs = stroke(chip, T.StrokeSoft, 1, 0.2)
		new("TextLabel", {
			Text = opt.big,
			Font = Enum.Font.GothamBlack,
			TextSize = CROZIX.D.TYPE.Section,
			Position = UDim2.fromOffset(0, 5),
			Size = UDim2.new(1, 0, 0, 20),
			Parent = chip,
		})
		local small = new("TextLabel", {
			Text = opt.small,
			TextSize = 11,
			TextColor3 = T.Muted,
			Position = UDim2.fromOffset(0, 25),
			Size = UDim2.new(1, 0, 0, 14),
			Parent = chip,
		})
		chips[opt.id] = { btn = chip, stroke = cs, small = small }
		chip.Activated:Connect(function()
			selectDuration(opt.id)
		end)
	end
	selectDuration("24h")

	local LinkBtn = iconButton(CardGroup, "Get Key Link", "link", T.Card, UDim2.fromOffset(260, CROZIX.D.HIT), UDim2.fromOffset(18, 126), nil, 14, 12)
	local _, KeyBox = inputBox(CardGroup, UDim2.fromOffset(18, 176), UDim2.fromOffset(260, CROZIX.D.HIT), "key", "Enter your key")
	local KeyInputFrame = KeyBox.Parent
	local LoginBtn = iconButton(CardGroup, "Login", "arrow", T.Accent, UDim2.fromOffset(260, CROZIX.D.HIT), UDim2.fromOffset(18, 226), nil, 14, 13)
	new("TextLabel", {
		Text = "No key yet? Choose a duration and tap Get Key Link.",
		TextSize = 11,
		TextColor3 = T.Muted,
		Position = UDim2.fromOffset(0, 274),
		Size = UDim2.new(1, 0, 0, 12),
		Parent = CardGroup,
	})

	LinkBtn.Activated:Connect(function()
		local link = Config.KeyLinks[selected] or ""
		if Config.OnGetKey then
			pcall(Config.OnGetKey, selected, link)
		end
		local copied = pcall(function()
			setclipboard(link)
		end)
		if copied then
			keyNotify("Key link copied", T.Green)
		else
			keyNotify(link, T.Accent, 5)
		end
	end)

	local busy = false
	local function shake()
		task.spawn(function()
			local base = KeyInputFrame.Position
			for _, o in ipairs({ -7, 7, -5, 5, 0 }) do
				tween(KeyInputFrame, 0.05, { Position = UDim2.new(base.X.Scale, base.X.Offset + o, base.Y.Scale, base.Y.Offset) })
				task.wait(0.05)
			end
		end)
	end
	local function tryLogin()
		if busy then
			return
		end
		local key = (KeyBox.Text:gsub("%s+", ""))
		if key == "" then
			keyNotify("Enter your key first", T.Yellow)
			shake()
			return
		end
		local ok, msg = validKey(key)
		if ok then
			busy = true
			keyNotify("Key accepted", T.Green)
			if Config.SaveKey then
				pcall(Config.SaveKey, key)
			end
			task.delay(0.45, function()
				loginEvent:Fire()
			end)
		else
			keyNotify(msg or "Invalid key", T.Red)
			shake()
		end
	end
	LoginBtn.Activated:Connect(tryLogin)
	KeyBox.FocusLost:Connect(function(enter)
		if enter then
			tryLogin()
		end
	end)

	-- red edge fade + flash
	local Flash = new("Frame", {
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		BackgroundColor3 = T.Accent,
		ZIndex = 3,
		Parent = Gui,
	})
	task.spawn(function()
		glow.fadeOut(0.6)
	end)

	-- logo intro (centre)
	tween(emblemScale, 0.55, { Scale = 1 }, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
	tween(Emblem, 0.65, { Rotation = 0 }, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
	task.wait(0.3)
	Flash.BackgroundTransparency = 0.8
	tween(Flash, 0.5, { BackgroundTransparency = 1 })
	pulse.Visible = true
	tween(pulse, 0.7, { Size = UDim2.fromOffset(160, 160) })
	tween(pulseStroke, 0.7, { Transparency = 1 })
	TitleLabel.Position = UDim2.fromOffset(0, 158)
	tween(TitleLabel, 0.4, { TextTransparency = 0, Position = UDim2.fromOffset(0, 146) }, Enum.EasingStyle.Quart)
	task.wait(0.15)
	tween(TitleLine, 0.45, { Size = UDim2.fromOffset(140, 2) }, Enum.EasingStyle.Quart)
	task.wait(0.15)
	tween(SubLabel, 0.4, { TextTransparency = 0 })
	task.wait(0.75)

	-- logo moves aside, key card appears
	tween(Logo, 0.65, { Position = UDim2.new(0.25, 0, 0.5, 0) }, Enum.EasingStyle.Quart, Enum.EasingDirection.InOut)
	task.wait(0.3)
	CardGroup.Position = UDim2.fromOffset(372, 15)
	tween(CardGroup, 0.5, { GroupTransparency = 0, Position = UDim2.fromOffset(292, 15) }, Enum.EasingStyle.Quart)

	loginEvent.Event:Wait()

	-- finish: fade everything out, then reveal the sections
	tween(CardGroup, 0.3, { GroupTransparency = 1, Position = UDim2.fromOffset(312, 15) })
	tween(Logo, 0.3, { GroupTransparency = 1 })
	tween(Backdrop, 0.45, { BackgroundTransparency = 1 })
	task.wait(0.45)
	KeyRoot:Destroy()
	Backdrop:Destroy()
	Flash:Destroy()
	revealMain()
end

------------------------------------------------------------------
-- START
------------------------------------------------------------------
task.spawn(function()
	-- No real key server is wired, so there is no authentication to perform: open the panel directly
	-- (local mode) rather than gate it behind a client-side check that proves nothing. When
	-- Config.KeyBackend is set, a saved key is validated against it and everyone else sees the key screen.
	if not Config.KeyBackend then
		waitForAssets(0.3, 2)
		revealMain()
		return
	end
	local okS, savedKey = pcall(Config.LoadSavedKey)
	if okS and type(savedKey) == "string" and savedKey ~= "" and validKey(savedKey) then
		waitForAssets(0.3, 2)
		revealMain()
	else
		bootSequence()
	end
end)
end

CROZIX.buildLoader()
CROZIX.step("client")
local okBuild, errBuild = pcall(CROZIX_BUILD)
CROZIX.step("ui")
CROZIX.finish(okBuild, errBuild)
if not okBuild then
	warn("[Crozix] v6 UI did not build: " .. tostring(errBuild))
end

local function window()
	if CROZIX.gui then
		return CROZIX.gui
	end
	local ok, gui = pcall(function()
		return CROZIX.hub():FindFirstChild("CrozixMainUI")
	end)
	return ok and gui or nil
end

-- After window() exists, not before: calling it above its own definition killed the chunk here.
local HOT = {
	"CrozixFab", "CrozixPower", "CrozixBox", "CrozixExec", "CrozixClear", "CrozixAuto", "CrozixSave", "CrozixDialog",
	"CrozixSlider_InterfaceSize", "CrozixSlider_Transparency",
	"CrozixSide_code", "CrozixSide_search", "CrozixSide_save", "CrozixSide_ai", "CrozixSide_extensions",
	"CrozixSide_settings", "CrozixSide_output", "CrozixOutCopy", "CrozixOutClear",
	"RobloxOutCopy", "RobloxOutClear", "CrozixProtAntiAfk", "CrozixProtAntiScam",
	"CrozixProtDisableRobux", "CrozixProtVerifyTeleports", "TopBar",
}
CROZIX.panelNames = HOT
-- Opening a pane that was hidden at boot has to re-take the map, because a hidden widget gives the
-- engine no hit-test geometry. The body cannot reach window(), so the tail hands it this one call.
CROZIX.report = function()
	CROZIX.hotspots(window(), HOT)
	CROZIX.tapmap(HOT)
end
CROZIX.hotspots(window(), HOT)
-- The reveal, the layout and the UIScale all settle a moment after the build returns, so the geometry
-- and the hit-map are taken once that has happened. The first hotspots call above is the fallback if
-- the panel never gets revealed at all.
task.spawn(function()
	-- Wait until the window is really on screen, i.e. past the key. A hit-map taken while the window is
	-- hidden finds nothing, because a hidden widget is not hit-testable.
	local root = nil
	for _ = 1, 2400 do
		root = CROZIX.hot and CROZIX.hot.CrozixRoot
		local shown = false
		pcall(function()
			shown = root ~= nil and root.Visible == true
		end)
		if shown then
			break
		end
		task.wait(0.25)
	end
	task.wait(1.5)
	-- The state the player left behind is written down, and the start-up script runs, once the panel is
	-- actually up. Not before: a script that runs before the key is accepted runs without the player.
	if CROZIX.settings and CROZIX.root then
		CROZIX.saveSettings(CROZIX.settings, CROZIX.root)
	end
-- AutoExec is a press, not a boot side effect: nothing here runs the folder on its own.
	CROZIX.hotspots(window(), HOT)
	CROZIX.tapmap(HOT)
	-- The brand sweep goes last, and it is a sweep with a witness: by now the panel is up, so every
	-- read the engine’s own chunk made already resolved through the Crozix aliases the loader
	-- published at the entry site. What it removes and what it leaves is written to disk.
	pcall(CROZIX.hideVendorNames)
	-- The hook guard is published in the same place the vendor names are hidden: after the panel is
	-- up, in the environment the player's scripts will run in.
	pcall(CROZIX.guardNamecallHook)
end)

return {
	VERSION = CROZIX.VERSION,
	SOURCE_MD5 = CROZIX.SOURCE_MD5,
	built = okBuild,
	error = errBuild,
	aliasHits = CROZIX.aliasHits or 0,
	ui = { root = window, widgets = function() return {} end },
}
